globalThis.DECKOMANTIK_RULES={"version":1,"pageCount":39,"sources":{"en":"https://www.kartomantik.com/files/en/kartomantik_Rulebook.pdf","it":"https://www.kartomantik.com/files/it/Regole_kartomantik.pdf","learn":"https://www.kartomantik.com/en/learn","codex":"https://www.kartomantik.com/en/codex"},"chapters":[{"id":"contents","pages":[2,3],"title":{"fr":"Sommaire","en":"Contents","it":"Indice"},"summary":{"fr":"Le plan complet du livret officiel.","en":"The complete map of the official rulebook.","it":"La mappa completa del regolamento ufficiale."}},{"id":"introduction","pages":[4,4],"title":{"fr":"Bienvenue dans la Kartomancie","en":"Welcome to Kartomancy","it":"Benvenuti nella Cartomanzia"},"summary":{"fr":"Le monde de jeu et le rôle des Kartomanciens.","en":"The game world and the role of Kartomancers.","it":"Il mondo di gioco e il ruolo dei Cartomanti."}},{"id":"basics","pages":[5,8],"title":{"fr":"Bases et cartes","en":"The Basics & Cards","it":"Le basi e le carte"},"summary":{"fr":"Tempéraments, matériel, Manifestations et Volontés.","en":"Temperaments, game contents, Manifestations and Wills.","it":"Umori, contenuto, Manifestazioni e Volontà."}},{"id":"zones","pages":[9,9],"title":{"fr":"Zones de jeu","en":"Game Zones","it":"Aree di gioco"},"summary":{"fr":"Champ cartomantique, Zone de Confrontation, Interzone, Limbes, Réceptacle empathique et Zone d’Impasse.","en":"Cartomantic Field, Confrontation, Interzone, Limbo and Empathic Vessel.","it":"Campo Cartomantico, Confronto, Interzona, Limbo e Bacino Empatico."}},{"id":"turn-overview","pages":[10,10],"title":{"fr":"Vue d’ensemble du tour","en":"Turn Overview","it":"Panoramica del turno"},"summary":{"fr":"Un aperçu rapide des phases et de la résolution d’un tour.","en":"A quick overview of the phases and resolution of a turn.","it":"Una rapida panoramica delle fasi e della risoluzione del turno."}},{"id":"tribute","pages":[11,12],"title":{"fr":"Payer un Tribut","en":"How to Pay a Tribute","it":"Pagare un Tributo"},"summary":{"fr":"Coûts de Volonté, Manifestations, Tempéraments et Essence excédentaire.","en":"Will costs, Manifestations, Temperaments and Excess Essence.","it":"Costi delle Volontà, Manifestazioni, Umori ed Essenza in eccesso."}},{"id":"priority-stack","pages":[13,16],"title":{"fr":"Priorité et Pile","en":"Priority & Stack","it":"Priorità e Pila"},"summary":{"fr":"Qui peut agir, comment répondre et dans quel ordre les effets se résolvent.","en":"Who can act, how to respond, and the order in which effects resolve.","it":"Chi può agire, come rispondere e in quale ordine si risolvono gli effetti."}},{"id":"effects","pages":[17,20],"title":{"fr":"Comprendre les effets","en":"Understanding Cards & Effects","it":"Comprendere carte ed effetti"},"summary":{"fr":"Effets activés, déclenchés, passifs et immédiats, Soutien et lecture du texte.","en":"Activated, Triggered, Passive and Immediate effects, Support, and reading card text.","it":"Effetti Attivati, Innescati, Passivi e Immediati, Supporto e lettura del testo."}},{"id":"deckbuilding","pages":[21,22],"title":{"fr":"Construire un deck","en":"Building a Deck","it":"Costruire un mazzo"},"summary":{"fr":"30 cartes uniques, jusqu’à 500 points de Manifestations, exemples de decks de départ.","en":"30 unique cards, up to 500 Manifestation points, and starter deck examples.","it":"30 carte uniche, fino a 500 punti Manifestazione ed esempi di mazzi iniziali."}},{"id":"turn-structure","pages":[23,29],"title":{"fr":"Structure du tour","en":"Turn Structure","it":"Struttura del turno"},"summary":{"fr":"Récupération, Confrontation, Résolution et Fin, avec un tour d’exemple.","en":"Recovery, Confrontation, Resolution and End, with a complete example turn.","it":"Recupero, Confronto, Risoluzione e Fine, con un turno di esempio completo."}},{"id":"end-game","pages":[30,30],"title":{"fr":"Fin et calcul des points","en":"End of Game & Points","it":"Fine della partita e punti"},"summary":{"fr":"Conditions de fin et calcul du score dans le Réceptacle Empathique.","en":"End conditions and scoring the Empathic Vessel.","it":"Condizioni di fine partita e calcolo del Bacino Empatico."}},{"id":"multiplayer","pages":[31,34],"title":{"fr":"Multijoueur","en":"Multiplayer","it":"Multigiocatore"},"summary":{"fr":"Mêlée générale et affrontement en équipes de deux.","en":"Free-for-All and Two-versus-Two team play.","it":"Tutti contro tutti e gioco a squadre due contro due."}},{"id":"bazaar","pages":[35,37],"title":{"fr":"Draft du Bazar","en":"Bazaar Draft","it":"Draft del Bazaar"},"summary":{"fr":"Préparation, sélection et construction d’un deck en draft.","en":"Setup, card selection and deck construction in draft play.","it":"Preparazione, selezione e costruzione del mazzo in modalità draft."}},{"id":"keywords","pages":[38,39],"title":{"fr":"Mots-clés","en":"Keywords","it":"Parole chiave"},"summary":{"fr":"Le glossaire officiel des actions et états de jeu.","en":"The official glossary of game actions and states.","it":"Il glossario ufficiale delle azioni e degli stati di gioco."}},{"id":"errata","pages":[39,39],"textOnly":true,"title":{"fr":"Intégrations et erratum","en":"Integrations & Errata","it":"Integrazioni ed errata"},"summary":{"fr":"Précisions, corrections et textes de cartes mis à jour, regroupés à la fin de la référence.","en":"Clarifications, corrections and updated card text, grouped at the end of the reference.","it":"Chiarimenti, correzioni e testi aggiornati delle carte."}}],"termRoutes":{"about_to":["effects",19],"currently":["effects",19],"immediate_effect":["effects",17],"field":["zones",9],"confrontation_zone":["zones",9],"interzone":["zones",9],"limbo":["zones",9],"empathic_vessel":["zones",9],"stalemate_zone":["zones",9],"controller":["effects",19],"owner":["effects",19],"base_power":["effects",19],"modifier":["effects",19],"counter":["effects",19],"points":["end-game",30],"token":["effects",20],"target":["effects",19],"first_manifestation":["turn-structure",24],"in_support":["effects",18],"support":["effects",18],"persist":["effects",18],"ephemeral_wills":["effects",17],"persistent_wills":["effects",17],"immunity":["keywords",38],"protection":["keywords",38],"cancel":["keywords",38],"chain":["keywords",38],"conceal":["keywords",38],"copy":["keywords",38],"destroy":["keywords",38],"discard":["keywords",38],"exhaust":["keywords",38],"exile":["keywords",39],"neutralize":["keywords",39],"restore":["keywords",39],"sacrifice":["keywords",39],"show":["keywords",39],"uncover":["keywords",39],"tribute":["tribute",11],"essence":["tribute",11]},"terms":[{"id":"about_to","forms":{"en":["about to"],"it":["sta per"],"fr":["sur le point de"]},"description":{"en":"A special timing that interrupts the normal flow of the game to apply effects, just before the event that is \"about to\" happen occurs.","it":"Un tempismo speciale che interrompe il normale svolgimento del gioco per applicare degli effetti, appena prima che l'evento che \"sta per\" accadere si verifichi.","fr":"Un timing spécial qui interrompt le déroulement normal du jeu pour appliquer des effets, juste avant que l’événement annoncé se produise."},"chapterId":"effects","page":19},{"id":"currently","forms":{"en":["currently"],"it":["attualmente"],"fr":["actuellement"]},"description":{"en":"At the moment in which the card or effect resolves on the Stack.","it":"Nel momento in cui la carta o l'effetto si risolve in Pila.","fr":"Au moment où la carte ou l’effet se résout dans la Pile."},"chapterId":"effects","page":19},{"id":"immediate_effect","forms":{"en":["immediate effect"],"it":["effetto immediato"],"fr":["effet immédiat","effets immédiats"]},"description":{"en":"An effect to which it is not possible to respond; it resolves on the Stack with priority over other effects. If an Immediate Effect triggers at Revelation, it triggers and resolves on the Stack before other Triggered effects have the opportunity to enter the Stack.","it":"Un effetto al quale non è possibile rispondere, si risolve in Pila in modo prioritario rispetto agli altri effetti. Se un effetto Immediato si innesca alla Rivelazione, questo si innesca e risolve in Pila prima che gli altri effetti Innescati abbiano l'opportunità di entrare in Pila.","fr":"Un effet auquel il est impossible de répondre : il se résout dans la Pile avant les autres effets. À la Révélation, il se déclenche et se résout avant que les autres effets déclenchés puissent entrer dans la Pile."},"chapterId":"effects","page":17},{"id":"field","forms":{"en":["field","cartomantic field"],"it":["campo","campo cartomantico"],"fr":["champ","champ cartomantique"]},"description":{"en":"The Cartomantic Field, the game zone that comprises the Interzone, the Confrontation, and in which played Persistent Wills are placed.","it":"Il Campo Cartomantico, area di gioco che comprende l'Interzona, il Confronto, e nel quale vengono posizionate le Volontà Persistenti giocate.","fr":"Le Champ cartomantique comprend l’Interzone, la Confrontation et l’emplacement où sont posées les Volontés persistantes jouées."},"chapterId":"zones","page":9},{"id":"confrontation_zone","forms":{"en":["confrontation zone"],"it":["area di confronto"],"fr":["zone de confrontation"]},"description":{"en":"Shared zone where all manifestations that are played and put into the Confrontation are placed.","it":"Area condivisa dove vengono messe tutte le manifestazioni che vengono giocate e messe nel Confronto.","fr":"Zone partagée où sont placées toutes les Manifestations jouées ou mises en Confrontation."},"chapterId":"zones","page":9},{"id":"interzone","forms":{"en":["interzone"],"it":["interzona"],"fr":["interzone"]},"description":{"en":"Zone where the player can place up to 3 of their Manifestations that have won a Confrontation to continue exploiting their effects as Support, or passive and triggered effects that require the manifestation to be \"on the field\". Those Manifestations can be replaced by putting them at the bottom of one's Deck every time another one would enter.","it":"Area dove il giocatore può posizionare fino a 3 sue Manifestazioni che hanno vinto un Confronto per continuare a sfruttarne gli effetti come Supporto, o gli effetti passivi e innescati che richiedono alla manifestazione di trovarsi \"in campo\". Quelle Manifestazioni possono essere sostituite mettendole in fondo al proprio Mazzo ogni volta ne entrerebbe un'altra.","fr":"Zone où un joueur peut conserver jusqu’à 3 Manifestations ayant remporté une Confrontation afin de continuer à exploiter leurs effets de Soutien, passifs ou déclenchés."},"chapterId":"zones","page":9},{"id":"limbo","forms":{"en":["limbo"],"it":["limbo"],"fr":["limbes","limbo"]},"description":{"en":"Zone where resolved Ephemeral Wills, Manifestations used as a Tribute, and destroyed cards are placed.","it":"Zona dove vengono poste le Volontà Effimere risolte, le Manifestazioni usate come Tributo, e le carte distrutte.","fr":"Zone où sont placées les Volontés éphémères résolues, les Manifestations utilisées comme Tribut et les cartes détruites."},"chapterId":"zones","page":9},{"id":"empathic_vessel","forms":{"en":["empathic vessel"],"it":["bacino empatico"],"fr":["réceptacle empathique"]},"description":{"en":"Zone where the opposing Manifestations that have lost the Confrontation are accumulated.","it":"Zona dove vengono accumulate le Manifestazioni avversarie che hanno perso il Confronto.","fr":"Zone où s’accumulent les Manifestations adverses ayant perdu la Confrontation."},"chapterId":"zones","page":9},{"id":"stalemate_zone","forms":{"en":["stalemate zone"],"it":["zona di stallo"],"fr":["zone d’impasse","zone d'impasse"]},"description":{"en":"Special zone where the Manifestations involved in a Stalemate are placed. Controller and Modifiers remain unchanged.","it":"Area speciale dove vengono messe le Manifestazioni coinvolte in uno Stallo. Controllore e Modificatori rimangono invariati.","fr":"Zone spéciale où sont placées les Manifestations impliquées dans une Impasse. Leur contrôleur et leurs modificateurs ne changent pas."},"chapterId":"zones","page":9},{"id":"controller","forms":{"en":["controller","controllers"],"it":["controllore","controllori"],"fr":["contrôleur","contrôleurs","contrôle","contrôlez"]},"description":{"en":"The player who can play and activate the effects of the cards. If a player controls a card of which they are not the owner, when the card leaves the field or the Stalemate Zone, it returns under the control of its owner.","it":"Il giocatore che può giocare e attivare gli effetti delle carte. Se un giocatore controlla una carta di cui non è il proprietario, quando la carta lascia il campo o la Zona di Stallo, torna sotto il controllo del suo proprietario.","fr":"Le joueur qui peut jouer la carte et activer ses effets. Une carte contrôlée par un autre joueur revient sous le contrôle de son propriétaire lorsqu’elle quitte le Champ ou la Zone d’Impasse."},"chapterId":"effects","page":19},{"id":"owner","forms":{"en":["owner","owners"],"it":["proprietario","proprietari"],"fr":["propriétaire","propriétaires"]},"description":{"en":"You are always the Owner of all the cards that are in your deck at the beginning of the game.","it":"Sei sempre il Proprietario di tutte le carte che sono nel tuo mazzo all'inizio della partita.","fr":"Vous êtes toujours le propriétaire de toutes les cartes présentes dans votre deck au début de la partie."},"chapterId":"effects","page":19},{"id":"base_power","forms":{"en":["base power"],"it":["forza base"],"fr":["puissance de base"]},"description":{"en":"The power value printed on the card, before any modifier.","it":"Il valore di forza stampato sulla carta, prima di qualsiasi modificatore.","fr":"La valeur de puissance imprimée sur la carte, avant tout modificateur."},"chapterId":"effects","page":19},{"id":"modifier","forms":{"en":["modifier","modifiers"],"it":["modificatore","modificatori"],"fr":["modificateur","modificateurs"]},"description":{"en":"Any temporary or permanent change to the characteristics of a card (power, temperament, etc.) caused by an effect.","it":"Qualsiasi cambiamento temporaneo o permanente alle caratteristiche di una carta (forza, umore, ecc.) causato da un effetto.","fr":"Tout changement temporaire ou permanent apporté par un effet aux caractéristiques d’une carte, comme sa puissance ou son tempérament."},"chapterId":"effects","page":19},{"id":"counter","forms":{"en":["counter","counters"],"it":["segnalino","segnalini"],"fr":["marqueur","marqueurs"]},"description":{"en":"Object to mark changes given by effects on a card.","it":"Oggetto per segnare cambiamenti dati da effetti su di una carta.","fr":"Un objet utilisé pour signaler sur une carte un changement créé par un effet."},"chapterId":"effects","page":19},{"id":"points","forms":{"en":["point","points"],"it":["punto","punti"],"fr":["point","points"]},"description":{"en":"If not specified \"of a manifestation\", it refers to the points in the Empathic Vessel.","it":"Se non specificati \"di una manifestazione\" si fa riferimento ai punti nel Bacino Empatico.","fr":"Sans la précision « d’une Manifestation », le terme désigne les points présents dans le Réceptacle Empathique."},"chapterId":"end-game","page":30},{"id":"token","forms":{"en":["token","tokens"],"it":["pedina","pedine"],"fr":["jeton","jetons"]},"description":{"en":"A manifestation or a will created by the effects of other cards. If a token leaves the Cartomantic Field it is exiled. Unless specified otherwise, manifestation tokens are exiled at Resolution.","it":"Una manifestazione o una volontà creata da effetti di altre carte. Se una pedina lascia il Campo Cartomantico viene esiliata. Salvo diversa indicazione, le pedine manifestazione vengono esiliate alla Risoluzione.","fr":"Une Manifestation ou une Volonté créée par l’effet d’une autre carte. Un jeton qui quitte le Champ cartomantique est exilé ; sauf indication contraire, les jetons Manifestation sont exilés à la Résolution."},"chapterId":"effects","page":20},{"id":"target","forms":{"en":["target","targets","targeted","targeting"],"it":["bersaglio","bersagli","bersaglia","bersagliano","bersagliate","bersagliata","bersagliato","bersagliati","bersagliando"],"fr":["cible","cibles","cibler","ciblé","ciblée","ciblés","ciblées"]},"description":{"en":"The element (a card, a player, etc.) that the controller of the effect or card must choose for it to have an effect.","it":"L'elemento (una carta, un giocatore, ecc.) che il controllore dell'effetto o della carta deve scegliere perché abbia effetto.","fr":"L’élément — carte, joueur ou autre — que le contrôleur d’une carte ou d’un effet doit choisir pour que celui-ci agisse."},"chapterId":"effects","page":19},{"id":"first_manifestation","forms":{"en":["first manifestation"],"it":["prima manifestazione"],"fr":["première manifestation"]},"description":{"en":"The manifestation that was played at Revelation by its controller. If that card leaves the Confrontation, its controller must choose another of their manifestations in the Confrontation as the new First Manifestation. If a player controls no manifestations in the Confrontation Zone, at the moment they play or put a manifestation into Support, the latter enters as the First Manifestation.","it":"La manifestazione che è stata giocata alla Rivelazione dal suo controllore. Se quella carta lascia il Confronto, il suo controllore deve scegliere un'altra sua manifestazione nel Confronto come nuova Prima Manifestazione. Se un giocatore non controlla manifestazioni nell'Area di Confronto, nel momento in cui gioca o mette in Supporto una manifestazione, quest'ultima entra come Prima Manifestazione.","fr":"La Manifestation jouée à la Révélation par son contrôleur. Si elle quitte la Confrontation, son contrôleur doit choisir l’une de ses autres Manifestations en Confrontation comme nouvelle Première Manifestation."},"chapterId":"turn-structure","page":24},{"id":"in_support","forms":{"en":["in support"],"it":["in supporto"],"fr":["en soutien"]},"description":{"en":"Any manifestation that is in the Confrontation Zone, and entered while a First Manifestation was already present, is defined as \"in Support\".","it":"Una qualsiasi manifestazione che si trova nell'Area di Confronto, ed è entrata mentre era già presente una Prima Manifestazione, è definita \"in Supporto\".","fr":"Toute Manifestation qui entre dans la Zone de confrontation alors qu’une Première Manifestation est déjà présente est considérée comme « en Soutien »."},"chapterId":"effects","page":18},{"id":"support","forms":{"en":["support"],"it":["supporto"],"fr":["soutien"]},"description":{"en":"A manifestation with Support can enter the Confrontation, from the hand or from the Interzone, after the First Manifestation. If \"from the hand\" is specified, it can be played in Support exclusively from the hand.","it":"Una manifestazione con Supporto può entrare nel Confronto, dalla mano o dall'Interzona, dopo la Prima Manifestazione. Se specificato \"dalla mano\" può essere giocata in Supporto esclusivamente dalla mano.","fr":"Une Manifestation avec Soutien peut entrer en Confrontation depuis la main ou l’Interzone après la Première Manifestation. Si « depuis la main » est précisé, elle ne peut être jouée en Soutien que depuis la main."},"chapterId":"effects","page":18},{"id":"persist","forms":{"en":["persist"],"it":["persistere"],"fr":["ténacité"]},"description":{"en":"If a manifestation with Persist has won the confrontation, it remains in the Confrontation Zone as a First Manifestation.","it":"Se una manifestazione con Persistere ha vinto il confronto, rimane nell'Area di Confronto come Prima Manifestazione.","fr":"Si une Manifestation avec Ténacité remporte la Confrontation, elle reste dans la Zone de Confrontation comme Première Manifestation."},"chapterId":"effects","page":18},{"id":"ephemeral_wills","forms":{"en":["ephemeral will","ephemeral wills"],"it":["volontà effimera","volontà effimere"],"fr":["volonté éphémère","volontés éphémères"]},"description":{"en":"Cards that can be played by paying a tribute. They can be played in response after Revelation. Once their effect resolves on the Stack, they are moved to the Limbo.","it":"Carte che possono essere giocate pagando un tributo. Possono essere giocate in risposta dopo la Rivelazione. Una volta che il loro effetto si risolve in Pila, vengono spostate nel Limbo.","fr":"Cartes jouées en payant un Tribut, y compris en réponse après la Révélation. Une fois leur effet résolu dans la Pile, elles sont placées dans les Limbes."},"chapterId":"effects","page":17},{"id":"persistent_wills","forms":{"en":["persistent will","persistent wills"],"it":["volontà persistente","volontà persistenti"],"fr":["volonté persistante","volontés persistantes"]},"description":{"en":"Cards that can be played by paying a tribute. They can be played only on an empty Stack during the End Phase and, once they resolve on the Stack, they enter the field. As a requirement for the activation of their effects, all persistent wills must be on the field.","it":"Carte che possono essere giocate pagando un tributo. Possono essere giocate solo a Pila vuota durante la Fase Finale e, una volta che si risolvono in Pila, entrano in campo. Come requisito per l'attivazione dei loro effetti, tutte le volontà persistenti devono essere in campo.","fr":"Cartes jouées en payant un Tribut uniquement sur une Pile vide pendant la Phase de fin. Une fois résolues, elles entrent sur le Champ, où elles doivent se trouver pour activer leurs effets."},"chapterId":"effects","page":17},{"id":"immunity","forms":{"en":["immunity","immune"],"it":["immunità","immune","immuni"],"fr":["immunité","immunisé","immunisée","immunisés","immunisées"]},"description":{"en":"Immune cards and players are not influenced in any way by the specified source.","it":"Le carte e i giocatori Immuni non sono influenzati in alcun modo dalla fonte specificata.","fr":"Une carte ou un joueur immunisé n’est influencé d’aucune manière par la source indiquée."},"chapterId":"keywords","page":38},{"id":"protection","forms":{"en":["protection","protected"],"it":["protezione","protetto","protetta","protetti","protette"],"fr":["protection","protégé","protégée","protégés","protégées"]},"description":{"en":"Protected cards and players cannot be chosen as targets by the specified source. Protected manifestations cannot obtain Modifiers from the specified source.","it":"Le carte e i giocatori Protetti non possono essere scelti come bersagli dalla fonte specificata. Le manifestazioni Protette non possono ottenere Modificatori dalla fonte specificata.","fr":"Une carte ou un joueur protégé ne peut pas être choisi comme cible par la source indiquée. Une Manifestation protégée ne peut pas recevoir de modificateurs de cette source."},"chapterId":"keywords","page":38},{"id":"cancel","forms":{"en":["cancel","cancels","canceled","cancelled","canceling","cancelling"],"it":["annullare","annulla","annulli","annullano","annullate","annullato","annullata","annullati","annullando"],"fr":["annuler","annule","annulé","annulée","annulés","annulées"]},"description":{"en":"Action that prevents an effect from resolving. A canceled effect cannot be resolved.","it":"Azione che impedisce a un effetto di risolversi. Un effetto annullato non può essere risolto.","fr":"Action qui empêche un effet de se résoudre. Un effet annulé ne peut pas être résolu."},"chapterId":"keywords","page":38},{"id":"chain","forms":{"en":["chain","chains","chained","chaining"],"it":["concatenare","concatena","concateni","concatenano","concatenate","concatenato","concatenata","concatenati","concatenando"],"fr":["enchaîner","enchaîne","enchaîné","enchaînée","enchaînés","enchaînées"]},"description":{"en":"Action that puts a manifestation under your control into Support. Once a Chained manifestation has entered the field, it is considered played and Chained.","it":"Azione che mette in Supporto una manifestazione sotto il tuo controllo. Una volta che una manifestazione Concatenata è entrata in campo, è considerata giocata e Concatenata.","fr":"Action qui place en Soutien une Manifestation sous votre contrôle. Après son entrée sur le Champ, elle est considérée comme jouée et Enchaînée."},"chapterId":"keywords","page":38},{"id":"conceal","forms":{"en":["conceal","conceals","concealed","concealing"],"it":["celare","cela","celi","celano","celate","celato","celata","celati","celando"],"fr":["dissimuler","dissimulé","dissimulée","dissimulés","dissimulées"]},"description":{"en":"A Concealed card is placed face-down in the zone specified by the effect. As long as it is Concealed, all its characteristics, except the Type, can be consulted only by its controller.","it":"Una carta Celata è posizionata coperta nella zona specificata dall'effetto. Finché è Celata, tutte le sue caratteristiche, tranne il Tipo, possono essere consultate solo dal suo controllore.","fr":"Une carte Dissimulée est posée face cachée dans la zone indiquée. Tant qu’elle est Dissimulée, seul son contrôleur peut consulter ses caractéristiques, à l’exception de son Type."},"chapterId":"keywords","page":38},{"id":"copy","forms":{"en":["copy","copies","copied","copying"],"it":["copiare","copia","copi","copie","copiano","copiate","copiato","copiata","copiati","copiando"],"fr":["copier","copie","copié","copiée","copiés","copiées"]},"description":{"en":"Action that creates a copy of a card. Unless specified otherwise, a copy has only the original printed characteristics of the copied card (name, temperament, cost, power, text) and does not inherit modifiers or counters. Copies are not considered Played.","it":"Azione che crea una copia di una carta. Salvo diversa indicazione, una copia ha solo le caratteristiche stampate originali della carta copiata (nome, umore, costo, forza, testo) e non eredita modificatori o segnalini. Le copie non sono considerate Giocate.","fr":"Action qui crée une copie d’une carte. Sauf indication contraire, la copie ne possède que les caractéristiques imprimées d’origine et n’hérite ni des modificateurs ni des marqueurs. Une copie n’est pas considérée comme jouée."},"chapterId":"keywords","page":38},{"id":"destroy","forms":{"en":["destroy","destroys","destroyed","destroying"],"it":["distruggere","distruggi","distrugge","distruggono","distruggete","distrutto","distrutta","distrutti","distrutte","distruggendo"],"fr":["détruire","détruit","détruite","détruits","détruites"]},"description":{"en":"Action that puts the affected card into its owner's Limbo. A destroyed card is in its owner's Limbo.","it":"Azione che mette la carta interessata nel Limbo del suo proprietario. Una carta distrutta si trova nel Limbo del suo proprietario.","fr":"Action qui place la carte concernée dans les Limbes de son propriétaire."},"chapterId":"keywords","page":38},{"id":"discard","forms":{"en":["discard","discards","discarded","discarding"],"it":["scartare","scarta","scarti","scartano","scartate","scartato","scartata","scartati","scartando"],"fr":["défausser","défausse","défaussé","défaussée","défaussés","défaussées"]},"description":{"en":"Action that puts the affected cards into the Limbo from the hand or from the deck. Discarded cards are in the Limbo.","it":"Azione che mette le carte interessate nel Limbo dalla mano o dal mazzo. Le carte scartate si trovano nel Limbo.","fr":"Action qui place dans les Limbes les cartes concernées depuis la main ou le deck."},"chapterId":"keywords","page":38},{"id":"exhaust","forms":{"en":["exhaust","exhausts","exhausted","exhausting"],"it":["esaurire","esaurisci","esaurisce","esauriscono","esaurite","esaurito","esaurita","esauriti","esaurendo"],"fr":["épuiser","épuisé","épuisée","épuisés","épuisées"]},"description":{"en":"Action that rotates the card horizontally. An Exhausted card cannot be Exhausted again until it is Restored, at the beginning of the turn or via effects.","it":"Azione che ruota la carta in orizzontale. Una carta Esaurita non può essere Esaurita di nuovo finché non viene Ripristinata, all'inizio del turno o per via di effetti.","fr":"Action qui tourne une carte à l’horizontale. Une carte Épuisée ne peut pas être Épuisée à nouveau avant d’être Restaurée au début du tour ou par un effet."},"chapterId":"keywords","page":38},{"id":"exile","forms":{"en":["exile","exiles","exiled","exiling"],"it":["esiliare","esilia","esili","esiliano","esiliate","esiliato","esiliata","esiliati","esiliando"],"fr":["exiler","exilé","exilée","exilés","exilées"]},"description":{"en":"Action that puts the card in its owner's exile zone, making it inaccessible for the rest of the game. An exiled card cannot return to play.","it":"Azione che mette la carta nella zona d'esilio del proprietario, rendendola non accessibile per il resto della partita. Una carta esiliata non può tornare in gioco.","fr":"Action qui place la carte dans la zone d’exil de son propriétaire, la rendant inaccessible pour le reste de la partie. Une carte exilée ne peut pas revenir en jeu."},"chapterId":"keywords","page":39},{"id":"neutralize","forms":{"en":["neutralize","neutralizes","neutralized","neutralizing"],"it":["neutralizzare","neutralizza","neutralizzi","neutralizzano","neutralizzate","neutralizzato","neutralizzata","neutralizzati","neutralizzando"],"fr":["neutraliser","neutralisé","neutralisée","neutralisés","neutralisées"]},"description":{"en":"Action that cancels the effect of the affected card and sends it to its owner's Limbo. A neutralized card has its effect canceled and is in its owner's Limbo.","it":"Azione che annulla l'effetto della carta interessata e la manda nel Limbo del proprietario. Una carta neutralizzata ha il suo effetto annullato e si trova nel Limbo del proprietario.","fr":"Action qui annule l’effet de la carte concernée et l’envoie dans les Limbes de son propriétaire."},"chapterId":"keywords","page":39},{"id":"restore","forms":{"en":["restore","restores","restored","restoring"],"it":["ripristinare","ripristina","ripristini","ripristinano","ripristinate","ripristinato","ripristinata","ripristinati","ripristinando"],"fr":["restaurer","restauré","restaurée","restaurés","restaurées"]},"description":{"en":"Action that returns an Exhausted card to a vertical position. A restored card can be Exhausted again.","it":"Azione che riporta una carta Esaurita in posizione verticale. Una carta ripristinata può essere nuovamente Esaurita.","fr":"Action qui remet une carte Épuisée en position verticale. Une carte Restaurée peut être Épuisée à nouveau."},"chapterId":"keywords","page":39},{"id":"sacrifice","forms":{"en":["sacrifice","sacrifices","sacrificed","sacrificing"],"it":["sacrificare","sacrifica","sacrifichi","sacrificano","sacrificate","sacrificato","sacrificata","sacrificati","sacrificando"],"fr":["sacrifier","sacrifié","sacrifiée","sacrifiés","sacrifiées"]},"description":{"en":"Action that puts your manifestation into the Limbo as the cost of an effect. A sacrificed manifestation is in the Limbo.","it":"Azione che mette la tua manifestazione nel Limbo come costo di un effetto. Una manifestazione sacrificata si trova nel Limbo.","fr":"Action qui place votre Manifestation dans les Limbes pour payer le coût d’un effet."},"chapterId":"keywords","page":39},{"id":"show","forms":{"en":["show","shows","showed","shown","showing"],"it":["mostrare","mostra","mostri","mostrano","mostrate","mostrato","mostrata","mostrati","mostrando"],"fr":["montrer","montre","montré","montrée","montrés","montrées"]},"description":{"en":"Action where you show the card (or cards) to your opponent and then put it back in its original zone, unless the effect specifies otherwise.","it":"Azione in cui mostri la carta (o le carte) al tuo avversario per poi rimetterla nella sua zona originale, a meno che l'effetto non specifichi diversamente.","fr":"Action qui montre une ou plusieurs cartes à l’adversaire avant de les replacer dans leur zone d’origine, sauf indication contraire."},"chapterId":"keywords","page":39},{"id":"uncover","forms":{"en":["uncover","uncovers","uncovered","uncovering"],"it":["scoprire","scopri","scopre","scoprono","scoprite","scoperto","scoperta","scoperti","scoperte","scoprendo"],"fr":["révéler","retourner face visible","révélé","révélée","révélés","révélées"]},"description":{"en":"Action that puts one or more cards face-up. An uncovered card has its characteristics visible.","it":"Azione che mette a faccia scoperta una o più carte. Una carta scoperta ha le sue caratteristiche visibili.","fr":"Action qui retourne une ou plusieurs cartes face visible. Les caractéristiques d’une carte Révélée sont visibles."},"chapterId":"keywords","page":39},{"id":"tribute","forms":{"en":["tribute","tributes"],"it":["tributo","tributi"],"fr":["tribut","tributs"]},"description":{"en":"A cost paid to play Wills or activate certain effects. Manifestations can be used as a Tribute only if an action specifically requires it.","it":"Un costo pagato per giocare Volontà o attivare determinati effetti. Le Manifestazioni possono essere usate in tributo solo nel caso un'azione lo richieda.","fr":"Un coût payé pour jouer des Volontés ou activer certains effets. Une Manifestation ne peut servir de Tribut que si une action l’exige explicitement."},"chapterId":"tribute","page":11},{"id":"essence","forms":{"en":["essence","essences","excess essence","excess essences"],"it":["essenza","essenze","essenza in eccesso","essenze in eccesso"],"fr":["essence","essences","essence excédentaire","essences excédentaires"]},"description":{"en":"A resource that can be used to pay Tributes, generated when the Manifestations used to pay a Tribute have a total base power higher than required. If a player has Excess Essence, it must always be used as priority for the payment of any Tribute that corresponds to its Temperament. Any Excess Essence not used by the end of the turn in which it was generated is lost. Excess Essence does not carry the effects of the manifestation from which it originated.","it":"Una risorsa che può essere usata per pagare Tributi, generata quando le Manifestazioni usate per pagare un Tributo hanno una forza base totale superiore a quella richiesta. Se un giocatore ha Essenze in Eccesso, queste vanno sempre usate in modo prioritario per pagare Tributi. Qualsiasi Essenza in Eccesso non utilizzata entro la fine del turno in cui è stata generata viene persa. L'Essenza in Eccesso non porta con sé gli effetti della Manifestazione da cui ha avuto origine.","fr":"Une ressource servant à payer des Tributs, créée lorsque la puissance de base totale des Manifestations utilisées dépasse le coût requis. L’Essence excédentaire correspondante doit être dépensée en priorité et disparaît à la fin du tour."},"chapterId":"tribute","page":11},{"id":"confrontation","forms":{"fr":["confrontation"],"en":["confrontation"],"it":["confronto"]},"description":{"fr":"L’affrontement qui commence à la Révélation et se termine à la Résolution. Il s’agit de l’événement de jeu, et non de la Zone de Confrontation.","en":"The contest that begins at Revelation and ends at Resolution. This is the game event, not the Confrontation Zone.","it":"Lo scontro che inizia alla Rivelazione e termina alla Risoluzione. È l’evento di gioco, non l’Area di Confronto."},"chapterId":"turn-structure","page":23}],"bookAvailable":{"fr":false,"en":true,"it":true},"textAvailable":{"fr":true,"en":true,"it":false},"text":{"fr":{"contents":[],"introduction":[{"type":"h2","text":"Introduction"},{"type":"callout","variant":"intro","text":"Kartomantik est un jeu né des cendres d'un monde désespéré."},{"type":"p","text":"C'est une invitation à faire une pause, à regarder l'autre dans les yeux et à poser sur la table ce que vous avez de plus précieux : votre âme."},{"type":"p","text":"C'est un jeu de cartes stratégique pour deux Cartomanciens, où vous façonnez votre deck à l'image de votre être. Chaque carte qu'il contient est un fragment de votre for intérieur, et les choix que vous faites en le construisant définissent qui vous êtes."},{"type":"p","text":"L'objectif n'est pas d'anéantir votre adversaire, mais de l'emporter dans les Confrontations : des échanges intenses où vos âmes se mesurent l'une à l'autre."},{"type":"p","text":"Chaque Confrontation commence lorsque vous révélez tous les deux simultanément une Première Manifestation : une impulsion, une peur, une passion qui prend forme pour vous représenter. À partir de là, d'autres Manifestations peuvent entrer sur le Champ Cartomantique en Soutien, mais pour vraiment façonner ce dialogue, vous devez exercer vos Volontés : des actes de pure intention qui, par le tribut d'un fragment de votre propre âme, altèrent le cours de la Confrontation. Quand vous gagnez une Confrontation, vous assimilez les Manifestations de l'âme adverse dans votre Réceptacle Empathique, accumulant leur valeur en points — une représentation du poids de ce fragment dans l'âme de son propriétaire."},{"type":"callout","text":"Le vainqueur est celui qui, à la fin de la partie, a accumulé le plus de points dans son Réceptacle Empathique, prouvant qu'il a assimilé et compris le plus profondément le for intérieur de la personne en face de lui.","variant":"winner"}],"basics":[{"type":"h2","text":"Les bases"},{"type":"h2","text":"Les Tempéraments"},{"type":"p","text":"Chaque carte qui compose l'âme d'un Cartomancien appartient à un Tempérament. Ces Tempéraments, et leur répartition au sein d'un deck, définissent la puissance et la personnalité de cette âme. Les Tempéraments sont les courants fondamentaux de l'être, chacun avec sa propre identité et sa façon d'aborder la Confrontation :"},{"type":"h3","text":"Tempéraments de base"},{"type":"p","text":"Flegmatique (Vert) : Patient, collaboratif, englobant. Le Flegmatique n'impose pas ; il s'étend. Dans une Confrontation, il met sur la table chaque fragment de lui-même, cultivant une présence faite de nombreuses petites Manifestations qui devient irrésistible. Sa victoire est celle de la saturation empathique : il enveloppe l'adversaire si profondément dans sa propre intériorité qu'il ne lui laisse aucune place pour définir la sienne."},{"type":"p","text":"Colérique (Rouge) : Passionné, courroucé, écrasant. Le Colérique est une âme qui brûle d'une seule flamme intense. Il ne dialogue pas : il déclare. Dans une Confrontation, il manifeste des pics émotionnels d'une puissance immense et déchaîne des Volontés qui anéantissent tout obstacle, imposant sa propre vérité avec une force qui ne souffre aucune réplique."},{"type":"p","text":"Vitreux (Bleu) : Froid, logique, manipulateur. Là où les autres voient le chaos, le Vitreux voit un schéma. Il contrôle le flux de la Confrontation en piochant des réponses, en invalidant les impulsions adverses par leur renvoi dans le Deck, et en dupliquant les réponses les plus efficaces. Il l'emporte non pas en exposant sa propre âme, mais en prouvant qu'il a mieux compris celle de l'autre que l'autre ne la comprend lui-même."},{"type":"p","text":"Capricieux (Jaune) : Rusé, imprévisible, envieux. Le Capricieux danse au bord de l'incertitude, utilisant sa vulnérabilité apparente comme appât. Au lieu de se confronter honnêtement, il sabote le dialogue : il neutralise les impulsions les plus fortes, vole ce qui ne lui appartient pas et contrarie les plans de l'adversaire avec un timing frustrant, l'emportant au moment où l'autre ne sait plus comment s'exprimer."},{"type":"p","text":"Mélancolique (Violet) : Nostalgique, tourmenté, dévorant. L'âme mélancolique combat son propre vide en le projetant sur l'autre. Elle le force à perdre des fragments de lui-même en lui faisant défausser des cartes, affaiblit ses impulsions et rappelle le passé depuis les Limbes. Assimiler les Manifestations de l'adversaire dans son Réceptacle Empathique est la seule façon qu'elle connaisse de se sentir, ne serait-ce qu'un instant, un peu plus entière."},{"type":"h3","text":"Méta-Tempéraments"},{"type":"p","text":"Transcendant (Blanc) : Unifiant, adaptable, éclairé. Si le but du jeu est la compréhension, le Transcendant est celui qui la poursuit avec sincérité. Il embrasse tous les Tempéraments, agissant comme un pont entre eux pour trouver un langage commun. Ses cartes plient les règles non pour tricher, mais pour créer de nouvelles voies de connexion, s'adaptant à chaque âme pour atteindre une plus grande conscience."},{"type":"p","text":"Creux (Noir) : Apathique, égoïste, imitateur. Si le Transcendant est l'ascension, le Creux est l'effondrement vers la victoire à tout prix. Il rejette l'esprit du jeu pour n'en exploiter que les mécaniques. Ses cartes sont des échos distordus des autres Tempéraments, des raccourcis qui offrent une puissance immédiate en échange de fragments de lui-même. Sa victoire n'apporte aucune compréhension, seulement le silence d'un objectif atteint."},{"type":"p","text":"Ce set est composé de 300 cartes uniques au total : toutes les cartes des Tempéraments de base et des Méta-Tempéraments sont contenues dans leur propre paquet. Chaque paquet de Tempérament de base comprend 50 cartes : 35 Manifestations, 12 Volontés du Tempérament correspondant et 3 Volontés Creuses. Les paquets de Tempérament de base contiennent aussi toutes les cartes nécessaires aux decks de départ (4.1.1)."},{"type":"p","text":"Le paquet Méta-Tempérament comprend 50 cartes : 10 Manifestations Creuses, 10 Manifestations Transcendantes, 10 Volontés Multi-Tempérament et 20 Volontés Creuses. Chaque joueur peut utiliser son propre set de cartes pour construire ses decks ; il n'est pas nécessaire de partager un seul set entre tous les participants."},{"type":"h2","text":"Les cartes"},{"type":"p","text":"Un deck Kartomantik est composé de deux types de cartes : les Manifestations et les Volontés."},{"type":"h3","text":"Les Manifestations"},{"type":"p","text":"« Les fragments mêmes de la psyché d'un Cartomancien. Chacun met à nu des impulsions, des manies, des passions et des peurs, prenant forme pour vous représenter dans les Confrontations. »"},{"type":"label-list","text":"Nom de la carte"},{"type":"label-list","text":"Type de Manifestation"},{"type":"label-list","text":"Effets : le texte décrivant les capacités spéciales de la carte. Certaines Manifestations peuvent avoir le mot-clé « Soutien » (3.1). Normalement, une seule Manifestation peut être jouée dans la Confrontation, la Première Manifestation ; seules les Manifestations avec Soutien peuvent être jouées et entrer dans la Confrontation par la suite."},{"type":"label-list","text":"Tempérament et Puissance : les symboles à la base de la carte. Leur forme et leur couleur définissent son Tempérament, et leur nombre définit sa Puissance de base. Essentiels pour gagner les Confrontations et jouer vos Volontés."},{"type":"label-list","text":"Points : la valeur de la Manifestation lorsqu'elle est placée dans un Réceptacle Empathique (1.3). Utilisée aussi pour la construction du deck ; chaque Cartomancien a une limite maximale de points que son deck peut contenir."},{"type":"note","text":"NOTE : Chaque carte, dans le coin inférieur gauche, présente aussi le symbole du set auquel elle appartient et un numéro pour l'identifier et l'ordonner parmi les cartes de ce set."},{"type":"h3","text":"Les Volontés"},{"type":"p","text":"« Intention pure, actes de détermination qu'un Cartomancien projette sur le Champ Cartomantique pour en altérer l'équilibre. »"},{"type":"label-list","text":"Nom de la carte"},{"type":"label-list","text":"Type de Volonté :"},{"type":"label-list","text":"Éphémère : une carte à effet instantané. Elle est jouée, son effet se résout, puis elle est placée dans les Limbes (1.3)."},{"type":"label-list","text":"Persistante : contrairement aux Éphémères, elle reste en jeu sur le Champ Cartomantique (1.3), appliquant son effet de façon continue ou selon des conditions spécifiées. Ces cartes ne peuvent pas être jouées en réponse tant que d'autres cartes sont sur la Pile (2.3) et ne sont jouées que pendant la Phase Finale."},{"type":"label-list","text":"Coût de Tribut : la plupart des Volontés nécessitent un Tribut pour être jouées. Les symboles présents et leur nombre indiquent le Tempérament et la quantité de puissance à payer en Tribut. La façon de payer les Tributs sera expliquée plus loin (2.1). NOTE : Certaines Volontés peuvent nécessiter un Tribut de plusieurs Tempéraments ; dans ce cas, les deux doivent être payés. La carte est considérée comme étant des deux Tempéraments."},{"type":"label-list","text":"Effets : texte décrivant les effets de la Volonté."}],"zones":[{"type":"h2","text":"Les zones de jeu"},{"type":"p","text":"1) Main : les cartes que le joueur a à disposition pour être jouées. Cachées des adversaires."},{"type":"p","text":"2) Deck : les cartes restantes de votre deck, face cachée."},{"type":"p","text":"3) Limbes : la zone où sont placées les Volontés Éphémères jouées et résolues, les Manifestations utilisées comme Tributs et les cartes détruites. Les cartes sont face visible."},{"type":"p","text":"4) Zone de Confrontation : une zone partagée où sont placées toutes les Manifestations jouées en tant que Première Manifestation ou en Soutien pendant une Confrontation."},{"type":"p","text":"5) Interzone : zone où un joueur peut placer jusqu'à 3 de ses Manifestations ayant gagné une Confrontation pour continuer à utiliser leurs effets. Les cartes sont face visible. Ces Manifestations peuvent être remplacées en les plaçant au fond du Deck de leur propriétaire chaque fois qu'une autre devrait entrer."},{"type":"p","text":"6) Champ Cartomantique : zone de jeu, souvent abrégée en « champ », qui comprend l'Interzone et la Zone de Confrontation, et inclut les Volontés Persistantes jouées, qui peuvent être placées à la discrétion du joueur."},{"type":"p","text":"7) Zone d'Impasse : une zone spéciale où sont placées les Manifestations impliquées dans une Confrontation terminée par une égalité (Impasse), ou déplacées ici par des cartes ou des effets. Les Manifestations y restent jusqu'à ce qu'une Confrontation se conclue avec un vainqueur."},{"type":"p","text":"8) Réceptacle Empathique : la zone où s'accumulent les Manifestations de l'adversaire ayant perdu une Confrontation. Les points de ces cartes sont comptés à la fin de la partie pour déterminer le vainqueur. Les cartes sont face visible."},{"type":"note","text":"NOTE : Vous êtes autorisé à regarder toute carte face visible ou toute zone contenant des cartes face visible, et à compter le nombre de cartes et de points dans n'importe quelle zone."},{"type":"p","text":"9) Exil : la zone où sont placées toutes les cartes exilées, avec lesquelles il n'est plus possible d'interagir pour le reste de la partie. Les cartes sont face cachée."},{"type":"p","text":"10) La Pile : une zone temporaire où sont placées toutes les cartes jouées et tous les effets déclenchés ou activés avant qu'ils ne se résolvent ou n'entrent sur le champ, régie par le Système de Pile (2.3)."}],"turn-overview":[{"type":"h2","text":"Aperçu du tour"},{"type":"p","text":"Les joueurs s'affrontent au cours de tours partagés, qui se divisent en ces phases :"},{"type":"phase","label":"Phase de Récupération :","text":"les joueurs piochent des cartes de leur deck jusqu'à en avoir 7 en main."},{"type":"phase","label":"Phase de Confrontation :","text":"Les joueurs choisissent et jouent simultanément une Première Manifestation depuis leur main, en la révélant dans la Zone de Confrontation. Après la Révélation, les joueurs peuvent jouer des Volontés Éphémères et des Manifestations avec Soutien, ou activer les effets de cartes sur le champ (Volontés Persistantes jouées, Manifestations dans la Zone de Confrontation ou dans l'Interzone)."},{"type":"phase","label":"Phase de Résolution :","text":"La Confrontation est résolue en fonction de la Puissance et du Tempérament des Manifestations dans la Confrontation. Si un joueur gagne la Confrontation, il place les Manifestations de l'adversaire dans son Réceptacle Empathique et décide s'il déplace ses propres Manifestations au fond de son deck ou dans son Interzone. En cas d'égalité, toutes les Manifestations de la Zone de Confrontation sont déplacées vers la Zone d'Impasse."},{"type":"phase","label":"Phase Finale :","text":"les joueurs peuvent jouer des Volontés Persistantes."},{"type":"callout","text":"La partie se termine quand un joueur n'a plus de cartes à piocher pendant la Phase de Récupération, ou ne peut plus jouer de Première Manifestation. Le joueur ayant accumulé le plus de points dans son Réceptacle Empathique gagne. Les différentes phases du tour et les actions autorisées seront détaillées dans la section « Structure du tour et phases » (4.2).","variant":"end-condition"}],"tribute":[{"type":"h2","text":"Jouer ses cartes"},{"type":"h2","text":"Comment payer un Tribut"},{"type":"p","text":"« Tout acte intentionnel exige un sacrifice. Pour en canaliser la puissance, le désir ne suffit pas : vous devez offrir en retour un fragment de votre propre âme d'une intensité égale. C'est un Tribut. »"},{"type":"p","text":"Jouer la Première Manifestation ou placer des Manifestations en Soutien n'a normalement aucun coût, mais de nombreuses actions (jouer des Volontés, activer des effets) exigent un Tribut. Pour payer un Tribut :"},{"type":"list","text":"Déclarez la Volonté ou l'effet pour lequel vous payez le Tribut, ainsi que ses cibles éventuelles (3.2 - Cibles)."},{"type":"list","text":"Choisissez une ou plusieurs Manifestations de votre main du Tempérament du Tribut afin d'atteindre une puissance totale égale ou supérieure à la valeur de Tribut requise. Montrez votre sélection à l'adversaire."},{"type":"list","text":"Satisfaites toute exigence supplémentaire demandée par l'action et déplacez les Manifestations choisies pour le Tribut vers les Limbes."},{"type":"note","text":"NOTE : Si les Manifestations choisies couvrent déjà ou dépassent le coût requis par une action, aucune Manifestation supplémentaire ne peut être utilisée pour le Tribut, sauf indication contraire de l'action. Les Manifestations ne peuvent être utilisées comme Tribut que si une action l'exige spécifiquement."},{"type":"h3","text":"Essence excédentaire"},{"type":"p","text":"Si la Puissance de base des Manifestations utilisées comme Tribut est supérieure à celle requise, l'excédent est considéré comme de l'« Essence excédentaire ». Cet excédent peut servir à payer, ou à contribuer au paiement, d'autres Tributs du même Tempérament, agissant comme une réserve temporaire. Si vous disposez d'Essence excédentaire, elle doit toujours être utilisée pour le paiement de tout Tribut correspondant à son Tempérament. Toute Essence excédentaire non utilisée avant la fin du tour où elle a été générée est perdue."},{"type":"note","text":"NOTE : L'Essence excédentaire ne transporte pas avec elle les effets de la Manifestation dont elle provient, sauf indication sur la Manifestation."},{"type":"h3","text":"Tributs et Essences spéciaux"},{"type":"p","text":"Tributs Creux (🔘) : de nombreuses Volontés et effets peuvent exiger un Tribut de Tempérament Creux 🔘. Il peut être payé avec une Manifestation de n'importe quel Tempérament."},{"type":"p","text":"Essences Creuse (🔘) et Transcendante (🌈) : une Manifestation Creuse ne peut payer que des Tributs Creux. À l'inverse, une Manifestation ou une Essence excédentaire de Tempérament Transcendant peut être utilisée pour payer un Tribut de n'importe quel Tempérament, en déclarant, pour chaque Essence utilisée, quel Tempérament de base elle représente."},{"type":"h3","text":"Exemple de Tribut"},{"type":"list","text":"Un joueur veut jouer une Volonté Éphémère, « Incinérer », d'un coût de 4🔥 (Colérique) en Tribut."},{"type":"list","text":"Dans sa main, il a deux Manifestations : l'une de Puissance de base 2🔥 et l'autre de 3🔥. Aucune n'est suffisante à elle seule ; le joueur utilise donc les deux, en additionnant leur Puissance de base."},{"type":"list","text":"Le joueur montre ces Manifestations à l'adversaire et déclare qu'il les utilise comme Tribut pour la Volonté « Incinérer »."},{"type":"list","text":"La Volonté est jouée, et les Manifestations utilisées comme Tribut sont placées dans les Limbes."},{"type":"list","text":"Ayant payé une Volonté d'un coût de 4 avec une puissance totale de 5, le joueur gagne 1 Essence excédentaire 🔥, qu'il peut utiliser jusqu'à la fin de ce tour."}],"priority-stack":[{"type":"h2","text":"La Priorité"},{"type":"p","text":"Maintenant que vous savez payer des Tributs et jouer des Volontés, vous devez comprendre quand vous avez le droit d'accomplir ces actions. Comme Kartomantik est un jeu à tours partagés, il repose sur la Priorité pour décider quel joueur a le droit d'agir."},{"type":"p","text":"Qui a la Priorité :"},{"type":"list","text":"Pendant la Phase de Confrontation, le joueur qui perdrait la Confrontation si elle était résolue à cet instant (4.2.2 - Résolution) a la Priorité."},{"type":"list","text":"Dans toutes les autres phases de jeu, le joueur qui a gagné la dernière Confrontation résolue a la Priorité."},{"type":"p","text":"Avoir la Priorité signifie avoir le droit d'accomplir une action, comme jouer une carte ou activer un effet. Le joueur qui a la Priorité peut choisir d'accomplir une action ou de « passer », cédant la Priorité à l'adversaire."},{"type":"note","text":"NOTE : Dans le cas particulier où il n'y a aucun moyen de déterminer quel joueur a la Priorité, chaque joueur lance un dé. Celui qui obtient le résultat le plus élevé a la Priorité."},{"type":"h2","text":"Le Système de Pile"},{"type":"p","text":"Lorsque, ayant la Priorité, vous jouez une carte, ou qu'un effet de carte est déclenché ou activé, ces actions ne se résolvent pas immédiatement : elles sont placées sur la Pile, une zone partagée où elles s'accumulent en attendant de se résoudre selon les étapes suivantes :"},{"type":"list","text":"Un joueur place une action sur la Pile (joue une carte, active son effet, ou un effet qu'il contrôle est déclenché)."},{"type":"list","text":"La Priorité passe à l'adversaire, qui peut répondre en plaçant une action au sommet de la Pile, ou passer. Tant qu'il y a des actions sur la Pile, les joueurs échangent automatiquement la Priorité chaque fois qu'ils ajoutent une action au sommet de la Pile ou passent."},{"type":"list","text":"Quand les deux joueurs passent consécutivement sans ajouter d'action à la Pile, celle-ci commence à se résoudre. Les actions sur la Pile se résolvent une à une dans l'ordre inverse, en partant de la dernière ajoutée (celle du sommet)."},{"type":"list","text":"Chaque fois qu'une action au sommet de la Pile est résolue et qu'une autre action est encore présente sur la Pile, chaque joueur peut interrompre la résolution de la Pile, revenant au point 2. Précisément, la Priorité passe au joueur qui ne contrôle pas l'action actuellement au sommet de la Pile, qui peut à nouveau décider de répondre ou de passer, et ainsi de suite."},{"type":"p","text":"Le processus continue jusqu'à ce que toutes les actions de la Pile aient été résolues. Une fois la Pile vidée, les joueurs reviennent aux règles normales de Priorité et peuvent démarrer une nouvelle Pile s'ils ont encore des actions à accomplir."},{"type":"note","text":"NOTE : Les Volontés Persistantes ne peuvent pas être utilisées en réponse ; elles ne peuvent être placées sur la Pile que s'il n'y a aucune autre carte déjà dessus."},{"type":"note","text":"NOTE : Quand un joueur accomplit une action qui utilise la Pile, ce qui est placé sur la Pile peut être :"},{"type":"list","text":"Une carte : quand vous jouez une carte depuis votre main ou depuis une zone autre que le champ (une Volonté Éphémère, une Volonté Persistante, ou une Manifestation avec Soutien), c'est la carte elle-même qui est placée sur la Pile. Elle y attend sa résolution. Si l'action se résout, la carte produit son effet puis se déplace vers la zone appropriée (les Limbes pour les Volontés Éphémères, le Champ Cartomantique pour les Volontés Persistantes, et la Zone de Confrontation pour les Manifestations de Soutien)."},{"type":"list","text":"Un effet : quand vous activez l'effet d'une carte déjà sur le champ (par ex. une Manifestation dans l'Interzone ou une Volonté Persistante), c'est uniquement l'effet qui est placé sur la Pile. La carte qui l'a généré reste où elle est."},{"type":"h3","text":"Exemples du Système de Pile"},{"type":"p","text":"Cas 1 :"},{"type":"p","text":"Imaginons une situation pendant une Confrontation. Le Joueur A a la Priorité et veut affaiblir « Gar Fild, le Malléable » (puissance 3) du Joueur B pour gagner la Confrontation."},{"type":"list","text":"Le Joueur A joue une Volonté Éphémère, « Opprimer », ciblant « Gar Fild ». L'effet d'Opprimer est : « Une Manifestation ciblée sur le champ gagne -3 puissance jusqu'à la fin du tour. » La carte est placée sur la Pile."},{"type":"list","text":"La Priorité passe au Joueur B, qui répond en jouant « Confier » sur son « Gar Fild ». L'effet de Confier est : « Doublez la Puissance de base d'une Manifestation ciblée sur le champ. » La carte est placée sur la Pile, au-dessus d'« Opprimer »."},{"type":"list","text":"Les deux joueurs choisissent de ne plus rien faire, passant la Priorité. Comme ils ont passé consécutivement, la Pile commence à se résoudre de haut en bas."},{"type":"list","text":"D'abord, la dernière action ajoutée se résout : « Confier ». La Puissance de base de « Gar Fild » est doublée, portant sa puissance totale à 6. La Volonté part aux Limbes."},{"type":"list","text":"Ensuite, « Opprimer » se résout. Son effet s'applique à « Gar Fild », qui a maintenant 6 de puissance. Sa puissance est réduite de 3, la ramenant à 3. Ce n'est pas suffisant pour le détruire. « Opprimer » part aussi aux Limbes."},{"type":"p","text":"La Pile est maintenant vide. « Gar Fild, le Malléable » a survécu à l'interaction, et la Confrontation continue."},{"type":"p","text":"Cas 2 :"},{"type":"p","text":"Voyons maintenant ce qui se passe si le Joueur B était en désavantage et agissait en premier :"},{"type":"list","text":"Le Joueur B, ayant la Priorité car il est en désavantage, joue « Confier » sur « Gar Fild ». La carte est placée sur la Pile."},{"type":"list","text":"La Priorité passe au Joueur A, qui joue « Opprimer » sur le même « Gar Fild » en réponse. « Opprimer » est placé sur la Pile, au-dessus de « Confier »."},{"type":"list","text":"Les deux joueurs passent, et la Pile commence à se résoudre."},{"type":"list","text":"Cette fois, « Opprimer » se résout en premier. Il applique son effet à « Gar Fild », qui a encore 3 de puissance. Sa puissance tombe à 0 (3-3=0), et il est détruit."},{"type":"list","text":"Ensuite, « Confier » tente de se résoudre. Au moment où il essaie de se résoudre, sa cible, « Gar Fild », n'est plus sur le champ. L'effet ne peut pas s'appliquer, et la carte part aux Limbes sans avoir rien fait."}],"effects":[{"type":"h2","text":"Comprendre les cartes"},{"type":"p","text":"Pour maîtriser Kartomantik, il est crucial de comprendre comment interpréter et appliquer les effets des cartes. La section suivante sert de guide complet à ces interactions. Pour un nouveau joueur, une première lecture pour se familiariser avec les concepts généraux est recommandée, sans avoir besoin de mémoriser chaque règle spécifique."},{"type":"p","text":"Utilisez ce chapitre comme un glossaire de règles pour lever des doutes précis à mesure qu'ils surviennent."},{"type":"h2","text":"Types d'effets"},{"type":"h3","text":"Activés"},{"type":"p","text":"Effets que vous pouvez choisir d'utiliser en payant un Tribut ou en remplissant une condition. Vous les reconnaissez à des formulations comme « Payez [coût] : ». Les effets activés utilisent la Pile et ne peuvent être utilisés qu'après la Révélation de la Première Manifestation."},{"type":"note","text":"NOTE : Quand une carte doit être épuisée pour activer son effet, tournez la carte de 90° ; cet effet ne peut plus être utilisé jusqu'à ce que la carte soit restaurée lors de la prochaine Phase de Récupération (4.2.1)."},{"type":"h3","text":"Continus (passifs)"},{"type":"p","text":"Effets qui sont toujours actifs tant que la carte reste sur le champ (ou dans la zone qu'ils spécifient). Ils n'ont, et ne requièrent, aucune condition pour être utilisés. Vous les reconnaissez à des formulations comme « Tant que… ». Ils n'utilisent pas la Pile."},{"type":"note","text":"NOTE : Les effets continus qui affectent d'autres cartes (par ex. « Les Manifestations que vous contrôlez gagnent +1 puissance tant qu'elles sont dans la Zone de Confrontation ») s'appliquent exclusivement tant que la carte générant l'effet ET les cartes affectées restent dans la zone spécifiée ; ils cessent immédiatement de s'appliquer dès que les cartes entrent dans une zone non couverte par le texte de la carte."},{"type":"h3","text":"Déclenchés"},{"type":"p","text":"Effets qui s'activent automatiquement lorsqu'une condition spécifique est remplie. Vous les reconnaissez à des mots comme « Quand… », « À chaque fois que… », « Si… ». Ils sont placés sur la Pile dès que leur condition est remplie, même pendant la résolution de la Pile, après que l'action les ayant déclenchés s'est résolue (les joueurs peuvent répondre). Quand plusieurs cartes ont un déclencheur au même moment (par ex. « lors de la Révélation »), ces effets sont simultanés. Si des effets simultanés sont contrôlés par des joueurs différents, ils sont placés sur la Pile selon les règles de Priorité : le joueur qui a la Priorité place ses effets sur la Pile en premier, puis l'adversaire place les siens. Si plusieurs effets simultanés appartiennent au même joueur, ce joueur choisit leur ordre sur la Pile. Dans le cas d'effets simultanés, tous doivent entrer sur la Pile avant qu'il soit possible de répondre."},{"type":"note","text":"NOTE : Si une Manifestation a un effet déclenché qui se produit lorsqu'elle est utilisée comme Tribut ou pour payer un coût alternatif (par ex. défausser une carte), l'action payée et l'effet de cette Manifestation sont simultanés."},{"type":"h3","text":"Soutien et Enchaînement"},{"type":"p","text":"Le Soutien est un effet activé spécial, normalement sans coût, qui permet à des Manifestations d'être jouées et d'entrer dans la Zone de Confrontation après la Première Manifestation, depuis la main ou l'Interzone. Si « depuis la main » est précisé, cette carte ne peut être jouée en Soutien que depuis votre main."},{"type":"p","text":"Enchaîner est un effet qui permet de placer n'importe quelle Manifestation en Soutien depuis la zone spécifiée sur la carte. Une Manifestation Enchaînée est considérée comme « jouée »."},{"type":"h2","text":"Lire les effets : règles clés"},{"type":"p","text":"La Règle d'Or : si le texte d'une carte a un effet qui contredit les règles du jeu, le texte de cette carte prévaut sur les règles du jeu. Si des effets se contredisent entre eux : les restrictions absolues (effets utilisant des mots comme « ne peut pas » ou « seulement ») prévalent toujours sur les effets qui autorisent ou tentent de forcer une action. Par exemple, si un effet dit « Vous ne pouvez pas piocher de cartes » et un autre « Piochez 3 cartes », l'effet qui empêche l'action l'emporte toujours."},{"type":"p","text":"Propriétaire et Contrôleur : chaque joueur est toujours le Propriétaire des cartes avec lesquelles il a commencé la partie dans son deck et, sauf si un effet le modifie, il en est aussi le Contrôleur, c'est-à-dire le joueur qui peut les jouer et activer leurs effets. Si une carte dont vous êtes le Contrôleur génère un effet, vous êtes aussi le Contrôleur de cet effet. Quand le texte d'une carte s'adresse directement au joueur, par exemple avec « vous » ou « votre », il désigne toujours le Contrôleur actuel de la carte."},{"type":"p","text":"Zones de jeu : si un effet indique une zone (par ex. « placez dans l'Interzone ») sans préciser le propriétaire, il désigne toujours celle appartenant au contrôleur de la carte. Chaque joueur est le Propriétaire de toutes ses zones de jeu non partagées : Interzone, Limbes, Deck, Main, Réceptacle Empathique et Exil. Les Limbes, le Deck, la Main et l'Exil ne peuvent contenir que des cartes dont vous êtes le Propriétaire. Le Réceptacle Empathique, à l'inverse, ne peut contenir que des cartes (Manifestations) dont vous n'êtes PAS le Propriétaire."},{"type":"note","text":"NOTE : Les Manifestations dans les Réceptacles Empathiques sont toujours sous le contrôle de leur Propriétaire. Quand des cartes entrent dans une zone de jeu partagée, comme la Zone de Confrontation, la Pile ou la Zone d'Impasse, ces cartes entrent sous le contrôle de leur Propriétaire, sauf indication contraire des cartes."},{"type":"p","text":"Cibles : de nombreuses cartes, pour se résoudre, ont besoin d'une ou plusieurs cibles, l'objet sur lequel elles ont un effet. Chaque fois que le mot « ciblé(e) » (ou « cible ») est utilisé dans le texte d'une carte en relation avec quelque chose (un joueur, une Manifestation, etc.), le contrôleur de cette carte doit déclarer une cible valide avant de placer cette action sur la Pile. Par exemple, si un effet dit « Une Manifestation ciblée sur le champ gagne -1 puissance », cet effet requiert une cible. Son contrôleur doit donc déclarer une Manifestation sur le champ comme cible avant de placer l'effet sur la Pile. La cible doit être valide à la fois quand l'effet est placé sur la Pile et quand il se résout. Si la cible n'est plus valide au moment où l'effet se résout (si, par exemple, la Manifestation a été retirée du champ), l'effet n'a pas lieu."},{"type":"p","text":"Validité des actions : vous ne pouvez pas jouer une carte ni activer un effet si vous ne pouvez pas en remplir toutes les exigences. Cela inclut le paiement des Tributs, les coûts supplémentaires (par ex. défausser des cartes) et le choix d'un nombre suffisant de cibles valides."},{"type":"p","text":"Modificateurs et marqueurs : tout ce qui altère les caractéristiques de base d'une carte ou d'une zone, sous forme permanente ou temporaire, est appelé un Modificateur. Si la puissance d'une Manifestation augmente ou diminue, ou si une carte perd ses effets ou en gagne d'autres au-delà de ceux qu'elle aurait normalement, ce sont des Modificateurs. Les Modificateurs sont, sauf indication contraire, permanents, mais seulement tant que la carte reste sur le Champ Cartomantique ou dans la Zone d'Impasse. Cela signifie, par exemple, qu'une Manifestation avec des Modificateurs peut se déplacer entre le champ (Interzone, Zone de Confrontation) et la Zone d'Impasse sans perdre ses modificateurs ; en revanche, si elle quitte l'une de ces zones pour entrer dans des Limbes, un Réceptacle Empathique, un deck, la main ou l'Exil, la Manifestation perd tous ses Modificateurs. Les marqueurs sont, quant à eux, une ressource qui doit être placée sur une carte ; chaque marqueur a un nom spécifique et est inutile en soi, mais peut servir à satisfaire les exigences des cartes qui en ont besoin pour activer certains effets. Les marqueurs suivent les mêmes règles que les Modificateurs."},{"type":"p","text":"Puissance et Puissance de base : la Puissance de base est une valeur généralement stable, indiquée par le nombre de symboles présents sur une Manifestation. En plus d'indiquer sa puissance de départ, elle indique aussi la valeur de cette Manifestation lorsqu'elle est utilisée comme Tribut. La Puissance est une valeur variable déterminée par la somme de la Puissance de base et de tous les modificateurs qui l'affectent de façon temporaire ou permanente. De plus, la Puissance est la valeur calculée pour déterminer le résultat d'une Confrontation."},{"type":"note","text":"NOTE : Quand une Manifestation atteint 0 puissance ou moins, cette Manifestation est détruite."},{"type":"p","text":"Indépendance des effets : un effet activé ou déclenché, une fois placé sur la Pile, existe indépendamment de sa source. Si la carte ayant généré l'effet est retirée du jeu alors que l'effet est encore sur la Pile, l'effet se résoudra quand même. Un effet qui se déclenche quand une carte subit un certain événement (comme être détruite) se déclenche à l'instant où cet événement se produit. Cet effet ira sur la Pile même si la carte qui l'a généré est en train de quitter le jeu."},{"type":"p","text":"« Mémoire » des effets : parfois, l'effet d'une carte ne fait pas que se résoudre : il crée une nouvelle règle ou un effet différé qui « s'attache » à une autre carte. Cette nouvelle règle reste valide même si la source originale de l'effet quitte le champ, comme si la carte cible en gardait la mémoire. Par exemple, si vous jouez une Volonté qui dit : « Enchaînez depuis votre main. Si la Manifestation Enchaînée gagne la confrontation, exilez-la. » Même si la Volonté d'origine est désormais dans les Limbes, la règle d'exil est « mémorisée » par la Manifestation. À la fin de la Confrontation, cette Manifestation sera exilée."},{"type":"note","text":"NOTE : Cette Mémoire n'est perdue par la carte que si cette dernière entre dans un deck ou si elle est exilée."},{"type":"p","text":"Jouer et Déplacer : les cartes ont plusieurs façons d'entrer sur le champ ; la plus courante consiste à les jouer. Une carte est normalement « jouée » lorsqu'elle est Révélée en tant que Première Manifestation, entre sur la Pile depuis la main ou le deck, ou est jouée depuis d'autres zones par un effet. Les cartes peuvent toutefois aussi entrer sur le champ en étant déplacées, ce qui se produit toujours via d'autres cartes ou effets. Si une carte, par exemple, parle de « placer » quelque chose dans une zone, c'est un déplacement, et il en va de même pour les Manifestations qui entrent en Soutien. Ce sont des déplacements ; les cartes entrent dans les zones spécifiées par ces effets sans passer d'abord par la Pile, et ne sont donc pas considérées comme « jouées », sauf si l'effet le précise explicitement (comme, par exemple, avec l'effet « Enchaîner »)."},{"type":"p","text":"Pour interpréter tous les effets de vos cartes et leurs mots-clés, rendez-vous à la section « Mots-clés » (7)."}],"deckbuilding":[{"type":"h2","text":"Jouer une partie"},{"type":"p","text":"Maintenant que vous avez compris les mécaniques de base, il est temps de s'asseoir et d'essayer le jeu. Entrons dans le détail pour voir comment se déroule une partie de Kartomantik entre deux joueurs."},{"type":"h2","text":"Construire un deck"},{"type":"p","text":"Pour commencer à jouer, chaque joueur doit avoir son propre deck."},{"type":"p","text":"Chaque deck doit être construit selon ces règles :"},{"type":"deck-rule","text":"Il doit contenir exactement 30 cartes."},{"type":"deck-rule","text":"La somme des Points de toutes les Manifestations du deck ne doit pas dépasser 500. Les cartes Volonté n'ont pas de coût en points pour la construction du deck."},{"type":"deck-rule","text":"Il ne peut y avoir plus d'un exemplaire de la même carte (même nom) dans le deck."},{"type":"p","text":"Il est recommandé d'avoir entre 8 et 12 Volontés dans un deck, et de s'assurer que leurs Tributs peuvent tous être payés. Pour les decks multi-Tempérament, il est préférable d'ajouter des Volontés ou des Manifestations Creuses, Transcendantes ou non, capables de payer plusieurs Tempéraments."},{"type":"p","text":"Si les joueurs veulent jouer au meilleur des 3 (Bo3), ils peuvent créer, en plus d'un deck normal, une Réserve (Sideboard) de 6 cartes sans limite de points. Avant le début de chaque manche, chaque joueur peut modifier son deck en y remplaçant des cartes par n'importe quelle carte choisie dans sa Réserve, en respectant les limites de construction normales."},{"type":"h3","text":"Decks de départ"},{"type":"p","text":"Pour essayer le jeu la première fois, il est recommandé de construire les decks de départ :"},{"type":"h4","text":"Colérique 🔥"},{"type":"p","text":"Fureur Atavique (235) ; Serpent-Chandelle (189) ; Biceps Ancien (190) ; Tigrolion (191) ; Druide Bicéphale (193) ; Furibête Ardente (195) ; Baranchio le Perfide (196) ; Vétéran Errant (197) ; Skapus, le Vil (198) ; Titan de la Matrice Embrasée (199) ; Glabron l'Oppresseur (200) ; Fintus, le Spectaculaire (202) ; Maître des Épines (203) ; Pimbo (204) ; Gorb le Baraqué (206) ; Borombo le Fou (210) ; Bell, Fanatique Ardent (214) ; Apparition Solaire (216) ; Bolbakazim, le Maudit (217) ; Présence Amicale (218) ; Migmomirf (219) ; Incinérer (225) ; Corroder (226) ; Endommager (227) ; Opprimer (228) ; Revanche ! (232) ; Arène Misérable (234) ; Affaiblir (272) ; Duel Loyal (279) ; Volcan (300)."},{"type":"h4","text":"Capricieux ⚡"},{"type":"p","text":"Volatilité Atavique (188) ; Ailoreilles (142) ; Babiole Absente (143) ; Roly-Polymancer (144) ; Yzzit, le Parieur (146) ; Pok, le Taquin (148) ; Pard Incohérent (149) ; Grande Gueule Imprévisible (150) ; Détaleur Statique (151) ; Loop, l'Insistant (152) ; Cimba, le Turbulent (153) ; Mime (154) ; Têtard Rebelle (155) ; Amphore Jongleuse (156) ; Colosse Noueux (159) ; Ranba, Ravisseur Silencieux (161) ; Fléau Indocile (163) ; Bloatuba (164) ; Bec Planaire (165) ; Masse Envahissante (166) ; Le Piétineur (167) ; Starkaz, le Brillant (169) ; Élaguer le Superflu (177) ; Neutraliser (179) ; Nectar Annihilant (180) ; Récupérer les Fragments (181) ; Clouer sur Place (183) ; Ignorer (285) ; Masque Empathique (289) ; Piège (291)."},{"type":"h4","text":"Mélancolique 🔮"},{"type":"p","text":"Oppression Atavique (141) ; Petite Répulsion (95) ; Esprit Craintif (96) ; Orphelin Répudié (97) ; Abats Endeuillés (98) ; Yurfuq, Lys Triste (101) ; Tenebro, Assaillant Nocturne (102) ; Amas Oublié (103) ; Sombre Apparition (104) ; Escargot Souterrain (106) ; Solenero, le Contrit (108) ; Zombalançoire (110) ; Géant Diabolique (111) ; Parasite Mental (112) ; Lament, Annule-Pensées (114) ; Forfog, le Pendu (115) ; Zrutrug, l'Endetté (118) ; Urne Repoussante (120) ; Dévoreur de Carcasses (121) ; Pachyver Cuirassé (122) ; Urolong, Nécromancien Affligé (125) ; Défigurer (130) ; Réclamer les Rejetés (131) ; Briser le Soi (135) ; Reforger le Destin (136) ; Traumatiser (139) ; Réanimer (140) ; Remonter de l'Abîme (270) ; Prier l'Éther (281) ; Karmapulte (296)."},{"type":"h4","text":"Vitreux 💧"},{"type":"p","text":"Introspection Atavique (94) ; Manta Dissimulée (48) ; Penseur Artificiel (49) ; Forge-Mots Isolé (50) ; Découvreur à l'Œil Perçant (52) ; Hurlon, Greffe-Pensées (54) ; Repousseur Cuiracé (55) ; Ammonite Fiable (57) ; Présage Rigide (59) ; Nuagénie Inspiré (63) ; Ohmom, l'Azuré (64) ; Crâne de Corail (65) ; Triade Vogue-Ciel (66) ; Shababba, Cube Divinatoire (68) ; Hermeto, l'Observateur (70) ; Tipson, le Médiateur (72) ; Songeur Expansif (73) ; Invocatrice de Rosée (74) ; Shymon, le Cerveau (76) ; Entité Bleue (80) ; Scruter l'Avenir (83) ; Différer (84) ; Refléter l'Impulsion (85) ; Imiter (86) ; Consulter (88) ; Dominer les Émotions (92) ; Bannir (93) ; Méditer (267) ; Refuser (276) ; Grimoire (297)."},{"type":"h4","text":"Flegmatique 🌿"},{"type":"p","text":"Accueil Atavique (47) ; Pousse du Vent (1) ; Cœur-de-Porc Repu (2) ; Pago Miséricordieux (3) ; Tiptup, le Siffleur (4) ; Champimonde (7) ; Pétale Gracieux (8) ; Courge Cordiale (10) ; Première Pierre (11) ; Tentacolonne Immense (12) ; Caresse-Fleurs (13) ; Écho du Bosquet (16) ; Roupilleur Stoïque (17) ; Jondo, le Cœur Pur (19) ; Pan Zuto, le Convocateur (20) ; Incubateur Spontané (21) ; Dame des Bossus (23) ; Couvée Galopante (24) ; Avocat de la Catharsis (27) ; Sanctuaire Mobile (28) ; Guide Forestier (31) ; Unir les Impulsions (36) ; Inviter à la Générosité (37) ; Confier (40) ; Ralliement (44) ; Récompenser la Constance (45) ; Monument Réconfortant (46) ; Renforcer (266) ; Glaneur d'Essences (268) ; Accentuer (275)."},{"type":"starter-summary","text":"Chacun de ces decks de départ contient exactement 30 cartes pour un total de 400 points. Une fois que vous savez jouer, vous pouvez les améliorer et expérimenter de nouvelles synergies en explorant les autres cartes disponibles dans le set."}],"turn-structure":[{"type":"h2","text":"Structure du tour et phases"},{"type":"p","text":"Après que les joueurs ont choisi et soigneusement mélangé leurs decks, la partie commence par le premier tour, en démarrant directement par la première Phase de Récupération."},{"type":"p","text":"Il est recommandé d'avoir des marqueurs et de petits objets à utiliser comme jetons pour les effets de vos cartes."},{"type":"h3","text":"Phase de Récupération"},{"type":"list","text":"Si ce n'est pas le premier tour, résolvez tout effet « au début du tour » et restaurez toutes vos cartes épuisées."},{"type":"list","text":"Chaque joueur pioche des cartes de son deck jusqu'à atteindre la limite de main de 7 cartes. Si la main d'un joueur a déjà atteint la limite, ce joueur ne pioche pas."},{"type":"list","text":"Chaque joueur vérifie qu'il a au moins une carte Manifestation en main jouable comme Première Manifestation ; sinon, il doit effectuer un Mulligan. Toutes les Manifestations, sauf indication contraire, peuvent être jouées comme Première Manifestation."},{"type":"list","text":"Après avoir vérifié la présence d'une Première Manifestation, résolvez ou jouez tout effet pouvant survenir « avant la Révélation »."},{"type":"h4","text":"Le Mulligan"},{"type":"p","text":"Si un joueur n'a aucune Manifestation jouable comme Première Manifestation, il doit le déclarer, montrer sa main à l'adversaire pour confirmation, remélanger toutes les cartes de sa main dans son Deck et repiocher jusqu'à la limite de main. C'est un « Mulligan ». Le Mulligan est autorisé au premier tour, une seule fois, même si vous avez une Manifestation valide en main. Dans ce cas, perdez 10 points."},{"type":"note","text":"NOTE : Si, après un second Mulligan, un joueur n'a toujours pas de Première Manifestation jouable, ce joueur perd immédiatement la partie."},{"type":"h3","text":"Phase de Confrontation"},{"type":"p","text":"La Confrontation se compose de deux sous-phases : la Révélation et la Réaction."},{"type":"h4","text":"Révélation"},{"type":"list","text":"Les deux joueurs doivent choisir secrètement une carte Manifestation de leur main à jouer comme Première Manifestation pour le tour. La carte choisie est mise à l'écart de la main (par ex. gardée face cachée sur la table, ou simplement clairement identifiée) pour montrer que le choix a été fait."},{"type":"list","text":"Simultanément, les joueurs dévoilent leur Première Manifestation choisie et la placent de leur côté de la Zone de Confrontation."},{"type":"list","text":"Tous les effets Immédiats à la Révélation sont déclenchés."},{"type":"list","text":"Ensuite, les effets « quand elle entre sur le champ » ou « quand elle entre dans la Zone de Confrontation » des Premières Manifestations et de toute Manifestation jouée par leurs effets sont déclenchés."},{"type":"note","text":"NOTE : Si, à cause de l'effet d'une carte, une Première Manifestation est jouée après celle de l'autre joueur, ces effets ne se déclenchent que lorsque les deux ont été jouées."},{"type":"note","text":"NOTE : Si vous avez déjà des Manifestations dans la Zone de Confrontation, vous ne pouvez pas révéler de Première Manifestation. À la place, vous devez choisir laquelle de ces Manifestations sera comptée comme la Première Manifestation et laquelle comme la dernière jouée. Si, à cause d'un ou plusieurs effets, il y a plusieurs Premières Manifestations, choisissez-en une et placez les autres au fond du deck dans l'ordre de votre choix."},{"type":"h4","text":"Réaction"},{"type":"list","text":"Tous les effets « après la Révélation » sont déclenchés."},{"type":"list","text":"À partir de là, les joueurs peuvent :"},{"type":"list","text":"Jouer des Volontés Éphémères depuis leur main (en payant les Tributs éventuels)."},{"type":"list","text":"Jouer des Manifestations avec Soutien depuis leur main ou leur Interzone pour les ajouter à la Confrontation."},{"type":"list","text":"Utiliser les effets activés de Volontés Persistantes ou de Manifestations déjà sur le champ."},{"type":"note","text":"NOTE : Si une Manifestation entrée en Soutien à cause de cartes ou d'effets déclenche un effet « entre sur le champ » ou « entre dans la Zone de Confrontation », ceux-ci se déclenchent aussi dans cette phase de jeu."},{"type":"p","text":"Toutes ces actions suivent les règles de la Priorité et de la Pile. La Phase de Confrontation continue jusqu'à ce que la Pile soit vide et que les deux joueurs décident de passer."},{"type":"h3","text":"Phase de Résolution"},{"type":"p","text":"Une fois que les deux joueurs ont passé pendant la partie Réaction de la phase :"},{"type":"p","text":"Chaque joueur additionne la Puissance actuelle (Puissance de base plus modificateurs éventuels) de toutes ses Manifestations dans la Zone de Confrontation. Si un joueur n'a aucune Manifestation dans la Confrontation, sa puissance totale est considérée comme 0. Quand un joueur a une puissance totale supérieure, ce joueur gagne la Confrontation."},{"type":"p","text":"Quand un joueur gagne :"},{"type":"list","text":"Tout effet de victoire, de défaite ou « à la Résolution » est déclenché. Les joueurs peuvent jouer des Volontés de leur main et utiliser des effets activés jusqu'à ce que les deux joueurs passent consécutivement, avant que les cartes ne soient déplacées vers leurs zones respectives. Ces effets n'altèrent pas le résultat de la Confrontation."},{"type":"list","text":"Le joueur gagnant place toutes les Manifestations dont l'adversaire est propriétaire présentes dans la Zone de Confrontation et dans la Zone d'Impasse dans son Réceptacle Empathique."},{"type":"list","text":"Pour chaque Manifestation dont il est le propriétaire présente dans la Zone de Confrontation ou dans la Zone d'Impasse, il peut décider, dans l'ordre de son choix, de : la placer au fond de son Deck, face cachée ; ou la placer dans un espace de son Interzone. Si cet espace était déjà occupé par une autre Manifestation, cette dernière est placée au fond du Deck de son propriétaire, face cachée."},{"type":"p","text":"En cas d'égalité de puissance :"},{"type":"p","text":"On utilise la dominance naturelle des Tempéraments. Comparez le Tempérament de la dernière Manifestation entrée dans la Confrontation sous le contrôle de chaque joueur. Si un joueur a le Tempérament dominant, il gagne la Confrontation. La hiérarchie est la suivante :"},{"type":"list","text":"🌿 Flegmatique l'emporte sur 💧 Vitreux et ⚡ Capricieux."},{"type":"list","text":"💧 Vitreux l'emporte sur 🔮 Mélancolique et 🔥 Colérique."},{"type":"list","text":"🔮 Mélancolique l'emporte sur ⚡ Capricieux et 🌿 Flegmatique."},{"type":"list","text":"⚡ Capricieux l'emporte sur 🔥 Colérique et 💧 Vitreux."},{"type":"list","text":"🔥 Colérique l'emporte sur 🌿 Flegmatique et 🔮 Mélancolique."},{"type":"list","text":"🌈 Transcendant l'emporte sur tout autre Tempérament."},{"type":"list","text":"🔘 Creux est battu par tout autre Tempérament."},{"type":"p","text":"Si la puissance totale dans la Confrontation ET le Tempérament des dernières Manifestations jouées sont tous deux égaux, la Confrontation se termine par une Impasse."},{"type":"h4","text":"Impasse"},{"type":"p","text":"En cas d'égalité, toutes les Manifestations des deux joueurs actuellement dans la Zone de Confrontation quittent le champ et sont déplacées vers la Zone d'Impasse. Elles y restent jusqu'à ce qu'une Confrontation soit gagnée, en conservant tous leurs modificateurs permanents."},{"type":"note","text":"NOTE : Comme elles n'ont pas participé à la Confrontation, les Manifestations quittant l'Impasse ne déclenchent pas leurs effets de victoire ou de défaite, même si une Confrontation est résolue avec un vainqueur."},{"type":"h3","text":"Phase Finale"},{"type":"p","text":"Quand la Confrontation a été résolue et que les Manifestations ont été déplacées vers leurs zones respectives, les joueurs peuvent jouer des Volontés Éphémères et des Volontés Persistantes depuis leur main, ou utiliser des effets activés, la Priorité revenant au joueur qui a gagné la dernière Confrontation résolue. Chaque fois, pendant la Phase Finale, qu'une Pile initiée par un joueur se résout complètement, la Priorité passe à son adversaire."},{"type":"p","text":"Une fois la Pile vide et les deux joueurs passant consécutivement :"},{"type":"list","text":"Résolvez tout effet « à la fin du tour »."},{"type":"list","text":"Tous les effets « jusqu'à la fin du tour » cessent."},{"type":"p","text":"Le tour se termine. Si un joueur a fini le tour avec plus de sept cartes en main, il place les cartes en excès au fond de son deck dans l'ordre de son choix. Un nouveau tour commence à partir de la Phase de Récupération, jusqu'à ce que l'une des deux Conditions de fin de partie (4.4.1) soit remplie."},{"type":"h3","text":"Exemple de tour"},{"type":"p","text":"Regardons un exemple de tour entre le Joueur A, avec un deck Flegmatique 🌿, et le Joueur B, avec un deck Colérique 🔥."},{"type":"p","text":"Récupération / Révélation"},{"type":"p","text":"1. Le tour commence. Les deux joueurs piochent des cartes jusqu'à en avoir 7 en main et confirment qu'ils ont une carte à jouer comme Première Manifestation."},{"type":"p","text":"2. Les joueurs commencent la Confrontation. Ils choisissent leur Première Manifestation dans leur main et indiquent leur choix en la plaçant face cachée sur la table."},{"type":"p","text":"3. Le Joueur A (Flegmatique) dévoile Dame des Bosses (Puissance 2🌿) avec l'effet : « Quand la Dame des Bosses entre sur le champ, cherchez une Manifestation dans votre Deck et Enchaînez-la, puis mélangez le Deck. Si la Manifestation Enchaînée gagne la confrontation, exilez-la. » Le Joueur B (Colérique) dévoile Gorb le Baraqué (Puissance 6🔥) avec l'effet : « Quand Gorb entre sur le champ, vous ne pouvez pas placer de Manifestations en Soutien sous votre contrôle jusqu'à la fin du tour. »"},{"type":"p","text":"4. Les effets « quand elle entre sur le champ » se déclenchent. Le Joueur A résout l'effet de Dame des Bosses et enchaîne (place en Soutien) Balourd Affable (Puissance 4🌿) depuis le deck. La puissance totale du Joueur A est de 6🌿 (2+4) contre 6🔥 pour le Joueur B. Il y a égalité, mais comme le Colérique domine le Flegmatique, le Joueur A est en désavantage et gagne la Priorité."},{"type":"p","text":"5. Les effets des Premières Manifestations résolus, la Confrontation passe à la sous-phase de Réaction. Le Joueur A, ayant la Priorité, joue la Volonté Accentuer, qui donne « +1 puissance jusqu'à la fin du tour » et cible son Balourd Affable. La carte va sur la Pile."},{"type":"p","text":"6. La Priorité passe au Joueur B. Il paie un Tribut pour jouer Opprimer en réponse, qui met -3 puissance sur une Manifestation, ciblant lui aussi Balourd Affable. La Manifestation utilisée comme Tribut va aux Limbes. Opprimer va au sommet de la Pile. Puis les deux joueurs passent."},{"type":"p","text":"7. La Pile se résout de haut en bas : Opprimer se résout : la Puissance de Balourd Affable tombe à 1 (4-3=1). Opprimer va aux Limbes. Puis Accentuer se résout : la Puissance de Balourd Affable monte à 2 (1+1=2). Accentuer va aux Limbes. La puissance totale du Joueur A est maintenant de 4🌿 (Dame des Bosses 2 + Balourd Affable 2), contre 6🔥 pour Gorb. Le Joueur A est toujours en désavantage et a la Priorité."},{"type":"p","text":"8. Le Joueur A joue Guide Forestier (Puissance 3🌿) en Soutien, atteignant un total de 7🌿. Maintenant que le Joueur A est en tête (7 à 6), la Priorité passe au Joueur B. Cependant, à cause de l'effet de Gorb, il ne peut pas jouer de Manifestations en Soutien et décide de passer. Le Joueur A passe aussi."},{"type":"p","text":"Résolution / Phase Finale"},{"type":"p","text":"9. Comme les deux joueurs ont passé, la Confrontation se résout : le Joueur A gagne la Confrontation avec une puissance totale de 7 contre 6. Gorb le Baraqué est placé dans son Réceptacle Empathique. Le Joueur A décide ensuite où déplacer ses Manifestations :"},{"type":"list","text":"Guide Forestier est placé dans l'Interzone pour continuer à utiliser son effet de Soutien aux tours suivants."},{"type":"list","text":"Dame des Bosses est placée au fond du deck pour être repiochée plus tard."},{"type":"list","text":"Balourd Affable est exilé, comme spécifié par l'effet de Dame des Bosses."},{"type":"p","text":"10. La Phase Finale commence. Le Joueur A, ayant gagné, a la Priorité, mais n'a rien à jouer et passe. Le Joueur B, désormais avec la Priorité, décide de jouer la Volonté Persistante Volcan, qui dit « Payez 🔘🔘🔘🔘 : Exilez toutes les Volontés sur le champ et toutes les Manifestations dans chaque Interzone. » Il la prépare pour un tour futur, avec l'intention d'exiler le Guide Forestier de l'adversaire."},{"type":"p","text":"11. Les deux joueurs passent, et le tour se conclut."},{"type":"h2","text":"Récapitulatif des phases et actions autorisées"},{"type":"note","text":"NOTE : Quand une carte fait référence au fait de sauter une phase, le joueur ne peut accomplir aucune action pendant cette phase, les effets déclenchés des cartes qu'il contrôle ne se déclenchent pas, et les effets continus se référant à cette phase ne sont pas pris en compte."},{"type":"note","text":"NOTE : Les Manifestations ne peuvent entrer dans la Zone de Confrontation que pendant une Confrontation."}],"end-game":[{"type":"h2","text":"Fin de partie et calcul des points"},{"type":"h3","text":"Conditions de fin de partie"},{"type":"p","text":"La partie se termine IMMÉDIATEMENT si l'une des conditions suivantes est remplie :"},{"type":"list","text":"Un joueur, pendant la Phase de Récupération, n'a pas pu piocher assez de cartes pour atteindre la limite de main requise."},{"type":"list","text":"Un joueur, pendant la Phase de Récupération, après son second Mulligan consécutif, n'a toujours pas de Première Manifestation jouable en main. Dans ce cas, ce joueur perd la manche."},{"type":"h3","text":"Calcul des points"},{"type":"p","text":"Une fois la manche terminée :"},{"type":"list","text":"Chaque joueur additionne les valeurs en Points de toutes les cartes Manifestation présentes dans son Réceptacle Empathique à la fin de la manche, ainsi que les Points gagnés ou perdus par les effets de cartes."},{"type":"list","text":"S'il reste des cartes Manifestation dans son deck, le joueur obtient 5 Points bonus pour chaque carte Manifestation restante."},{"type":"note","text":"NOTE : Les cartes encore dans la Zone d'Impasse à la fin de la manche ne sont pas prises en compte dans le calcul des points."},{"type":"h3","text":"Condition de victoire"},{"type":"victory","text":"Le joueur ayant le total de Points le plus élevé gagne la manche. En cas d'égalité de Points, la manche est un match nul."}],"multiplayer":[{"type":"h2","text":"Modes multijoueurs"},{"type":"h2","text":"Chacun pour soi (Free-for-All)"},{"type":"p","text":"Mode pour 3 à 5 joueurs s'affrontant en même temps. C'est le format idéal pour une expérience de jeu plus décontractée et imprévisible. Les règles de base de Kartomantik restent valables, avec les modifications et ajouts suivants."},{"type":"h3","text":"Priorité"},{"type":"p","text":"Pendant une Confrontation en Chacun pour soi, la Priorité se transmet en fonction du Désavantage, qui est le nombre de joueurs par lesquels on serait battu individuellement en Puissance ou en Tempérament :"},{"type":"list","text":"Le joueur qui a la Priorité est le joueur en désavantage absolu, c'est-à-dire celui qui serait battu par chaque autre joueur."},{"type":"list","text":"Si le joueur qui a la Priorité passe sur une Pile vide, la Priorité va au joueur ayant le désavantage le plus élevé après lui."},{"type":"list","text":"S'il y a plusieurs joueurs avec le même désavantage, la Priorité passe plutôt au joueur le plus proche, dans le sens horaire, du joueur qui cède la Priorité."},{"type":"list","text":"Si un joueur en désavantage passe, il ne peut pas obtenir de nouveau la Priorité tant qu'un autre joueur n'a pas accompli d'action, redonnant la Priorité au joueur ayant le plus grand désavantage."},{"type":"p","text":"Quand, sur une Pile vide, tous les joueurs ont passé consécutivement, le tour passe à la phase suivante."},{"type":"p","text":"En dehors de la Confrontation ou en cas d'Impasse, le joueur ayant gagné la dernière Confrontation résolue a la Priorité, et la Priorité se transmet dans le sens horaire."},{"type":"p","text":"Si l'on ne peut pas décider qui a la Priorité, appuyez-vous sur les règles de base de la Priorité."},{"type":"h3","text":"La Pile"},{"type":"list","text":"Quand un joueur ayant la Priorité accomplit une action, elle est placée au sommet de la Pile. La Priorité passe immédiatement au joueur suivant dans le sens horaire."},{"type":"list","text":"Les joueurs continuent de se transmettre la Priorité dans le sens horaire, ajoutant des actions à la Pile ou passant."},{"type":"list","text":"La Pile ne commence à se résoudre que lorsque tous les joueurs ont passé consécutivement."},{"type":"h3","text":"Résolution et Impasse"},{"type":"list","text":"Un joueur ne gagne une Confrontation que si sa Puissance totale et son Tempérament (si nécessaire) lui permettraient de vaincre individuellement chaque autre joueur présent dans la Confrontation. La Résolution se déroule normalement, en plaçant toutes les Manifestations adverses de la Confrontation et de l'Impasse dans son propre Réceptacle Empathique. (Il est recommandé d'avoir des piles séparées pour chaque joueur.)"},{"type":"list","text":"La Confrontation se termine en revanche par une Impasse dans tous les cas où il n'y a pas de vainqueur unique. Par exemple :"},{"type":"list","text":"Si les dernières Manifestations entrées dans la Confrontation des deux joueurs ayant la puissance totale la plus élevée ont le même Tempérament."},{"type":"list","text":"Si une chaîne de dominance se crée entre les Tempéraments (par ex. le Joueur A bat B, B bat C, et C bat A)."},{"type":"h3","text":"Phase Finale"},{"type":"p","text":"Chaque fois que, pendant la Phase Finale, une Pile initiée par un joueur se résout complètement, la Priorité passe au joueur le plus proche dans le sens horaire."},{"type":"h3","text":"Fin de partie"},{"type":"p","text":"Si un joueur ne peut pas atteindre la limite de main requise pendant la Récupération ou perd la partie, par exemple à cause de deux Mulligans consécutifs, la partie NE se termine PAS. Ce joueur ne peut plus participer aux Confrontations, mais conserve le droit de jouer des Volontés et d'activer des effets."},{"type":"p","text":"La partie continue tant qu'au moins deux joueurs sont encore capables d'atteindre la limite de main pendant leur Récupération."},{"type":"h2","text":"Mode 2 contre 2"},{"type":"p","text":"Mode à quatre joueurs pour une confrontation en équipe. Il est conçu pour ceux qui recherchent une dynamique de groupe basée sur la coordination entre coéquipiers. Les règles de base restent valables, avec les modifications et ajouts suivants."},{"type":"h3","text":"Construction du deck"},{"type":"list","text":"Chaque deck doit être composé d'exactement 21 cartes."},{"type":"list","text":"La somme des Points de toutes les Manifestations du deck ne doit pas dépasser 400."},{"type":"list","text":"Comme dans les règles de base, il ne peut y avoir plus d'un exemplaire de la même carte dans son propre deck."},{"type":"h3","text":"Zones de jeu"},{"type":"p","text":"L'équipe partage un seul Interzone étendu à 4 espaces au total. Elle partage aussi le Champ et la Zone de Confrontation. Les Limbes, le Deck, la Main et le Réceptacle Empathique restent en revanche séparés."},{"type":"note","text":"NOTE : Les joueurs ne peuvent pas regarder la main de leur coéquipier."},{"type":"h3","text":"Contrôle des cartes"},{"type":"p","text":"Quand le texte d'une carte fait référence à des cartes ou effets sous le contrôle d'un joueur, considérez aussi les cartes ou effets contrôlés par son coéquipier."},{"type":"p","text":"La propriété et le contrôle de chaque carte restent à son propriétaire et ne peuvent pas être partagés."},{"type":"h3","text":"Priorité"},{"type":"p","text":"En dehors de la Pile, la Priorité est attribuée à l'équipe, comme s'il s'agissait de joueurs uniques, en suivant les règles de base (par ex. l'équipe qui perdrait la Confrontation à cet instant a la Priorité, ou l'équipe qui a gagné la dernière Confrontation). Quand une équipe obtient la Priorité, les deux joueurs décident ensemble lequel des deux l'utilisera pour accomplir une action (jouer une Volonté, activer un effet, etc.). S'ils choisissent de passer, la Priorité passe à l'équipe adverse."},{"type":"h3","text":"La Pile"},{"type":"p","text":"Pour que chacun puisse réagir, la Pile utilise la logique du Chacun pour soi :"},{"type":"list","text":"Quand un joueur ayant la Priorité accomplit une action, elle est placée au sommet de la Pile. La Priorité passe immédiatement au joueur suivant dans le sens horaire."},{"type":"list","text":"Les joueurs continuent de se transmettre la Priorité dans le sens horaire, ajoutant des actions à la Pile ou passant."},{"type":"list","text":"La Pile ne commence à se résoudre que lorsque les quatre joueurs passent consécutivement."},{"type":"h3","text":"Révélation"},{"type":"p","text":"Chaque équipe ne peut avoir qu'une seule Première Manifestation sur le champ. À la Révélation, les joueurs de chaque équipe décident lequel des deux doit choisir la Première Manifestation. Quand les deux équipes ont choisi, les joueurs dévoilent la Première Manifestation choisie et la placent de leur côté de la Zone de Confrontation. La Révélation et la Réaction se déroulent comme dans les règles de base."},{"type":"h3","text":"Résolution"},{"type":"list","text":"Pour déterminer le résultat d'une Confrontation, additionnez la Puissance totale de toutes les Manifestations contrôlées par les deux joueurs de l'Équipe A, contre la Puissance totale de toutes les Manifestations de l'Équipe B, comme s'il s'agissait de joueurs uniques, en suivant les règles de base."},{"type":"list","text":"Quand une équipe gagne la Confrontation : les deux joueurs de l'équipe gagnante décident entre eux dans lequel des deux Réceptacles Empathiques placer les Manifestations de l'équipe adverse. Ils décident quelles Manifestations placer dans l'Interzone, ou au fond des decks de leurs propriétaires respectifs."},{"type":"h3","text":"Fin de partie"},{"type":"p","text":"Si un ou plusieurs joueurs ne peuvent pas atteindre la limite de main requise pendant la Récupération, mais que leur coéquipier le peut, la partie ne se termine pas immédiatement : le dernier tour est joué. Ces joueurs peuvent encore participer et utiliser toutes les cartes à leur disposition."},{"type":"p","text":"Si un joueur perd la partie, par exemple à cause de deux Mulligans consécutifs, son équipe perd."},{"type":"h3","text":"Calcul des points et victoire"},{"type":"p","text":"À la fin de la partie, le score de l'équipe se calcule en additionnant le total des Points présents dans les Réceptacles Empathiques des deux joueurs, et en comptant les points bonus des deux pour les Manifestations encore dans leurs decks. L'équipe ayant le total combiné le plus élevé gagne la partie."},{"type":"p","text":"En cas de conditions de victoire ou de défaite alternatives, elles sont partagées par les joueurs."}],"bazaar":[{"type":"h2","text":"Mode Draft Bazaar"},{"type":"p","text":"Mode de draft aux enchères pour 2 à 6 joueurs. Les joueurs rivalisent pour acquérir les cartes les plus précieuses via un système d'enchères libres, puis s'affrontent dans un tournoi où chaque joueur défie chaque autre joueur exactement une fois. La victoire se mesure à la capacité d'accumuler des points sur l'ensemble des matchs du tournoi."},{"type":"h3","text":"Préparation du draft"},{"type":"h4","text":"Diviser les cartes"},{"type":"p","text":"Séparez toutes les cartes du set en 4 piles distinctes :"},{"type":"list","text":"Pile des Volontés : toutes les cartes Volonté (Éphémères et Persistantes)."},{"type":"list","text":"Pile des Manifestations mineures : Manifestations de 0 à 15 Points."},{"type":"list","text":"Pile des Manifestations moyennes : Manifestations de 20 à 35 Points."},{"type":"list","text":"Pile des Manifestations majeures : Manifestations de 40 à 50 Points."},{"type":"p","text":"Mélangez soigneusement chaque pile."},{"type":"note","text":"NOTE : La composition des piles peut être modifiée selon les préférences du groupe. Par exemple, il est recommandé de retirer les cartes « Fureur Atavique » (235), « Volatilité Atavique » (188), « Oppression Atavique » (141), « Introspection Atavique » (94), « Accueil Atavique » (47), ainsi que toutes les Volontés Persistantes multi-Tempérament, pour mieux équilibrer le draft. Vous pouvez personnaliser les cartes à inclure dans chaque pile, tant qu'il y a assez de cartes pour compléter le draft avec le nombre de joueurs prévu."},{"type":"h4","text":"Créer le Deck de Draft"},{"type":"p","text":"Selon le nombre de joueurs, piochez le nombre indiqué de cartes dans chaque pile selon ce tableau :"},{"type":"p","text":"Combinez toutes les cartes piochées en un seul deck et mélangez-le soigneusement. Ce sera le Deck de Draft."},{"type":"h3","text":"Jouer le draft"},{"type":"h4","text":"Phase de Dévoilement"},{"type":"list","text":"Dévoilez et placez sur la table un nombre de cartes du Deck de Draft égal au double du nombre de joueurs (par ex. 3 joueurs = 6 cartes dévoilées, 4 joueurs = 8 cartes dévoilées, etc.)."},{"type":"list","text":"Déterminez l'ordre de départ par un lancer de dé (celui qui obtient le plus haut résultat commence). Continuez dans le sens horaire à partir de ce joueur."},{"type":"h4","text":"Phase de Sélection et d'Enchères"},{"type":"p","text":"Tour du joueur :"},{"type":"list","text":"Le joueur actif choisit l'une des cartes dévoilées sur la table. Cela ouvre une enchère pour cette carte."},{"type":"list","text":"Tout autre joueur peut lancer l'enchère en faisant une offre (minimum 5 Points, ou tout multiple de 5)."},{"type":"list","text":"L'enchère se poursuit, les joueurs enchérissant à tour de rôle, selon ces règles :"},{"type":"list","text":"Autres joueurs : peuvent seulement monter l'enchère, en offrant un montant supérieur à l'enchère actuelle (chaque offre doit se faire par paliers de 5 Points). Il n'y a pas de limite aux points qu'un joueur peut miser."},{"type":"list","text":"Joueur actif : a un droit spécial. Après chaque offre d'un autre joueur, il peut choisir d'égaler l'offre pour devenir le plus offrant, ou de la surenchérir lui-même."},{"type":"list","text":"L'enchère se termine quand, après une offre, tous les autres joueurs choisissent de « passer » et de ne pas monter l'enchère. Si personne n'a fait d'offre, le joueur actif prend la carte gratuitement. Sinon, le joueur ayant fait la dernière offre la plus élevée remporte la carte et note les Points dépensés, qui serviront au Calcul de la Dette."},{"type":"p","text":"Si le joueur actif a perdu l'enchère, il rejoue immédiatement en choisissant une autre carte. Sinon, le tour passe au joueur suivant."},{"type":"p","text":"Ordre de draft en serpent :"},{"type":"p","text":"Le draft suit un ordre en serpent pour équilibrer l'avantage du choix. Ce schéma ne s'applique qu'au sein d'un même lot de cartes dévoilées et se réinitialise chaque fois que la table est réapprovisionnée."},{"type":"p","text":"Exemple avec 4 joueurs (A, B, C, D) : la sélection pour chaque groupe de cartes dévoilées se déroule ainsi :"},{"type":"list","text":"Manche 1 (sens horaire) : le premier joueur (A) choisit une carte, suivi du deuxième, et ainsi de suite, jusqu'au dernier joueur de la manche (D) : (A → B → C → D)."},{"type":"list","text":"Manche 2 (sens anti-horaire) : le dernier joueur (D), qui vient de choisir sa première carte, entame immédiatement la deuxième manche en en choisissant une autre. L'ordre se déroule ensuite à l'envers : (D → C → B → A)."},{"type":"p","text":"Pour le lot de cartes suivant, les joueurs recommencent depuis le premier joueur comme à la Manche 1, et ainsi de suite."},{"type":"p","text":"Limite d'Acquisition :"},{"type":"list","text":"Chaque joueur peut acquérir au maximum 2 cartes avant que la table ne soit réapprovisionnée."},{"type":"list","text":"Quand c'est le tour d'un joueur ayant déjà pris 2 cartes, ce joueur saute son tour et ne peut pas participer aux enchères jusqu'au réapprovisionnement de la table."},{"type":"h4","text":"Réapprovisionner la table"},{"type":"p","text":"Quand toutes les cartes dévoilées ont été prises, dévoilez de nouvelles cartes du Deck de Draft (un nombre égal au double du nombre de joueurs)."},{"type":"h4","text":"Conclusion du draft"},{"type":"p","text":"Le draft se termine quand :"},{"type":"list","text":"Le Deck de Draft est épuisé."},{"type":"list","text":"Chaque joueur a acquis exactement 36 cartes."},{"type":"p","text":"Après le draft, chaque joueur construit un deck d'exactement 30 cartes, un seul exemplaire de chaque, parmi les 36 acquises. Contrairement au mode standard, il n'y a aucune limite au total de Points que le deck peut contenir."},{"type":"h3","text":"Calcul de la Dette"},{"type":"p","text":"Avant le début du tournoi, chaque joueur calcule sa Dette :"},{"type":"list","text":"Additionnez les Points de toutes les Manifestations de votre deck de 30 cartes."},{"type":"list","text":"Additionnez tous les Points dépensés en enchères pendant le draft."},{"type":"list","text":"Additionnez les deux valeurs précédentes."},{"type":"list","text":"Si ce total dépasse 500 Points, le montant excédentaire est compté comme Dette et doit être noté."},{"type":"p","text":"Exemple : un joueur a un deck totalisant 480 Points et a dépensé 100 points en enchères. Le total est de 580 Points (480 Points de Manifestations + 100 Points d'enchères = 580 Points au total). Comme le joueur a dépassé le seuil de 500 Points de 80, il aura une Dette de 80 points."},{"type":"h3","text":"Tournoi et condition de victoire"},{"type":"p","text":"Chaque joueur affronte chaque autre joueur exactement une fois. Les matchs suivent les règles standard de Kartomantik."},{"type":"p","text":"À la fin du tournoi, chaque joueur additionne tous les points gagnés dans tous les matchs joués et soustrait ses points de Dette de ce total. Le joueur ayant le score final le plus élevé gagne le draft."},{"type":"p","text":"En cas d'égalité entre deux joueurs ou plus, les joueurs à égalité s'affrontent dans un match de départage."}],"keywords":[{"type":"h2","text":"Mots-clés"},{"type":"p","text":"(Présentés dans l'ordre alphabétique de la version originale.)"},{"type":"p","text":"Sur le point de : un timing spécial, qui interrompt le déroulement normal du jeu pour appliquer des effets, juste avant que l'événement « sur le point de » se produire n'ait lieu."},{"type":"p","text":"Puissance de base : la valeur de puissance imprimée sur la carte, avant tout modificateur."},{"type":"p","text":"Annuler : l'effet annulé ne peut pas se résoudre."},{"type":"p","text":"Enchaîner : placez une Manifestation sous votre contrôle en Soutien. Une fois entrée sur le champ, elle est considérée comme jouée et Enchaînée."},{"type":"p","text":"Dissimuler : une carte Dissimulée est placée face cachée dans la zone spécifiée par l'effet. Tant qu'elle est Dissimulée, toutes ses caractéristiques, sauf le Type, ne peuvent être consultées que par son contrôleur."},{"type":"p","text":"Zone de Confrontation : zone partagée où sont placées toutes les Manifestations qui sont jouées et placées dans la Confrontation."},{"type":"p","text":"Contrôleur : le contrôleur est le joueur qui peut jouer les cartes et activer leurs effets. Si un joueur contrôle une carte dont il n'est pas le propriétaire, quand la carte quitte le champ ou la Zone d'Impasse, elle revient sous le contrôle de son propriétaire."},{"type":"p","text":"Copier : crée une copie d'une carte. Sauf indication contraire, la copie n'a que les caractéristiques imprimées d'origine de la carte copiée (nom, tempérament, coût, puissance, texte) et n'hérite ni des modificateurs ni des marqueurs. Les copies ne sont pas considérées comme jouées."},{"type":"p","text":"Marqueur : objet servant à noter les changements apportés par les effets sur une carte."},{"type":"p","text":"Actuellement : au moment où la carte ou l'effet se résout sur la Pile."},{"type":"p","text":"Détruire : placez la carte détruite dans les Limbes de son propriétaire."},{"type":"p","text":"Défausser : placez les cartes défaussées dans les Limbes, depuis la main ou depuis le deck."},{"type":"p","text":"Réceptacle Empathique : zone où s'accumulent les Manifestations adverses ayant perdu la Confrontation."},{"type":"p","text":"Volontés Éphémères : cartes qui peuvent être jouées en payant un Tribut. Elles peuvent être jouées en réponse après la Révélation. Une fois leur effet résolu sur la Pile, elles sont déplacées vers les Limbes."},{"type":"p","text":"Épuiser : tournez la carte à l'horizontale. Elle ne peut pas être épuisée de nouveau tant qu'elle n'est pas restaurée, au début du tour ou via des effets."},{"type":"p","text":"Exiler : placez la carte dans la zone d'Exil de son propriétaire, la rendant inaccessible pour le reste de la partie."},{"type":"p","text":"Champ : le Champ Cartomantique, la zone de jeu qui comprend l'Interzone et la Confrontation, et où sont placées les Volontés Persistantes jouées."},{"type":"p","text":"Première Manifestation : la Manifestation jouée à la Révélation par son contrôleur. Si cette carte quitte la Confrontation, son contrôleur doit choisir une autre de ses Manifestations dans la Confrontation comme nouvelle Première Manifestation. Si un joueur ne contrôle aucune Manifestation dans la Zone de Confrontation, au moment où il joue ou place une Manifestation en Soutien, cette dernière entre comme Première Manifestation."},{"type":"p","text":"Gagner / Perdre des Points : ajoutez ou retirez la valeur spécifiée au total de points du Réceptacle Empathique du joueur. Les points du Réceptacle Empathique peuvent aussi devenir négatifs et sont indépendants des points des Manifestations capturées."},{"type":"p","text":"Gagne -/+ puissance : diminue ou augmente la puissance de la Manifestation ; la Manifestation garde le même Tempérament. Quand une Manifestation atteint 0 puissance ou moins, elle est détruite."},{"type":"p","text":"Effet Immédiat : un effet auquel il n'est pas possible de répondre ; il se résout sur la Pile en priorité sur les autres effets. Si un Effet Immédiat se déclenche à la Révélation, il se déclenche et se résout sur la Pile avant que les autres effets déclenchés aient l'occasion d'entrer sur la Pile."},{"type":"p","text":"Immunité : les cartes et joueurs immunisés ne sont influencés d'aucune manière par la source spécifiée."},{"type":"p","text":"en Soutien : toute Manifestation qui se trouve dans la Zone de Confrontation et y est entrée alors qu'une Première Manifestation était déjà présente est dite « en Soutien »."},{"type":"p","text":"Interzone : zone où le joueur peut placer jusqu'à 3 de ses Manifestations ayant gagné une Confrontation pour continuer à exploiter leurs effets de Soutien, ou leurs effets continus et déclenchés qui exigent que la Manifestation soit « sur le champ ». Ces Manifestations peuvent être remplacées en les plaçant au fond de son Deck chaque fois qu'une autre devrait entrer."},{"type":"p","text":"Limbes : zone où sont placées les Volontés Éphémères résolues, les Manifestations utilisées comme Tribut et les cartes détruites."},{"type":"p","text":"Modificateur : tout changement temporaire ou permanent des caractéristiques d'une carte (puissance, tempérament, etc.) causé par un effet."},{"type":"p","text":"Neutraliser : annulez l'effet de la carte neutralisée et envoyez-la dans les Limbes de son propriétaire."},{"type":"p","text":"Propriétaire : vous êtes toujours le Propriétaire de toutes les cartes présentes dans votre deck au début de la partie."},{"type":"p","text":"Ténacité : si une Manifestation avec Ténacité a gagné la confrontation, elle reste dans la Zone de Confrontation comme Première Manifestation."},{"type":"p","text":"Volontés Persistantes : cartes qui peuvent être jouées en payant un Tribut. Elles ne peuvent être jouées que sur une Pile vide pendant la Phase Finale et, une fois résolues sur la Pile, elles entrent sur le champ. Comme condition d'activation de leurs effets, toutes les Volontés Persistantes doivent être sur le champ."},{"type":"p","text":"Points : sauf s'il est précisé « d'une Manifestation », le terme désigne les points du Réceptacle Empathique."},{"type":"p","text":"Protection : les cartes et joueurs Protégés ne peuvent pas être choisis comme cibles par la source spécifiée. Les Manifestations Protégées ne peuvent pas recevoir de Modificateurs de la source spécifiée."},{"type":"p","text":"Réduire : diminuez la puissance de la Manifestation. C'est un coût alternatif pour l'activation des effets de certaines cartes ; il n'est donc pas considéré comme une diminution de puissance via des cartes ou des effets."},{"type":"p","text":"Restaurer : remettez une carte épuisée en position verticale. Cette carte peut de nouveau être épuisée."},{"type":"p","text":"Sacrifier : placez votre Manifestation sacrifiée dans les Limbes comme coût d'un effet."},{"type":"p","text":"Montrer : montrez la carte (ou les cartes) à votre adversaire, puis remettez-la dans sa zone d'origine, sauf indication contraire de l'effet."},{"type":"p","text":"Zone d'Impasse : zone spéciale où sont placées les Manifestations impliquées dans une Impasse. Le contrôleur et les Modificateurs restent inchangés."},{"type":"p","text":"Soutien : une Manifestation avec Soutien peut entrer dans la Confrontation, depuis la main ou depuis l'Interzone, après la Première Manifestation. Si « depuis la main » est précisé, elle ne peut être jouée en Soutien qu'à partir de la main."},{"type":"p","text":"Cible : l'élément (une carte, un joueur, etc.) que le contrôleur de l'effet ou de la carte doit choisir pour qu'il ait un effet."},{"type":"p","text":"Jeton : une Manifestation ou une Volonté créée par les effets d'autres cartes. Si un jeton quitte le Champ Cartomantique, il est exilé. Sauf indication contraire, les jetons de Manifestation sont exilés à la Résolution."},{"type":"p","text":"Dévoiler : placez une ou plusieurs cartes face visible."}],"errata":[{"type":"h2","text":"Intégrations et Errata"},{"type":"p","text":"Mises à jour concernant la transition vers l'édition Beta de Kartomantik. Voici les principales nouveautés :"},{"type":"p","text":"Prise en charge du multijoueur : le design des cartes a été préparé pour l'intégration des modes multijoueurs."},{"type":"p","text":"Nouveaux mots-clés : pour alléger le texte et améliorer la lisibilité, certaines mécaniques récurrentes ont été résumées en ces mots-clés : « Une fois par tour » → Épuiser ; « Jouer comme si elle avait Soutien » → Enchaîner."},{"type":"p","text":"Cibles : pour réduire l'ambiguïté des effets, le mot « ciblé(e) » a été ajouté aux cartes qui nécessitaient d'en choisir une."},{"type":"p","text":"Refontes de texte : plusieurs cartes ont été modifiées pour améliorer leur équilibre. Vous pouvez consulter ci-dessous la liste des changements les plus importants."},{"type":"h2","text":"Principaux changements"},{"type":"p","text":"80 — Entité Bleue — Manifestation · 45 pts · 💧💧💧"},{"type":"p","text":"Ancien texte : « Tant que l'Entité Bleue est sur le champ, à chaque fois que vous jouez une volonté, toutes les Manifestations sur le champ que vous contrôlez gagnent +1 puissance jusqu'à la fin du tour. »"},{"type":"p","text":"Nouveau texte : « Tant que l'Entité Bleue est dans la Zone de Confrontation, à chaque fois que vous jouez une Volonté, toutes les autres Manifestations que vous contrôlez dans la Zone de Confrontation gagnent +1 puissance jusqu'à la fin du tour. »"},{"type":"p","text":"83 — Entrevoir les Présages — Volonté Éphémère · 💧💧"},{"type":"p","text":"Ancien texte : « Regardez les 4 cartes du dessus de votre Deck. Placez ces cartes sur le dessus ou au fond de votre Deck dans l'ordre de votre choix, puis piochez 3 cartes. »"},{"type":"p","text":"Nouveau texte : « Regardez les 4 cartes du dessus de votre Deck. Répartissez autant de ces cartes que vous voulez sur le dessus et au fond de votre Deck dans l'ordre de votre choix, puis piochez 1 carte. »"},{"type":"p","text":"81 — Malaleuco, le Façonneur de Volontés — Manifestation · 50 pts · 💧💧"},{"type":"p","text":"Ancien texte : « Tant que Malaleuco est dans l'Interzone, à chaque fois que vous jouez une volonté, vous pouvez la copier. Vous pouvez choisir de nouvelles cibles pour la copie. Si Malaleuco est dans votre main et qu'il y a de la place dans votre Interzone, vous pouvez payer 💧💧💧💧 : si vous le faites, placez-le dans votre Interzone. »"},{"type":"p","text":"Nouveau texte : « Tant que Malaleuco est dans l'Interzone, vous pouvez l'épuiser pour copier une Volonté que vous contrôlez sur la Pile. Vous pouvez choisir une nouvelle cible pour la copie. Si Malaleuco est en main et qu'il y a de la place dans votre Interzone, vous pouvez payer 💧💧💧 : placez-le dans votre Interzone. »"},{"type":"p","text":"76 — Shymon, le Cerveau — Manifestation · 35 pts · 💧💧💧💧"},{"type":"p","text":"Ancien texte : « Tant que Shymon est sur le champ, une fois par tour, il peut gagner -2 puissance : l'adversaire ne pioche pas lors de la prochaine Phase de Récupération. »"},{"type":"p","text":"Nouveau texte : « Tant qu'il est sur le champ, vous pouvez épuiser Shymon et réduire sa puissance de 2 : au tour suivant, un adversaire ciblé ne peut pas piocher de cartes en dehors de la Phase de Récupération jusqu'à la fin de ce tour. »"},{"type":"p","text":"184 — Dévier — Volonté Éphémère · ⚡⚡"},{"type":"p","text":"Ancien texte : « Détruisez une Manifestation sur le point d'entrer dans un Réceptacle Empathique. »"},{"type":"p","text":"Nouveau texte : « Perdez 5 points. Vous ne pouvez jouer cette Volonté que pendant la Résolution. Détruisez une Manifestation ciblée dans la Zone de Confrontation qui a perdu la confrontation ce tour-ci. »"},{"type":"p","text":"175 — Katun, l'Inconstant — Manifestation · 50 pts · ⚡⚡⚡⚡⚡"},{"type":"p","text":"Ancien texte : « Tant que Katun est dans l'Interzone, à chaque fois qu'une Manifestation quitte le champ, des Limbes, un Réceptacle Empathique ou une Zone d'Impasse à cause de l'effet d'une carte que vous contrôlez, gagnez 5 points. Si Katun a plutôt été récupéré d'un Réceptacle Empathique, à chaque fois que vous déclenchez ses effets, gagnez 10 points. »"},{"type":"p","text":"Nouveau texte : « Tant que Katun est dans l'Interzone, à chaque fois qu'une Manifestation quitte le champ, des Limbes, un Réceptacle Empathique ou la Zone d'Impasse à cause de cartes ou d'effets, vous gagnez 5 points. Si Katun a quitté un Réceptacle Empathique au cours de la partie, alors, à la place, à chaque fois que vous déclenchez ses effets, vous gagnez 10 points. »"},{"type":"p","text":"206 — Gorb le Baraqué — Manifestation · 25 pts · 🔥🔥🔥🔥🔥🔥"},{"type":"p","text":"Ancien texte : « Quand Gorb entre sur le champ, vous ne pouvez pas jouer de Manifestations en Soutien jusqu'à la fin du tour. »"},{"type":"p","text":"Nouveau texte : « Quand Gorb entre sur le champ, vous ne pouvez pas placer de Manifestations en Soutien sous votre contrôle jusqu'à la fin du tour. »"},{"type":"p","text":"208 — Numbi, l'Agaçant — Manifestation · 25 pts · 🔥🔥🔥🔥"},{"type":"p","text":"Ancien texte : « Tant que Numbi est dans l'Interzone, après la Révélation vous pouvez forcer l'adversaire à jouer une Manifestation de sa main comme si elle avait Soutien. Si l'adversaire ne le peut pas, il vous montre sa main. »"},{"type":"p","text":"Nouveau texte : « Tant que Numbi est dans l'Interzone, après la Révélation vous pouvez forcer un adversaire ciblé à Enchaîner depuis sa main. Si l'adversaire le peut, la Première Manifestation que vous contrôlez gagne +2 puissance jusqu'à la fin du tour. Si l'adversaire ne le peut pas, il révèle sa main. »"},{"type":"p","text":"211 — Quorum, l'Intouchable — Manifestation · 30 pts · 🔥🔥"},{"type":"p","text":"Ancien texte : « Quand Quorum entre sur le champ, vous pouvez défausser autant de Volontés que vous voulez de votre main : Quorum gagne +3 puissance pour chaque Volonté ainsi défaussée. »"},{"type":"p","text":"Nouveau texte : « Quand Quorum entre sur le champ, vous pouvez défausser autant de Volontés que vous voulez de votre main. Quorum gagne +3 puissance jusqu'à la fin du tour pour chaque Volonté ainsi défaussée. »"},{"type":"p","text":"42 — Inflorescence Altruiste — Volonté Persistante · 🌿🌿🌿"},{"type":"p","text":"Ancien texte : « Une Manifestation sur le champ a Soutien en plus de ses autres effets. »"},{"type":"p","text":"Nouveau texte : « Quand l'Inflorescence Altruiste entre sur le champ, choisissez une Manifestation ciblée sur le champ. Cette Manifestation a Soutien en plus de ses autres effets. Lors de la Phase Finale, vous pouvez épuiser cette carte et payer 🌿🌿🌿 : changez la cible de l'effet de cette carte. »"},{"type":"p","text":"35 — Gargullo, Roi des Bois — Manifestation · 50 pts · 🌿"},{"type":"p","text":"Ancien texte : « Tant que Gargullo est sur le champ, chaque Manifestation en Soutien que vous contrôlez gagne +1 puissance pendant la confrontation pour chaque autre Manifestation que vous contrôlez dans la confrontation. »"},{"type":"p","text":"Nouveau texte : « Tant que Gargullo est sur le champ, pendant la confrontation chaque Manifestation non-jeton en Soutien que vous contrôlez gagne +1 puissance pour chaque autre Manifestation non-jeton que vous contrôlez dans la Zone de Confrontation. »"},{"type":"p","text":"37 — Plaidoyer pour la Générosité — Volonté Éphémère · 🌿🌿"},{"type":"p","text":"Ancien texte : « Gagnez 5 points pour chaque Manifestation dans une confrontation. »"},{"type":"p","text":"Nouveau texte : « Gagnez 5 points pour chaque Manifestation non-jeton dans la Zone de Confrontation sous le contrôle d'un joueur ciblé. »"},{"type":"p","text":"21 — Incubateur Spontané — Manifestation · 25 pts · 🌿🌿🌿🌿"},{"type":"p","text":"Ancien texte : « Tant que l'Incubateur Spontané est dans l'Interzone, au début du tour, vous gagnez 5 points. »"},{"type":"p","text":"Nouveau texte : « Tant que l'Incubateur Spontané est dans l'Interzone, au début du tour vous gagnez 10 points. »"},{"type":"p","text":"33 — Tong, l'Expansif — Manifestation · 45 pts · 🌿🌿🌿🌿 → 🌿🌿🌿🌿🌿🌿"},{"type":"p","text":"Ancien texte : « Tant que Tong est sur le champ, augmentez de 3 le nombre d'espaces de votre Interzone. »"},{"type":"p","text":"Nouveau texte : texte inchangé ; seul le coût/puissance passe de 🌿🌿🌿🌿 à 🌿🌿🌿🌿🌿🌿."},{"type":"p","text":"128 — Ergorath, Scribe des Limbes — Manifestation · 50 pts · 🔮"},{"type":"p","text":"Ancien texte : « Tant qu'Ergorath est sur le champ, vous pouvez jouer des Volontés de vos Limbes en payant 1 🔘 au lieu de leur coût de Tribut normal. Si les Volontés jouées ainsi devaient entrer dans des Limbes, une main ou un Deck, exilez-les à la place. »"},{"type":"p","text":"Nouveau texte : « Tant qu'Ergorath est sur le champ, vous pouvez jouer des Volontés de vos Limbes en payant 1 🔘 au lieu de leur coût de Tribut normal. Si les Volontés jouées ainsi doivent entrer dans des Limbes, une main ou un Deck, exilez-les à la place. Si à la fin du tour Ergorath est dans l'Interzone, son contrôleur perd 10 points, puis il est mélangé dans le Deck de son propriétaire. »"},{"type":"p","text":"138 — Mâchoire Écorcheuse — Volonté Persistante · 🔮🔮"},{"type":"p","text":"Ancien texte : « Quand la Mâchoire Écorcheuse entre sur le champ, choisissez une Manifestation sur le champ. Cette Manifestation gagne -2 puissance à la fin du tour. Lors de la Phase Finale, une fois par tour, vous pouvez payer 🔮 : changez la cible de cette volonté. »"},{"type":"p","text":"Nouveau texte : « Quand la Mâchoire Écorcheuse entre sur le champ, choisissez une Manifestation ciblée sur le champ. Cette Manifestation gagne -2 puissance. Lors de la Phase Finale, vous pouvez épuiser cette carte et payer 🔮 : changez la cible de l'effet de cette carte. »"},{"type":"p","text":"114 — Lament, Annule-Pensées — Manifestation · 25 pts · 🔮🔮"},{"type":"p","text":"Ancien texte : « Soutien depuis la main. Ne peut pas être jouée comme Première Manifestation. Quand Lament entre dans une confrontation, chaque joueur défausse une carte du dessus de son deck pour chaque Manifestation que vous contrôlez dans cette confrontation. »"},{"type":"p","text":"Nouveau texte : « Soutien depuis la main. Ne peut pas être jouée comme Première Manifestation. Quand Lament entre dans la Zone de Confrontation, un joueur ciblé défausse une carte du dessus de son Deck pour chaque Manifestation non-jeton qu'il contrôle dans la Zone de Confrontation. »"},{"type":"p","text":"109 — Pyramide Possédée — Manifestation · 20 pts · 🔮"},{"type":"p","text":"Ancien texte : « Soutien depuis la main. Quand la Pyramide Possédée entre dans le Réceptacle Empathique d'un adversaire, ce joueur saute la prochaine Phase de Récupération. »"},{"type":"p","text":"Nouveau texte : « Soutien depuis la main. Quand la Pyramide Possédée entre dans le Réceptacle Empathique d'un adversaire, au tour suivant la main de ce joueur est réduite de 1. Pendant ce tour, toute carte excédentaire dans sa main doit être immédiatement défaussée. »"},{"type":"p","text":"241 — Presse Alchimique — Volonté Persistante · 💧💧🔮🔮"},{"type":"p","text":"Ancien texte : « Vous pouvez utiliser des Manifestations de vos Limbes pour payer des Tributs. Si vous le faites, exilez-les. À chaque fois que vous jouez une volonté, vous pouvez piocher une carte. Si vous le faites, défaussez une carte de votre main. »"},{"type":"p","text":"Nouveau texte : « La Presse Alchimique entre sur le champ avec 5 marqueurs Formule. Tant qu'il y a des marqueurs Formule sur la Presse Alchimique, vous pouvez utiliser les Manifestations de vos Limbes pour payer des Tributs. Si vous le faites, exilez cette Manifestation et retirez un marqueur Formule de la Presse Alchimique. À chaque fois que vous jouez une Volonté, vous pouvez défausser une carte. Si vous le faites, piochez une carte. »"},{"type":"p","text":"244 — Matrice Extorqueuse — Volonté Persistante · 🔥🔥 🌿🌿"},{"type":"p","text":"Ancien texte : « Après la Révélation, l'adversaire peut choisir de vous montrer sa main. S'il le fait, vous choisissez une Manifestation parmi celles-ci, et l'adversaire doit la jouer comme si elle avait Soutien. Si l'adversaire ne vous montre pas sa main ou ne peut pas jouer de Manifestations, vous pouvez placer un jeton 🔘 de 2 puissance dans la confrontation comme Soutien. »"},{"type":"p","text":"Nouveau texte : « Après la Révélation, un adversaire ciblé peut vous montrer sa main. S'il le fait, choisissez une Manifestation parmi celles-ci ; l'adversaire Enchaîne cette Manifestation. Si l'adversaire ne vous montre pas sa main ou s'il ne peut pas Enchaîner, placez 2 jetons de 2 puissance 🔘 en Soutien. »"},{"type":"p","text":"250 — Qu Lom, Martyr Hasardeux — Manifestation · 25 pts · 🌈🌈"},{"type":"p","text":"Ancien texte : « À chaque fois que Qu Lom est utilisé comme Tribut, lancez un D6 : si le résultat est pair, renvoyez Qu Lom dans votre main depuis vos Limbes. »"},{"type":"p","text":"Nouveau texte : « Quand Qu Lom est utilisé comme Tribut, à la fin de ce tour lancez un D6. Si le résultat est pair, Qu Lom retourne dans la main de son propriétaire depuis les Limbes. Si le résultat est impair, il est exilé à la place. »"},{"type":"p","text":"264 — Gummo — Manifestation · 40 pts · 🔘🔘🔘"},{"type":"p","text":"Ancien texte : « Tant que Gummo est dans l'Interzone : · Une fois par tour, pendant la Phase Finale, vous pouvez choisir une Manifestation au hasard dans votre Réceptacle Empathique : Gummo copie sa Puissance de base et gagne ses effets en plus des siens jusqu'à ce que cet effet soit réactivé. · Avant la Révélation, vous pouvez payer 🔘🔘🔘 : Gummo entre dans la confrontation comme Première Manifestation. »"},{"type":"p","text":"Nouveau texte : « Tant que Gummo est dans l'Interzone, à la fin du tour vous pouvez choisir une Manifestation dans votre Réceptacle Empathique. Si vous le faites, Gummo copie sa Puissance de base et gagne ses effets en plus des siens jusqu'à ce que cet effet soit réutilisé. Avant la Révélation, vous pouvez payer 🔘🔘🔘 : Gummo entre dans la Zone de Confrontation comme Première Manifestation depuis l'Interzone. »"},{"type":"p","text":"284 — Martyriser — Volonté Éphémère · 🔘"},{"type":"p","text":"Ancien texte : « Montrez et défaussez une Manifestation de votre main, piochez un nombre de cartes égal à sa Puissance de base. »"},{"type":"p","text":"Nouveau texte : « Comme coût supplémentaire pour jouer cette Volonté, révélez et exilez une Manifestation de votre main. Piochez un nombre de cartes égal à la Puissance de base de la Manifestation révélée, puis exilez cette Volonté. »"},{"type":"p","text":"257 — Cristacœur Rocheux — Manifestation · 10 → 15 pts · 🔘🔘"},{"type":"p","text":"Ancien texte : « Quand le Cristacœur Rocheux est utilisé comme Tribut, il est considéré comme étant de Tempérament 🌈. »"},{"type":"p","text":"Nouveau texte : texte inchangé ; seuls les Points passent de 10 à 15."}]},"en":{"contents":[],"introduction":[{"type":"h2","text":"Introduction"},{"type":"callout","variant":"intro","text":"Kartomantik is a game born from the ashes of a desperate world."},{"type":"p","text":"It is an invitation to pause, to look another in the eye, and to lay on the table what you hold most precious: your soul."},{"type":"p","text":"This is a strategic card game for two Cartomancers where you shape your deck to mirror your being. Every card within it is a fragment of your inner self, and the choices you make in building it define who you are."},{"type":"p","text":"The objective is not to annihilate your opponent, but to prevail in Confrontations: intense exchanges where your souls are measured against one another."},{"type":"p","text":"Each Confrontation begins when you both simultaneously reveal a First Manifestation: an impulse, a fear, a passion that takes form to represent you. From there, other Manifestations can enter the Cartomantic Field in support, but to truly shape this dialogue, you must exercise your Wills: acts of pure intention that, through the tribute of a fragment of your own soul, alter the course of the Confrontation.When you win a Confrontation, you assimilate the opposing soul's Manifestations into your Empathic Vessel, accumulating their point value—a representation of that fragment's weight in its owner's soul."},{"type":"callout","text":"The winner is the one who, at the end of the game, has accumulated the most points in their Empathic Vessel, proving they have more deeply assimilated and understood the inner self of the person before them.","variant":"winner"}],"basics":[{"type":"h2","text":"The Basics"},{"type":"h2","text":"The Temperaments"},{"type":"p","text":"Every card that makes up a Cartomancer's soul belongs to a Temperament. These Temperaments, and their distribution within a deck, define the power and personality of that soul. The Temperaments are the fundamental currents of being, each with its own identity and a different way of approaching the Confrontation:"},{"type":"p","text":"Base Temperaments"},{"type":"p","text":"Phlegmatic (Green): Patient, collaborative, encompassing. The Phlegmatic does not impose; it expands. In a Confrontation, it puts every fragment of itself on the table, cultivating a presence of many small Manifestations that becomes unstoppable. Its victory is one of empathic saturation: it envelops the opponent so deeply in its own interiority that it leaves them no room to define their own."},{"type":"p","text":"Choleric (Red): Passionate, wrathful, overwhelming. The Choleric is a soul that burns with a single, intense flame. It does not dialogue: it declares. In a Confrontation, it manifests emotional peaks of immense power and unleashes Wills that annihilate every obstacle, imposing its own truth with a force that brooks no reply."},{"type":"p","text":"Vitreous (Blue): Cold, logical, manipulative. Where others see chaos, the Vitreous sees a pattern. It controls the flow of the Confrontation by drawing answers, invalidating opposing impulses by returning them to the deck, and duplicating the most effective responses. It prevails not by exposing its own soul, but by proving it has understood the other's better than it understands itself."},{"type":"p","text":"Capricious (Yellow): Cunning, unpredictable, envious. The Capricious dances on the edge of uncertainty, using its apparent vulnerability as bait. Instead of confronting honestly, it sabotages the dialogue: it neutralizes the strongest impulses, steals what is not its own, and thwarts the opponent's plans with frustrating timing, winning at the moment the other no longer knows how to express themself."},{"type":"p","text":"Melancholic (Purple): Nostalgic, tormented, consuming. The Melancholic soul fights its own emptiness by projecting it onto the other. It forces them to lose fragments of themself by making them discard cards, weakens their impulses, and recalls the past from the Limbo. Assimilating the opponent's Manifestations into its Empathic Vessel is the only way it knows to feel, if only for a moment, a little more whole."},{"type":"p","text":"Meta-Temperaments"},{"type":"p","text":"Transcendent (White): Unifying, adaptable, enlightened. If the goal of the game is understanding, the Transcendent is the one who pursues it with sincerity. It embraces all Temperaments, acting as a bridge between them to find a common language. Its cards bend the rules not to cheat, but to create new paths of connection, adapting to every soul to achieve greater awareness."},{"type":"p","text":"Hollow (Black): Apathetic, selfish, emulative. If the Transcendent is the ascent, the Hollow is the collapse towards victory at any cost. It rejects the spirit of the game to exploit only its mechanics. Its cards are distorted echoes of the other Temperaments, shortcuts that offer immediate power in exchange for fragments of itself. Its victory brings no understanding, only the silence of an objective achieved."},{"type":"p","text":"This set is composed of a total of 300 unique cards:All cards of the Base Temperaments and Meta-Temperaments are contained within their own pack. Each Base Temperament pack includes 50 cards: 35 Manifestations, 12 Wills of the corresponding Temperament, and 3 Hollow Wills. The Base Temperament packs also contain all the cards necessary for the starter decks (4.1.1)."},{"type":"p","text":"The Meta-Temperament pack includes 50 cards: 10 Hollow Manifestations, 10 Transcendent Manifestations, 10 Multi-Temperament Wills, and 20 Hollow Wills. Each player can use their own set of cards to build their decks; it is not necessary to share a single set among all participants."},{"type":"h2","text":"The Cards"},{"type":"p","text":"A Kartomantik deck is composed of two types of cards: Manifestations and Wills."},{"type":"h3","text":"Manifestations"},{"type":"p","text":"“The very fragments of a Cartomancer's psyche. Each one lays bare impulses, manias, passions, and fears, taking form to represent you in Confrontations.”"},{"type":"label-list","text":"Card Name"},{"type":"label-list","text":"Manifestation Type"},{"type":"label-list","text":"Effects: The text describing the card's special abilities. Some Manifestations may have the keyword “Support” (3.1). Normally, only one manifestation can be played in the Confrontation, the First Manifestation; only manifestations with Support can be played and enter the Confrontation after it."},{"type":"label-list","text":"Temperament and Power: The symbols at the base of the card. Their shape and color define its temperament, and their number defines its base power. Essential for winning Confrontations and playing your Wills."},{"type":"label-list","text":"Points: The value of the Manifestation when it is placed in an Empathic Vessel (1.3). Also used in deck construction; each Cartomancer has a maximum limit of points their deck can contain."},{"type":"note","text":"NOTE: Each card, in the bottom left corner, also features the symbol of the set to which it belongs and a number to identify and order it among the cards of that set."},{"type":"h3","text":"Wills"},{"type":"p","text":"“Pure intent, acts of determination that a Cartomancer projects onto the Cartomantic Field to alter its balance.”"},{"type":"label-list","text":"Card Name"},{"type":"label-list","text":"Will Type:"},{"type":"label-list","text":"Ephemeral: A card with an instantaneous effect. It is played, its effect resolves, and then it is placed in the Limbo (1.3)."},{"type":"label-list","text":"Persistent: Unlike Ephemeral ones, it remains in play on the Cartomantic Field (1.3), applying its effect continuously or according to specified conditions. These cards cannot be played in response while other cards are on the stack (2.3) and are only played during the End Phase."},{"type":"label-list","text":"Tribute Cost: Most Wills require a tribute to be played. The symbols present and their number indicate the Temperament and amount of power to be paid as a tribute. How to pay Tributes will be explained later (2.1).NOTE: Some Wills may require a tribute of multiple temperaments; in that case, both must be paid. The card is considered to be of both temperaments."},{"type":"label-list","text":"Effects: Text describing the Will's effects."}],"zones":[{"type":"h2","text":"Game Zones"},{"type":"p","text":"1) Hand: The cards the player has available to be played. Hidden from opponents."},{"type":"p","text":"2) Deck: The remaining cards of your deck, face-down."},{"type":"p","text":"3) Limbo: The zone where played and resolved Ephemeral Wills, Manifestations used as Tributes, and destroyed cards are placed. Cards are face-up."},{"type":"p","text":"4) Confrontation Zone: A shared zone where all manifestations played as a First Manifestation or in Support during a Confrontation are placed."},{"type":"p","text":"5) Interzone: Zone where a player can place up to 3 of their Manifestations that have won a Confrontation to continue utilizing their effects. Cards are face-up. These Manifestations can be replaced by putting them at the bottom of the owner's Deck whenever another one would enter."},{"type":"p","text":"6) Cartomantic Field: Game zone, often shortened to \"field,\" which comprises the Interzone and the Confrontation Zone, and includes played Persistent Wills, which can be placed at the player's discretion."},{"type":"p","text":"7) Stalemate Zone: A special zone where Manifestations involved in a Confrontation that ended in a tie (Stalemate) are placed, or moved here by cards or effects. Manifestations remain here until a Confrontation concludes with a winner."},{"type":"p","text":"8) Empathic Vessel: The zone where the opponent's Manifestations that have lost a Confrontation are accumulated. The points on these cards are counted at the end of the game to determine the winner. Cards are face-up."},{"type":"p","text":"9) Exile: The zone where all exiled cards are placed, with which it is no longer possible to interact for the rest of the match. Cards are face-down."},{"type":"note","text":"NOTE: You are allowed to look at any face-up card or zone with face-up cards, and to count the number of cards and points in any zone."},{"type":"p","text":"10) The Stack: A temporary zone where all cards played and effects triggered or activated are placed before they resolve or enter the field, governed by the Stack System (2.3)."},{"type":"h3","text":"Game Zones"},{"type":"p","text":"The team shares a single Interzone extended to 4 total spaces. And they share the Field and Confrontation Zone.Limbo, Deck, Hand, and Empathic Vessel remain separate instead."},{"type":"note","text":"Note: Players cannot look at their teammate's hand."},{"type":"h3","text":"Card Control"},{"type":"p","text":"When a card's text refers to cards or effects under a player's control, consider also cards or effects controlled by their teammate."},{"type":"p","text":"The ownership and control of each card remain with the owner and cannot be shared."}],"turn-overview":[{"type":"h2","text":"Turn Overview"},{"type":"p","text":"Players compete in shared turns, which are divided into these phases:"},{"type":"phase","label":"Recovery Phase :","text":"Players draw cards from their deck until they have 7 cards in hand."},{"type":"phase","label":"Confrontation Phase :","text":"Players choose and simultaneously play a First Manifestation from their hand, revealing it in the Confrontation Zone. After the Revelation, players can play Ephemeral Wills and Manifestations with Support or activate effects of cards on the field (played Persistent Wills, Manifestations in the Confrontation Zone, or in the Interzone)."},{"type":"phase","label":"Resolution Phase :","text":"The Confrontation is resolved based on the Power and the Temperament of the Manifestations in the Confrontation. If a player wins the Confrontation, they place the opponent's Manifestations into their Empathic Vessel and decide whether to move their own Manifestations to the bottom of their deck or into their Interzone. In case of a tie, all manifestations in the Confrontation Zone are moved to the Stalemate Zone."},{"type":"phase","label":"End Phase :","text":"Players can play Persistent Wills."},{"type":"callout","text":"The game ends when a player has no more cards to draw during the Recovery Phase, or can no longer play a First Manifestation. The player who has accumulated the most points in their Empathic Vessel wins. The various turn phases and permitted actions will be explored in more detail in the \"Turn Structure and Phases\" section (4.2).","variant":"end-condition"}],"tribute":[{"type":"h2","text":"Playing your Cards"},{"type":"h2","text":"How to Pay a Tribute"},{"type":"p","text":"“Every intentional act demands a sacrifice. To channel its power, desire is not enough: you must offer a fragment of your own soul of equal intensity in return. This is a Tribute.“"},{"type":"p","text":"While playing the First Manifestation or put manifestations in Support normally has no cost, many actions (playing Wills, activating effects) require a Tribute to be performed. To pay a Tribute:"},{"type":"p","text":"Declare the Will or effect for which you are paying the Tribute and any of its targets (3.2 - Targets)."},{"type":"p","text":"Choose one or more Manifestations from your hand of the Tribute's Temperament to reach a total power equal to or greater than the required Tribute value. Show your selection to the opponent."},{"type":"p","text":"Satisfy any additional requirements requested by the action and move the manifestations chosen for the Tribute to the Limbo."},{"type":"note","text":"NOTE: If the chosen Manifestations already cover or exceed the cost required by an action, additional Manifestations cannot be used for the Tribute unless specified by the action. Manifestations can be used as a Tribute only if an action specifically requires it."},{"type":"p","text":"Excess Essence:"},{"type":"p","text":"If the base power of the manifestations used as a Tribute is higher than that required, the excess is considered \"Excess Essence.\" This excess can be used to pay for, or contribute to paying for, other Tributes of the same Temperament, acting as a temporary reserve. If you have Excess Essence, it must always be used for the payment of any Tribute that corresponds to its Temperament. Any Excess Essence not used by the end of the turn in which it was generated is lost."},{"type":"note","text":"NOTE: Excess Essence does not carry with it the effects of the manifestation from which it originated, unless specified on the manifestation."},{"type":"p","text":"Special Tributes and Essences:"},{"type":"p","text":"Hollow Tributes (🔘): Many Wills and effects may require a tribute of Hollow temperament 🔘. This can be paid using a Manifestation of any Temperament."},{"type":"p","text":"Hollow (🔘) and Transcendent (🌈) Essences: A Hollow manifestation can only pay for Hollow tributes. Conversely, a manifestation or excess essence of Transcendent Temperament can be used to pay a Tribute of any Temperament by declaring, for each essence used, which base temperament it represents."},{"type":"h3","text":"Example of a Tribute"},{"type":"p","text":"A player wants to play an Ephemeral Will, \"Incinerate,\" with a cost of 4🔥 (Choleric) Tributes."},{"type":"p","text":"In their hand, they have two manifestations: one with 2🔥 base power and another with 3🔥. Neither is sufficient on its own, so the player uses both, adding their base power together."},{"type":"p","text":"The player shows these manifestations to the opponent and declares they are using them as a tribute for the \"Incinerate\" Will."},{"type":"p","text":"The Will is played, and the manifestations used as Tribute are placed in the Limbo."},{"type":"p","text":"Having paid for a Will with a cost of 4 with a total power of 5, the player gains 1 🔥 Excess Essence, which they can use until the end of that turn."}],"priority-stack":[{"type":"h2","text":"Priority"},{"type":"p","text":"Now that you know how to pay tributes and play Wills, you must understand when you have the right to perform these actions. Since Kartomantik is a shared-turn game, it relies on Priority to decide which player is allowed to act."},{"type":"p","text":"Who has Priority:"},{"type":"p","text":"During the Confrontation Phase, the player who would lose the Confrontation if it were resolved at that moment (4.2.2 - Resolution) has Priority."},{"type":"p","text":"In every other game phase, the player who won the last resolved Confrontation has Priority."},{"type":"p","text":"Having Priority means having the right to perform an action, such as playing a card or activating an effect. The player with Priority can choose to perform an action or to \"pass,\" giving up Priority to the opponent."},{"type":"note","text":"NOTE: In the special case where there is no way to determine which player has Priority, each player rolls a die. Whoever rolls higher has Priority."},{"type":"h2","text":"The Stack System"},{"type":"p","text":"When, having Priority, you play a card or a card's effect is triggered or activated, these actions do not resolve immediately, they are placed on the Stack, a shared zone where they accumulate while waiting to resolve according to the following steps:"},{"type":"p","text":"A player puts an action onto the Stack (plays a card, activates its effect, or an effect they control is triggered)."},{"type":"p","text":"Priority passes to the opponent, who can respond by putting an action on top of the Stack, or pass. As long as there are actions on the Stack, players exchange Priority automatically each time they add an action to the top of the Stack or pass."},{"type":"p","text":"When both players pass consecutively without adding actions to the Stack, it begins to resolve. Actions on the Stack resolve one at a time in reverse order, starting from the last one added to the Stack (the one on top)."},{"type":"p","text":"Each time an action on top of the Stack is resolved and another action is still present on the Stack, every player can interrupt the resolution of the Stack, returning to point 2. Specifically, Priority passes to the player who does not control the action currently on top of the Stack, who can again decide to respond or pass, and so on."},{"type":"p","text":"The process continues until all actions on the Stack have been resolved. After the Stack has emptied, players return to applying the normal rules of Priority and can start a new Stack if they still have actions to perform."},{"type":"note","text":"NOTE: Persistent Wills cannot be used in response; they can only be placed on the Stack if there are no other cards already on it."},{"type":"note","text":"NOTE: When a player performs an action that uses the Stack, what is placed on the Stack can be:"},{"type":"p","text":"A Card: When you play a card from your hand or from zones other than the field (an Ephemeral Will, a Persistent Will, or a Manifestation with Support), it is the card itself that is placed on the Stack. It waits there for its resolution. If the action resolves, the card produces its effect and then moves to the appropriate zone (Limbo for Ephemeral Wills, Cartomantic Field for Persistent Wills, and the Confrontation Zone for support manifestations)."},{"type":"p","text":"An Effect: When you activate an effect of a card that is already on the field (e.g., a Manifestation in the Interzone or a Persistent Will), it is only the effect that is placed on the Stack. The card that generated it remains where it is."},{"type":"h3","text":"Examples of the Stack System"},{"type":"p","text":"Case 1:"},{"type":"p","text":"Let's imagine a situation during a Confrontation. Player A has Priority and wants to weaken Player B's \"Gar Fild, the Malleable\" (3 power) to win the Confrontation."},{"type":"p","text":"Player A plays an Ephemeral Will, \"Oppress,\" targeting \"Gar Fild.\" The effect of Oppress is: \"A target manifestation on the field gets -3 power until the end of the turn.\" The card is placed on the Stack."},{"type":"p","text":"Priority passes to Player B, who responds by playing \"Entrust\" on their \"Gar Fild.\" The effect of Entrust is: \"Double the base power of a target manifestation on the field.\" The card is placed on the Stack, on top of \"Oppress.\""},{"type":"p","text":"Both players choose not to take any more actions, passing Priority. Since they have passed consecutively, the Stack begins to resolve from top to bottom."},{"type":"p","text":"First, the last action added resolves: \"Entrust.\" The base power of \"Gar Fild\" is doubled, bringing its total power to 6. The Will goes to the Limbo."},{"type":"p","text":"Next, \"Oppress\" resolves. Its effect is applied to \"Gar Fild,\" which now has 6 Power. Its power is reduced by 3, bringing it to 3. This is not enough to destroy it. \"Oppress\" also goes to the Limbo."},{"type":"p","text":"The Stack is now empty. \"Gar Fild, the Malleable\" has survived the interaction, and the Confrontation continues."},{"type":"p","text":"Case 2:"},{"type":"p","text":"Now, let's see what happens if Player B were at a disadvantage and acted first:"},{"type":"p","text":"Player B, having Priority because they are at a disadvantage, plays \"Entrust\" on \"Gar Fild.\" The card is placed on the Stack."},{"type":"p","text":"Priority passes to Player A, who plays \"Oppress\" on the same \"Gar Fild\" in response. \"Oppress\" is placed on the Stack, on top of \"Entrust.\""},{"type":"p","text":"Both players pass, and the Stack begins to resolve."},{"type":"p","text":"This time, \"Oppress\" resolves first. It applies its effect to \"Gar Fild,\" which still has 3 Power. Its power drops to 0 (3-3=0), and it is destroyed."},{"type":"p","text":"Next, \"Entrust\" attempts to resolve. When it tries to resolve, its target, \"Gar Fild,\" is no longer on the field. The effect cannot be applied, and the card goes to the Limbo without having done anything."},{"type":"h3","text":"Priority"},{"type":"p","text":"During a confrontation in Free-for-All, priority is passed based on Disadvantage, which is the number of players by whom one would be beaten individually by Power or Temperament:"},{"type":"p","text":"The player with priority is the player at an absolute disadvantage, meaning the one who would be beaten by every single other player."},{"type":"p","text":"If the player with priority passes on an empty stack, priority goes to the player with the next greatest disadvantage after them."},{"type":"p","text":"If there are multiple players with the same disadvantage, priority instead passes to the closest player, in clockwise order, to the player who is passing priority."},{"type":"p","text":"If a player at a disadvantage passes, they cannot obtain priority again until another player performs an action, returning priority to the player with the greatest disadvantage."},{"type":"p","text":"When, on an empty Stack, all players have passed consecutively, the turn moves to the next phase."},{"type":"p","text":"Outside of the confrontation or in case of a stalemate, the player who won the last resolved confrontation has priority, and priority is passed clockwise."},{"type":"p","text":"In case it cannot be decided who has priority, rely on the base rules for priority."},{"type":"h3","text":"The Stack"},{"type":"p","text":"When a player with Priority performs an action, it is placed on top of the Stack. Priority passes immediately to the next player clockwise."},{"type":"p","text":"Players continue to pass Priority clockwise, adding actions to the Stack or passing."},{"type":"p","text":"The Stack begins to resolve only when all players have passed consecutively."},{"type":"h3","text":"Resolution and Stalemate"},{"type":"p","text":"A player wins a Confrontation only if their total Power and Temperament (if necessary) would allow them to individually defeat every other player present in the Confrontation.Resolution proceeds normally, putting all opposing manifestations from the confrontation and stalemate into one's own empathic vessel. (It is recommended to have separate piles for each player)"},{"type":"p","text":"The Confrontation instead ends in a Stalemate in any case where there is no single winner. For example:"},{"type":"p","text":"If the last manifestations to enter the Confrontation of the two players with the highest total power have the same Temperament."},{"type":"p","text":"If a chain of dominance is created between the Temperaments (e.g., Player A beats B, B beats C, and C beats A)."},{"type":"h3","text":"End Phase"},{"type":"p","text":"Each time that, during the End Phase, a Stack initiated by a player resolves completely, priority passes to the closest player in clockwise order."},{"type":"h3","text":"Priority"},{"type":"p","text":"Outside of the Stack, Priority is assigned to the team, as if they were single players, following the base rules (e.g., the team that would lose the Confrontation at that moment has Priority, or the team that won the last Confrontation).When a team obtains Priority, the two players decide together which of the two will use it to perform an action (play a Will, activate an effect, etc.). If they choose to pass, Priority passes to the opposing team."},{"type":"h3","text":"The Stack"},{"type":"p","text":"To ensure that everyone can react, the Stack uses the Free-for-All logic:"},{"type":"p","text":"When a player with Priority performs an action, it is placed on top of the Stack. Priority passes immediately to the next player clockwise."},{"type":"p","text":"Players continue to pass Priority clockwise, adding actions to the Stack or passing."},{"type":"p","text":"The Stack begins to resolve only when all four players pass consecutively."},{"type":"h3","text":"Revelation"},{"type":"p","text":"Each team can have a single First Manifestation on the field.At revelation, the players of each team decide which of the two must choose the First Manifestation.When both teams have chosen, the players uncover the chosen First Manifestation and place it on their side of the Confrontation Zone. Revelation and reaction proceed as per the base rules."},{"type":"h3","text":"Resolution"},{"type":"p","text":"To determine the result of a Confrontation, sum the total Power of all Manifestations controlled by both players of Team A, against the total Power of all the Manifestations of Team B, as if they were single players, following the base rules."},{"type":"p","text":"When a team wins the Confrontation:"},{"type":"p","text":"The two players of the winning team decide between themselves in which of the two Empathic Vessels to put the opposing team's manifestations."},{"type":"p","text":"They decide which manifestations to put in the interzone, or at the bottom of the respective owners' decks."}],"effects":[{"type":"h2","text":"Understanding the Cards"},{"type":"p","text":"To master Kartomantik, it is crucial to understand how to interpret and apply card effects. The following section serves as a comprehensive guide to these interactions. For a new player, an initial read-through to familiarize yourself with the general concepts is recommended, without the need to memorize every specific rule."},{"type":"p","text":"Use this chapter as a rules glossary to resolve specific doubts as they arise."},{"type":"h2","text":"Types of Effects"},{"type":"h3","text":"Activated"},{"type":"p","text":"Activated:"},{"type":"p","text":"Effects that you can choose to use by paying a Tribute or meeting a condition. You can recognize them by phrases like \"Pay [cost]:\". Activated effects use the Stack and can only be used after the Revelation of the First Manifestation.NOTE: When a card requires being Exhausted to activate its effect, turn the card 90°, that effect cannot be used again until the card is Restored during the next Recovery Phase (4.2.1)."},{"type":"h3","text":"Passive"},{"type":"p","text":"Passive:"},{"type":"p","text":"Effects that are always active as long as the card remains on the field (or in the zone they specify). They do not have, nor do they require, conditions to be used. You can recognize them by phrases like \"As long as...\". They do not use the Stack.NOTE: Passive effects that affect other cards (e.g., \"Manifestations you control get +1 power as long as they are in the Confrontation Zone\") apply exclusively as long as both the card generating the effect and the cards affected by it remain in the specified zone; they immediately cease to be applied when the cards enter a zone not covered by the card's text."},{"type":"h3","text":"Triggered"},{"type":"p","text":"Triggered:"},{"type":"p","text":"Effects that activate automatically when a specific condition is met. You can recognize them by words like \"When...\", \"Whenever...\", \"If...\". They are placed on the Stack as soon as their condition is met, even during the resolution of the Stack, after the action that triggered them has resolved (players can respond). When multiple cards have a trigger at the same time (e.g., “At Revelation”), those effects are simultaneous. If simultaneous effects are controlled by different players, they are placed on the Stack according to the rules of Priority: the player with Priority puts their effects on the Stack first, then the opponent puts their effects on the Stack."},{"type":"p","text":"If multiple simultaneous effects belong to the same player, that player chooses their order on the Stack. In the case of simultaneous effects, all must enter the Stack before it is possible to respond."},{"type":"note","text":"NOTE: If a Manifestation has a triggered effect that occurs when it's used as tribute or to pay an alternative cost (e.g., discarding a card), the paid action and that Manifestation's effect are simultaneous."},{"type":"p","text":"Support and Chain:"},{"type":"p","text":"Support is a special activated effect, normally without costs, that allows manifestations to be played and enter the Confrontation Zone after the First Manifestation, from the hand or the Interzone. If \"from hand\" is specified, that card can only be played in Support from your hand."},{"type":"p","text":"Chain is an effect that allows you to put any manifestation into Support from the zone specified on the card. A Chained manifestation is considered \"played.\""},{"type":"h3","text":"Support and Chain"},{"type":"h2","text":"Reading the Effects: Key Rules"},{"type":"p","text":"The Golden Rule:If the text of a card has an effect that contradicts the game rules, the text of that card takes precedence over the game rules. If effects contradict each other: Absolute restrictions (effects using words like \"cannot\" or \"can only\") always take precedence over effects that allow or try to force an action. For example, if one effect says \"You cannot draw cards\" and another says \"Draw 3 cards,\" the effect that prevents the action always prevails."},{"type":"p","text":"Owner and Controller:Each player is always the Owner of the cards they started the game with in their deck and, unless an effect changes it, they are also the Controller, meaning the player who can play them and activate their effects. If a card of which you are the Controller generates an effect, you are also the Controller of that effect. When the text of a card addresses the player directly, for example with \"you\" or \"your,\" it always refers to the current Controller of the card."},{"type":"p","text":"Game Zones:If an effect indicates a zone (e.g., \"put in the Interzone\") without specifying the owner, it always means the one belonging to the card's controller. Each player is the Owner of all their non-shared game zones: Interzone, Limbo, Deck, Hand, Empathic Vessel, and Exile. The Limbo, the Deck, the Hand, and Exile can contain only cards of which you are the Owner. The Empathic Vessel, conversely, can only contain cards (manifestations) of which you are NOT the Owner. NOTE: Manifestations in Empathic Vessels are always under the control of their Owner.When cards enter a shared game zone, such as the Confrontation Zone, the Stack, or the Stalemate Zone, these cards enter under the control of their Owner, unless the cards specify otherwise."},{"type":"p","text":"Targets:Many cards, to resolve, need one or more targets, the object upon which they have an effect. Every time the word \"target\" is used in the text of a card in relation to something (a player, a manifestation, etc.), the controller of that card must declare a valid target before putting that action on the Stack. For example, if an effect says \"A target manifestation on the field gets-1 power,\" that effect requires a target. Its controller must therefore declare a Manifestation on the field as a target before putting the effect on the Stack. The target must be valid both when the effect is put on the Stack and when it resolves. If the target is no longer valid when the effect resolves (if, for example, the manifestation has been removed from the field), the effect does not take place."},{"type":"p","text":"Action Validity:You cannot play a card or activate an effect if you cannot fulfill all of its requirements. This includes paying Tributes, additional costs (e.g., discarding cards), and choosing a sufficient number of valid targets."},{"type":"p","text":"Modifiers and Counters:Anything that alters the base characteristics of a card or a zone, whether in permanent or temporary form, is called a Modifier. If a manifestation's power increases or decreases, or if a card loses its effects or gains others beyond those it would normally have, these are Modifiers. Modifiers are, unless otherwise indicated, permanent, but only as long as the card remains on the Cartomantic Field or in the Stalemate Zone. This means that, for example, a manifestation with Modifiers can move between the field (Interzone, Confrontation Zone) and the Stalemate Zone without losing its modifiers; however, if it leaves one of these zones to enter a Limbo, an Empathic Vessel, a deck, the hand, or Exile, the manifestation loses all its Modifiers.Counters are instead a resource that must be placed on a card; each Counter has a specific name and is useless on its own, but can be used to satisfy the requirements of cards that need them to activate certain effects. Counters follow the same rules as Modifiers."},{"type":"p","text":"Power vs Base Power:Base Power is a generally stable value, indicated by the number of symbols present on a manifestation. In addition to indicating its starting power, it also indicates the value of that manifestation when used as a Tribute. Power is a variable value determined by the sum of the Base Power and all the modifiers affecting it in a temporary or permanent way. Furthermore, Power is the value calculated to determine the result of a confrontation. NOTE: When a manifestation reaches 0 or less Power, that manifestation is destroyed."},{"type":"p","text":"Independence of Effects:An activated or triggered effect, once put on the Stack, exists independently of its source. If the card that generated the effect is removed from the game while the effect is still on the Stack, the effect will still resolve. An effect that triggers when a card undergoes a certain event (such as being destroyed) triggers at the instant that event occurs. That effect will go onto the Stack even if the card that generated it is leaving the game."},{"type":"p","text":"“Memory” of Effects:Sometimes, a card's effect doesn't just resolve, but it creates a new rule or a delayed effect that \"attaches\" to another card. This new rule remains valid even if the original source of the effect leaves the field, as if the target card retains a memory of it. For example, if you play a Will that says: \"Chain from your hand. If the Chained manifestation wins the confrontation, exile it.\" Even if the original Will is now in the Limbo, the rule to exile is \"remembered\" by the manifestation. At the end of the Confrontation, that manifestation will be exiled.NOTE: This Memory is lost by the card only if the latter enters a deck or if it is exiled."},{"type":"p","text":"Play and Move:Cards have multiple ways to enter the field; the most common consists of playing them. A card is normally \"played\" when it is Revealed as a First Manifestation, enters the Stack from the hand or deck, or is played from other zones due to an effect. Cards, however, can also enter the field by being moved, which always occur via other cards or effects. If a card, for example, speaks of \"putting\" something in an area, that's a movement, and the same applies to manifestations that enter in Support. These are considered movements; the cards enter the zones specified by these effects without first passing through the Stack, and therefore are not considered \"played\" unless the effect explicitly states it (as, for example, with the \"Chain\" effect)."},{"type":"p","text":"To interpret all the effects of your cards and their keywords, go to the \"Keywords\" section (7)."}],"deckbuilding":[{"type":"h2","text":"Playing a Game"},{"type":"p","text":"Now that you have understood the basic mechanics, it's time to sit down and try the game. Let's go into detail to see how a game of Kartomantik unfolds between two players."},{"type":"h2","text":"Building a Deck"},{"type":"p","text":"To start playing, each player must have their own deck."},{"type":"p","text":"Each deck must be built according to these rules:"},{"type":"deck-rule","text":"There must be exactly 30 cards."},{"type":"deck-rule","text":"The sum of the Points of all Manifestations in the deck must not exceed 500. Will cards do not have a point cost for deck construction."},{"type":"deck-rule","text":"There can be no more than one copy of the same card (same name) in the deck."},{"type":"p","text":"It is recommended to have between 8 and 12 Wills in a deck, and to ensure that their tributes can all be paid. For multi-temperament decks, it is preferable to add Hollow Wills or manifestations, Transcendent or not, that can pay for multiple temperaments."},{"type":"p","text":"If players want to play best-of-3 (Bo3), they can create, in addition to a normal deck, a Sideboard of 6 cards with no point limits. Before the start of each match, each player can modify their deck by replacing cards in it with any card chosen from their Sideboard, respecting the normal construction limits."},{"type":"h3","text":"Starter Decks"},{"type":"p","text":"To try the game for the first time, it is recommended to build the starter decks:"},{"type":"h4","text":"Choleric"},{"type":"p","text":"Atavic Fury (235); Candle Serpent (189); Ancient Bicep (190); Tigrolione (191); Twin-Headed Druid (193); Fiery Furybeast (195); Perfidious Baranchio (196); Wandering Veteran (197); Skapus, the Vile (198); Titan of the Blazing Womb (199); Glabron, the Oppressing (200); Fintus, the Spectacular (202); Thornmaster (203); Pimbo (204); Gorb, the Musclebound (206); Borombo, the Mad (210); Bell, Ardent Fanatic (214); Solar Apparition (216); Bolbakazim, the Cursed (217); Friendly Presence (218); Migmomirf (219); Incinerate (225); Corrode (226); Damage (227); Oppress (228); Rematch! (232); Wretched Arena (234); Weaken (272); Duel Honorably (279); Volcano (300)."},{"type":"h4","text":"Capricious"},{"type":"p","text":"Atavic Volatility (188); Auriwings (142); Absent Trinket (143); Roly-Polymancer (144); Yzzit, the Gambler (146); Pok, the Teaser (148); Incoherent Pard (149); Unpredictable Loudmouth (150); Static Scuttler (151); Loop, the Insistent (152); Cimba, the Boisterous (153); Mimer (154); Rogue Tadpole (155); Juggling Amphora (156); Knobbly Colossus (159); Ranba, Silent Abductor (161); Unruly Flail (163); Bloatuba (164); Planar Beak (165); Obtrusive Mass (166); The Stomper (167); Starkaz, the Brilliant (169); Trim the Excess (177); Neutralize (179); Annihilating Nectar (180); Salvage the Fragments (181); Pin Down (183); Ignore (285); Empathic Mask (289); Trap (291)."},{"type":"h4","text":"Melancholic"},{"type":"p","text":"Atavic Oppression (141); Little Abhorrence (95); Timid Brain (96); Repudiated Orphan (97); Mourning Offal (98); Yurfuq, Sad Lily (101); Tenebro, Night Assailant (102); Forgotten Pile (103); Dark Apparition (104); Underground Snail (106); Solenero, the Contrite (108); Zombieswing (110); Diabolical Giant (111); Mind Parasite (112); Lament, Thought-Nullifier (114); Forfog, the Hanged (115); Zrutrug, the Indebted (118); Repelling Urn (120); Carcass Devourer (121); Armored Pachywyrm (122); Urolong, Rueful Necromancer (125); Disfigure (130); Claim the Forsaken (131); Shattering the Self (135); Reforging Fate (136); Traumatize (139); Revive (140); Recover from the Abyss (270); Pray the Ether (281); karmapult (296)."},{"type":"h4","text":"Vitreous"},{"type":"p","text":"Atavic Introspection (94); Concealed Manta (48); Artificial Thinker (49); Isolated Wordsmith (50); Keen-Eyed Seeker (52); Hurlon, Thought-Implanter (54); Chitinous Repeller (55); Reliable Ammonite (57); Rigid Omen (59); Inspired Nimbus (63); Ohmom, the Azure (64); Coral Skull (65); Skysailing Triad (66); Shababba, Divining Cube (68); Hermeto, the Observer (70); Tipson, the Mediator (72); Expansive Ponderer (73); Dew Invoker (74); Shymon, the Mastermind (76); Blue Entity (80); Glimpse the Omens (83); Defer (84); Mirror the Impulse (85); Imitate (86); Consult (88); Dominate the Aspects (92); Banish (93); Ponder (267); Deny (276); Grimoire (297)."},{"type":"h4","text":"Phlegmatic"},{"type":"p","text":"Atavic Welcome (47); Wind Sprout (1); Sated Swineheart (2); Merciful Pago (3); Tiptup, the Whistler (4); World Spore (7); Graceful Petal (8); Amiable Blockhead (10); First Stone (11); Sprawling Tentacle (12); Flower Tender (13); Echo of the Wilds (16); Stoic Snoozer (17); Jondo, the Pure Heart (19); Pan Zuto, the Beckoner (20); Spontaneous Incubator (21); Lady of the Humps (23); Stampeding Brood (24); Advocate of Catharsis (27); Mobile Sanctuary (28); Forest Guide (31); Unite Impulses (36); Plea for Generosity (37); Entrust (40); Rally (44); Reap What You’ve Sown (45); Heartening Monument (46); Strengthen (266); Essence Forager (268); Accentuate (275)."},{"type":"starter-summary","text":"Each of these starter decks contains exactly 30 cards with a total of 400 points. Once you've learned how to play, you can upgrade them and experiment with new synergies, by exploring the other cards available in the set."}],"turn-structure":[{"type":"h2","text":"Turn Structure and Phases"},{"type":"p","text":"After the players have chosen and thoroughly shuffled their decks, the game begins with the first turn, starting directly with the first Recovery Phase."},{"type":"p","text":"It is recommended to have counters and small objects to use as tokens for your card effects."},{"type":"h3","text":"Recovery Phase"},{"type":"p","text":"If it is not the first turn, resolve any \"at the beginning of the turn\" effects and restore all your exhausted cards."},{"type":"p","text":"Each player draws cards from their deck until they reach the hand limit of 7 cards. If a player's hand has already reached the limit, that player does not draw."},{"type":"p","text":"Each player checks if they have at least one Manifestation card in hand that can be played as a First Manifestation, otherwise they must perform a Mulligan. All manifestations, unless specified otherwise, can be played as a First Manifestation."},{"type":"p","text":"After checking for the First Manifestation, resolve or play any effects that can occur \"before the Revelation.\""},{"type":"h4","text":"The Mulligan:"},{"type":"p","text":"If a player has no manifestations playable as a First Manifestation, they must declare it, show their hand to the opponent to confirm, shuffle all cards from their hand back into their Deck, and draw again up to the hand limit. This is a \"Mulligan.\" The Mulligan is allowed at the first turn, only once, even in case you have a valid Manifestation in your hand. In that case, lose 10 points."},{"type":"note","text":"NOTE: If after a second Mulligan a player does not have a playable First Manifestation, that player immediately losesthe game."},{"type":"h3","text":"Confrontation Phase"},{"type":"p","text":"The Confrontation is composed of two sub-phases: Revelation and Reaction."},{"type":"h4","text":"Revelation"},{"type":"p","text":"Both players must secretly choose a Manifestation card from their hand to play as their First Manifestation for the turn. The chosen card is set apart from the hand (e.g., kept face-down on the table or simply clearly identified) to show that the choice has been made."},{"type":"p","text":"Simultaneously, the players uncover their chosen First Manifestation andplace it on their side of the Confrontation Zone."},{"type":"p","text":"All Immediate effects on Revelation are triggered."},{"type":"p","text":"Then, \"when it enters the field\" or \"when it enters the Confrontation Zone\" effects of the First Manifestations and any manifestations played due to their effects are triggered."},{"type":"note","text":"NOTE: If, due to a card's effect, one First Manifestation is played after the other player's, those effects trigger only when both have been played."},{"type":"note","text":"NOTE: If you already have manifestations in the Confrontation Zone, you cannot reveal a First Manifestation. Instead, you must choose which of those manifestations will be counted as the First Manifestation and which as the last one played. If, due to one or more effects, there are multiple First Manifestations, choose one and place the others at the bottom of the deck in any order."},{"type":"h4","text":"Reaction"},{"type":"p","text":"All \"after the Revelation\" effects are triggered."},{"type":"p","text":"From now on, players can:"},{"type":"p","text":"Play Ephemeral Wills from their hand (paying any Tributes)."},{"type":"p","text":"Play Manifestations with Support from their hand or Interzone to add them to the Confrontation."},{"type":"p","text":"Use activated effects of Persistent Wills or Manifestations already on the field."},{"type":"note","text":"NOTE: If a manifestation that entered in Support due to cards or effects triggers an “enters the field” or “enters the Confrontation Zone” effect, these also trigger in this game phase."},{"type":"p","text":"All these actions follow the rules of Priority and the Stack. The Confrontation phase continues until the Stack is empty and both players decide to pass."},{"type":"h3","text":"Resolution Phase"},{"type":"p","text":"Once both players have passed during the Reaction part of the phase:"},{"type":"p","text":"Each player sums the current Power (base power plus any modifiers) of all their Manifestations in the Confrontation Zone. If a player has no manifestations in the Confrontation, their total power is considered 0. When one player has greater total power, that player wins the Confrontation."},{"type":"p","text":"When a Player Wins:"},{"type":"p","text":"Any on-win, on-loss, or \"at the Resolution\" effects are triggered. Players can play Wills from their hand and use activated effects until both players pass consecutively, before cards are moved to their respective zones. Those effects do not alter the outcome of the Confrontation."},{"type":"p","text":"The winning player places all Manifestations owned by the opponent present in the Confrontation Area and in the Stalemate Zone into their Empathic Vessel."},{"type":"p","text":"For each Manifestation they are the owner of present in the Confrontation Area or in the Stalemate Zone, they can decide, in any order, to:"},{"type":"p","text":"Place it at the bottom of their Deck, face-down."},{"type":"p","text":"Place it in a space in their Interzone. If that space was already occupied by another Manifestation, that manifestation is placed at the bottom of its owner's Deck, face-down."},{"type":"p","text":"In case of a tie in power:The natural dominance of the Temperaments is used. Compare the Temperament of the last manifestation that entered the Confrontation under each player's control. If one player has the dominant Temperament, they win the Confrontation.The hierarchy is as follows:"},{"type":"p","text":"🌿 Phlegmatic beats 💧 Vitreous and ⚡ Capricious.💧 Vitreous beats 🔮 Melancholic and 🔥 Choleric.🔮 Melancholic beats ⚡ Capricious and 🌿 Phlegmatic.⚡ Capricious beats 🔥 Choleric and 💧 Vitreous.🔥 Choleric beats 🌿 Phlegmatic and 🔮 Melancholic.🌈 Transcendent beats any other Temperament.🔘 Hollow is beaten by any other Temperament."},{"type":"p","text":"If the total power in the Confrontation and the Temperament of the last manifestations played are both equal, the Confrontation ends in a Stalemate."},{"type":"p","text":"You can use the card’s back as reference."},{"type":"h4","text":"Stalemate"},{"type":"p","text":"In the event of a tie, all Manifestations of both players currently in the Confrontation Zone leave the field and are moved to the Stalemate Zone. They remain there until a Confrontation is won, retaining all their permanent modifiers.NOTE: Since they did not participate in the Confrontation, Manifestations leaving the Stalemate do not trigger their on-win, on-loss effects, even if a Confrontation is resolved with a winner."},{"type":"h3","text":"End Phase"},{"type":"p","text":"When the Confrontation has been resolved and the Manifestations have been moved to their respective zones, players can play Ephemeral Wills and Persistent Wills from their hand, or use activated effects, with Priority going to the player who won the last resolved Confrontation.Each time during the End Phase a Stack initiated by a player resolves completely, priority passes to their opponent."},{"type":"p","text":"Once the Stack is empty and both players pass consecutively:"},{"type":"p","text":"Resolve any \"at the end of the turn\" effects."},{"type":"p","text":"All \"until the end of the turn\" effects wear off."},{"type":"p","text":"The turn ends. If a player ended the turn with more than seven cards in hand, they place the excess cards at the bottom of their deck in any order.A new turn begins from the recovery phase until one of the two End Game Conditions (4.4.1) is met."},{"type":"h3","text":"Example Turn"},{"type":"p","text":"Let's look at an example turn between Player A, with a Phlegmatic 🌿deck, and Player B, with a Choleric 🔥 Deck."},{"type":"p","text":"Recovery"},{"type":"p","text":"Revelation"},{"type":"p","text":"1. The turn begins. Both players draw cards until they have 7 in hand and confirm they have a card to play as a First Manifestation."},{"type":"p","text":"2. Players begin the Confrontation. They choose their First Manifestation from their hand and indicate their choice by placing it face-down on the table."},{"type":"p","text":"3. Player A (Phlegmatic) uncovers Lady of the Humps (Power 2🌿) with the effect: \"When Lady of the Humps enters the field, search your deck for a manifestation and Chain it, then shuffle the deck."},{"type":"p","text":"If the Chained manifestation wins the confrontation, exile it.\"Player B (Choleric) uncovers Gorb, the Musclebound (Power 6🔥) with the effect: \"When Gorb enters the field, you cannot put manifestations in Support under your control until the end of the turn.\""},{"type":"p","text":"4. The \"when it enters the field\" effects are triggered. Player A resolves the effect of Lady of the Humps and chains (puts into support) Amiable Blockhead (Power 4🌿) from the deck.Player A's total power is 6🌿 (2+4) versus Player B's total power of 6🔥. They are tied, but since Choleric has dominance over Phlegmatic¹, Player A is at a disadvantage and gains Priority."},{"type":"p","text":"5. Having resolved the effects of the First Manifestations, the Confrontation moves to the reaction sub-phase.Player A, having Priority, plays the Will Accentuate which gives \"+1 power until the end of the turn\" and targets their Amiable Blockhead. The card goes on the Stack."},{"type":"p","text":"6. Priority passes to Player B. They pay a tribute to play Oppress in response, which puts -3 power on a manifestation, also targeting Amiable Blockhead. The manifestation used as a tribute goes to the Limbo. Oppress goes on top of the Stack. Then both players pass."},{"type":"p","text":"7. The Stack resolves from top to bottom:"},{"type":"p","text":"Oppress resolves: the Power of Amiable Blockhead drops to 1(4-3=1). Oppress goes to the Limbo.Then Accentuate resolves: the Power of Amiable Blockhead rises to 2 (1+1=2). Accentuate goes to the Limbo.Player A's total power is now 4🌿 (Lady of the Humps 2 + Amiable Blockhead 2), against Gorb's 6🔥. Player A is still at a disadvantage and has Priority."},{"type":"p","text":"8. Player A plays Forest Guide (Power 3🌿) as support, reaching a total of 7🌿.Now that Player A is winning (7 to 6), Priority passes to Player B. However, due to Gorb's effect, they cannot play Manifestations as support and decide to pass. Player A also passes."},{"type":"p","text":"Resolution"},{"type":"p","text":"End Phase"},{"type":"p","text":"9. Since both players have passed, the Confrontation resolves: Player A wins the Confrontation with a total power of 7 against 6.Gorb, the Musclebound is placed in their Empathic Vessel.Player A then decides where to move their Manifestations:"},{"type":"p","text":"• Forest Guide is placed in the Interzone to continue using its Support effect in future turns."},{"type":"p","text":"• Lady of the Humps is placed at the bottom of the deck to be drawn again in the future."},{"type":"p","text":"• Amiable Blockhead is exiled, as specified by the effect of Lady of the Humps."},{"type":"p","text":"10. The End Phase begins.Player A, having won, has Priority, but has nothing to play and passes.Player B, now with Priority, decides to play the Persistent Will Volcano, which says \"Pay 🔘🔘🔘🔘: Exile all Wills on the field and all manifestations in every Interzone.\"They prepare it for a future turn, with the intention of exiling the opponent's Forest Guide."},{"type":"p","text":"11. Both players pass, and the turn concludes."},{"type":"h2","text":"Summary of Phases and Permitted Actions"},{"type":"note","text":"NOTE: When a card refers to Skipping a Phase, the player cannot take any actions during that phase, triggered effects on cards they control are not triggered, and passive effects referring to that phase are not considered."},{"type":"note","text":"NOTE: Manifestations can only enter the Confrontation Zone during a Confrontation."}],"end-game":[{"type":"h2","text":"End of the Game and Point Calculation"},{"type":"h3","text":"End Game Conditions"},{"type":"p","text":"The game ends IMMEDIATELY if one of the following conditions is met:"},{"type":"p","text":"A player, during the Recovery Phase, could not draw enough cards to reach the required hand limit."},{"type":"p","text":"A player, during the Recovery Phase, after their second consecutive Mulligan, still does not have a playable First Manifestation in hand. In this case, the player loses the match."},{"type":"h3","text":"Point Calculation"},{"type":"p","text":"Once the match has ended:"},{"type":"p","text":"Each player sums the values in Points of all Manifestation cards present in their Empathic Vessel at the end of the match and the Points gained or lost from card effects."},{"type":"p","text":"If a player still has Manifestation cards in their deck, they obtain 5 bonus Points for each Manifestation card remaining inside it."},{"type":"note","text":"NOTE: Cards that are still in the Stalemate Zone at the end of the match are not considered in the point calculation."},{"type":"h3","text":"Win Condition"},{"type":"victory","text":"The player with the highest total of Points wins the match. In case of a tie in Points, the match is a draw."},{"type":"h3","text":"End of the Game"},{"type":"p","text":"If a player cannot reach the required hand limit during recovery or loses the game, for example, due to two consecutive mulligans, the game DOES NOT end.That player can no longer take part in Confrontations, but retains the right to play Wills and activate effects."},{"type":"p","text":"The game continues as long as at least two players are still able to reach the hand limit during their Recovery."},{"type":"h3","text":"End of the Game"},{"type":"p","text":"If one or more players cannot reach the required hand limit during recovery, but their teammate can, the game does not end immediately, but the final turn is played. Those players can still participate and use all the cards at their disposal."},{"type":"p","text":"If a player loses the game, for example due to two consecutive mulligans, their team loses."},{"type":"h3","text":"Point Calculation and Victory"},{"type":"p","text":"At the end of the game, the team's score is calculated by summing the total Points present in the Empathic Vessels of both players, and counting the bonus points of both for the manifestations still in their decks. The team with the highest combined total wins the game."},{"type":"p","text":"In case of alternative win or loss conditions, they are shared by the players."}],"multiplayer":[{"type":"h2","text":"Multiplayer Modes"},{"type":"h2","text":"Free-for-All"},{"type":"p","text":"Mode for 3 to 5 players to confront each other at the same time. It is the ideal format for a more casual and unpredictable gaming experience. The base rules of Kartomantik remain valid, with the following modifications and additions."},{"type":"h2","text":"2vs2 Mode"},{"type":"p","text":"Four-player mode for a team confrontation. It is designed for those seeking a group dynamic based on coordination between teammates. The base rules remain valid, with the following modifications and additions."},{"type":"h3","text":"Deck Building"},{"type":"p","text":"Each deck must be composed of exactly 21 cards."},{"type":"p","text":"The sum of the Points of all Manifestations in the deck must not exceed 400."},{"type":"p","text":"As in the base rules, there cannot be more than one copy of the same card in your own deck."}],"bazaar":[{"type":"h2","text":"Bazaar Draft Mode"},{"type":"p","text":"Auction draft mode for 2-6 players. Players compete to acquire the most valuable cards through a free auction system, then face off in a tournament where each player challenges every other player exactly once. Victory is measured by the ability to accumulate points across all tournament matches."},{"type":"h3","text":"Draft Preparation"},{"type":"h4","text":"Dividing the Cards"},{"type":"p","text":"Separate all cards from the set into 4 distinct piles:"},{"type":"p","text":"Wills Pile: All Will cards (Ephemeral and Persistent)"},{"type":"p","text":"Minor Manifestations Pile: Manifestations from 0 to 15 Points."},{"type":"p","text":"Medium Manifestations Pile: Manifestations from 20 to 35 Points."},{"type":"p","text":"Major Manifestations Pile: Manifestations from 40 to 50 Points."},{"type":"p","text":"Shuffle each pile thoroughly."},{"type":"note","text":"NOTE: The composition of the piles can be modified based on the group's preferences. For example, it is recommended to remove the cards \"Atavic Fury\" (235), \"Atavic Volatility\" (188), \"Atavic Oppression\" (141), \"Atavic Introspection\" (94), \"Atavic Welcome\" (47), and all multi-temperament Persistent Wills to better balance the draft. You can customize which cards to include in each pile, as long as there are enough cards to complete the draft with the expected number of players."},{"type":"h4","text":"Creating the Draft Deck"},{"type":"p","text":"Based on the number of players, draw the indicated number of cards from each pile according to this table:"},{"type":"p","text":"Players"},{"type":"p","text":"Wills"},{"type":"p","text":"Manif. 0-15"},{"type":"p","text":"Manif. 20-35"},{"type":"p","text":"Manif. 40-50"},{"type":"p","text":"Total"},{"type":"p","text":"2"},{"type":"p","text":"24"},{"type":"p","text":"18"},{"type":"p","text":"21"},{"type":"p","text":"9"},{"type":"p","text":"72"},{"type":"p","text":"3"},{"type":"p","text":"36"},{"type":"p","text":"27"},{"type":"p","text":"32"},{"type":"p","text":"13"},{"type":"p","text":"108"},{"type":"p","text":"4"},{"type":"p","text":"48"},{"type":"p","text":"36"},{"type":"p","text":"42"},{"type":"p","text":"18"},{"type":"p","text":"144"},{"type":"p","text":"5"},{"type":"p","text":"60"},{"type":"p","text":"45"},{"type":"p","text":"53"},{"type":"p","text":"22"},{"type":"p","text":"180"},{"type":"p","text":"6"},{"type":"p","text":"72"},{"type":"p","text":"54"},{"type":"p","text":"63"},{"type":"p","text":"27"},{"type":"p","text":"216"},{"type":"p","text":"Combine all the drawn cards into a single deck and shuffle it thoroughly. This will be the Draft Deck."},{"type":"h3","text":"Playing the Draft"},{"type":"h4","text":"Uncovering Phase"},{"type":"p","text":"Uncover and place a number of cards from the Draft Deck onto the table equal to twice the number of players (e.g., 3 players = 6 uncovered cards, 4 players = 8 uncovered cards, etc.)."},{"type":"p","text":"Determine the starting order with a die roll (whoever rolls higher goes first). Proceed clockwise from that player."},{"type":"h4","text":"Selection and Auction Phase"},{"type":"p","text":"Player Turn:"},{"type":"p","text":"The active player chooses one of the uncovered cards on the table. This opens an auction for that card."},{"type":"p","text":"Any other player can start the auction by making a bid (minimum 5 Points, or any multiple of 5)."},{"type":"p","text":"The auction proceeds with players taking turns bidding, following these rules:"},{"type":"p","text":"Other players: Can only raise the bid, offering an amount higher than the current bid (each bid must be in increments of 5 Points). There is no limit to the points that can be bid by a player."},{"type":"p","text":"Active player: Has a special right. After each bid from another player, they can choose to match the bid to become the highest bidder, or raise it themselves."},{"type":"p","text":"The auction ends when, after a bid has been made, all other players choose to \"pass\" and not raise the bid."},{"type":"p","text":"If no one made a bid, the active player takes the card for free."},{"type":"p","text":"Otherwise, the player with the final highest bid wins the card and notes down the Points spent, which will be used in the Debt Calculation."},{"type":"p","text":"If the active player lost the auction, they take another turn by immediately choosing another card. Otherwise, the turn passes to the next player."},{"type":"p","text":"Snake Draft Order:"},{"type":"p","text":"The draft follows a snake draft order to balance the advantage of choice. This pattern applies only within a single set of uncovered cards and resets each time the table is refilled."},{"type":"p","text":"Example with 4 players (A, B, C, D):The selection for each group of uncovered cards proceeds as follows:"},{"type":"p","text":"Round 1 (Clockwise): The first player (A) chooses a card, followed by the second, and so on, up to the last player of the round (D): (A → B → C → D)"},{"type":"p","text":"Round 2 (Counter-clockwise): The last player (D), who just chose their first card, immediately starts the second round by choosing another. The order then proceeds in reverse. (D → C → B → A)"},{"type":"p","text":"For the next set of cards, players start again from the first player as in Round 1, and so on."},{"type":"p","text":"Acquisition Limit:"},{"type":"p","text":"Each player can acquire a maximum of 2 cards before the table is refilled."},{"type":"p","text":"When it is the turn of a player who has already taken 2 cards, that player skips their turn and cannot participate in auctions until the table is refilled."},{"type":"h4","text":"Refilling the Table"},{"type":"p","text":"When all the uncovered cards have been taken, uncover new cards from the Draft Deck (a number equal to twice the number of players)."},{"type":"h4","text":"Conclusion of the Draft"},{"type":"p","text":"The draft ends when:"},{"type":"p","text":"The Draft Deck is depleted."},{"type":"p","text":"Each player has acquired exactly 36 cards."},{"type":"p","text":"After the draft, each player builds a deck of exactly 30 cards, only one copy of each, from the 36 they acquired. Unlike the standard mode, there is no limit to the total Points the deck can contain."},{"type":"h3","text":"Debt Calculation"},{"type":"p","text":"Before the tournament begins, each player calculates their Debt:"},{"type":"p","text":"Sum the Points of all Manifestations in your 30-card deck."},{"type":"p","text":"Sum all the Points spent in auctions during the draft."},{"type":"p","text":"Add the two previous values together."},{"type":"p","text":"If this total exceeds 500 Points, the excess amount is counted as Debt and must be recorded."},{"type":"p","text":"Example: A player has a deck with a total of 480 Points and spent 100 points in auctions. The total is 580 Points (480 Manifestation Points + 100 auction Points = 580 total Points). Since the player exceeded the 500-Point threshold by 80, they will have a Debt of 80 points."},{"type":"h3","text":"Tournament and Victory Condition"},{"type":"p","text":"Each player faces every other player exactly once. The matches follow the standard Kartomantik rules."},{"type":"p","text":"At the end of the tournament, each player sums up all the points earned in all matches played and subtracts their Debt points from this total.The player with the highest final score wins the draft."},{"type":"p","text":"In the event of a tie between two or more players, the tied players face off in a tiebreaker match."}],"keywords":[{"type":"h2","text":"Keywords"},{"type":"p","text":"About to: A special timing, which interrupts the normal flow of the game to apply effects, just before the event that is \"about to\" happen occurs."},{"type":"p","text":"Base Power: The power value printed on the card, before any modifier."},{"type":"p","text":"Cancel: The canceled effect cannot be resolved."},{"type":"p","text":"Chain: Put a manifestation under your control into Support. Once it has entered the field, it is considered played and Chained."},{"type":"p","text":"Conceal: A Concealed card is placed face-down in the zone specified by the effect. As long as it is Concealed, all its characteristics, except the Type, can be consulted only by its controller."},{"type":"p","text":"Confrontation Zone: Shared zone where all manifestations that are played and put into the Confrontation are placed."},{"type":"p","text":"Controller: The controller is the player who can play and activate the effects of the cards. If a player controls a card of which they are not the owner, when the card leaves the field or the Stalemate Zone, it returns under the control of its owner."},{"type":"p","text":"Copy: Creates a copy of a card. Unless specified otherwise, the copy has only the original printed characteristics of the copied card (name, temperament, cost, power, text) and does not inherit modifiers or counters. Copies are not considered Played."},{"type":"p","text":"Counter: Object to mark changes given by effects on a card."},{"type":"p","text":"Currently: At the moment in which the card or effect resolves on the Stack."},{"type":"p","text":"Destroy: Put the destroyed card into its owner's Limbo."},{"type":"p","text":"Discard: Put the Discarded cards into the Limbo from the hand or from the deck."},{"type":"p","text":"Empathic Vessel: Zone where the opposing Manifestations that have lost the Confrontation are accumulated."},{"type":"p","text":"Ephemeral Wills: Cards that can be played by paying a tribute. They can be played in response after Revelation. Once their effect resolves on the Stack, they are moved to the Limbo."},{"type":"p","text":"Exhaust: Rotate the card horizontally. It cannot be Exhausted again until the card is Restored, at the beginning of the turn or via effects."},{"type":"p","text":"Exile: Put the card in its owner's exile zone, making it inaccessible for the rest of the game."},{"type":"p","text":"Field: The Cartomantic Field, the game zone that comprises the Interzone, the Confrontation, and in which played Persistent Wills are placed."},{"type":"p","text":"First Manifestation: The manifestation that was played at Revelation by its controller. If that card leaves the Confrontation, its controller must choose another of their manifestations in the Confrontation as the new First Manifestation. If a player controls no manifestations in the Confrontation Zone, at the moment they play or put a manifestation into Support, the latter enters as the First Manifestation."},{"type":"p","text":"Gain/Lose Points: Add or remove the specified value to the total points of the player's Empathic Vessel. Points in the Empathic Vessel can also go into the negative and are independent of the points of captured manifestations."},{"type":"p","text":"Gets -/+ power: Decrease or increase the power of the manifestation; the manifestation remains the same Temperament. When a manifestation reaches 0 power or less it is destroyed."},{"type":"p","text":"Immediate Effect: An effect to which it is not possible to respond; it resolves on the Stack with priority over other effects. If an Immediate Effect triggers at Revelation, it triggers and resolves on the Stack before other Triggered effects have the opportunity to enter the Stack."},{"type":"p","text":"Immunity: Immune cards and players are not influenced in any way by the specified source."},{"type":"p","text":"in Support: Any manifestation that is in the Confrontation Zone, and entered while a First Manifestation was already present, is defined as \"in Support\"."},{"type":"p","text":"Interzone: Zone where the player can place up to 3 of their Manifestations that have won a Confrontation to continue exploiting their effects as Support, or passive and triggered effects that require the manifestation to be \"on the field\". Those Manifestations can be replaced by putting them at the bottom of one's Deck every time another one would enter."},{"type":"p","text":"Limbo: Zone where resolved Ephemeral Wills, Manifestations used as a Tribute, and destroyed cards are placed."},{"type":"p","text":"Modifier: Any temporary or permanent change to the characteristics of a card (power, temperament, etc.) caused by an effect."},{"type":"p","text":"Neutralize: Cancel the effect of the neutralized card and send it to its owner's Limbo."},{"type":"p","text":"Owner: You are always the Owner of all the cards that are in your deck at the beginning of the game."},{"type":"p","text":"Persist: If a manifestation with Persist has won the confrontation, it remains in the Confrontation Zone as a First Manifestation."},{"type":"p","text":"Persistent Wills: Cards that can be played by paying a tribute. They can be played only on an empty Stack during the End Phase and, once they resolve on the Stack, they enter the field. As a requirement for the activation of their effects, all persistent wills must be on the field."},{"type":"p","text":"Points: If not specified \"of a manifestation\" it refers to the points in the Empathic Vessel."},{"type":"p","text":"Protection: Protected cards and players cannot be chosen as targets by the specified source. Protected manifestations cannot obtain Modifiers from the specified source."},{"type":"p","text":"Reduce: Decrease the power of the manifestation. It is an alternative cost for the activation of the effects of some cards, therefore it is not considered as a decrease in power via cards or effects."},{"type":"p","text":"Restore: Return an Exhausted card to a vertical position. That card can be Exhausted again."},{"type":"p","text":"Sacrifice: Put your sacrificed manifestation into the Limbo as the cost of an effect."},{"type":"p","text":"Show: Show the card (or cards) to your opponent and then put it back in its original zone, unless the effect specifies otherwise."},{"type":"p","text":"Stalemate Zone: Special zone where the Manifestations involved in a Stalemate are placed. Controller and Modifiers remain unchanged."},{"type":"p","text":"Support: A manifestation with Support can enter the Confrontation, from the hand or from the Interzone, after the First Manifestation. If \"from the hand\" is specified it can be played in Support exclusively from the hand."},{"type":"p","text":"Target: The element (a card, a player, etc.) that the controller of the effect or card must choose for it to have an effect."},{"type":"p","text":"Token: A manifestation or a will created by the effects of other cards. If a token leaves the Cartomantic Field it is exiled. Unless specified otherwise, manifestation tokens are exiled at Resolution."},{"type":"p","text":"Uncover: Put one or more cards face-up."}],"errata":[{"type":"h2","text":"Integrations and Errata"},{"type":"p","text":"Updates regarding the transition to the Beta edition of Kartomantik. Below are the main new features:"},{"type":"p","text":"Multiplayer Support: The card design has been prepared for the integration of multiplayer modes."},{"type":"p","text":"New Keywords: To streamline the text and improve readability, some recurring mechanics have been summarized into the following keywords: \"Once per turn\" - Exhaust; \"Play as if it had support\" - Chain."},{"type":"p","text":"Targets: To reduce the ambiguity of effects, the word \"target\" has been added to cards that required one to be chosen."},{"type":"p","text":"Text Reworks: Several cards have undergone modifications to improve their balance. You can consult the list of the most important changes below."},{"type":"p","text":"Main Changes"},{"type":"p","text":"N°"},{"type":"p","text":"Name"},{"type":"p","text":"Type"},{"type":"p","text":"Pts"},{"type":"p","text":"Temperament"},{"type":"p","text":"Power/Cost"},{"type":"p","text":"Previous Text"},{"type":"p","text":"Updated Text"},{"type":"p","text":"80"},{"type":"p","text":"Blue Entity"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"45"},{"type":"p","text":"💧💧💧"},{"type":"p","text":"As long as Blue Entity is on the field, whenever you play a will, all manifestations on the field you control gain +1 power until the end of the turn."},{"type":"p","text":"As long as the Blue Entity is in the Confrontation Zone, whenever you play a Will, all other manifestations in the Confrontation Zone you control get +1 power until the end of the turn."},{"type":"p","text":"83"},{"type":"p","text":"Glimpse the Omens"},{"type":"p","text":"Ephemeral Will"},{"type":"p","text":"/"},{"type":"p","text":"💧💧"},{"type":"p","text":"Look at the top 4 cards of your deck. Put those cards on the top or bottom of your deck in any order, then draw 3 cards."},{"type":"p","text":"Look at the top 4 cards of your deck. Distribute any number of those cards on the top and on the bottom of your deck in any order, then draw 1 card."},{"type":"p","text":"81"},{"type":"p","text":"Malaleuco, the Will-Shaper"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"50"},{"type":"p","text":"💧💧"},{"type":"p","text":"As long as Malaleuco is in the Interzone, whenever you play a will, you may copy it. You may choose new targets for the copy."},{"type":"p","text":"If Malaleuco is in your hand and there is space in your Interzone, you may pay 💧💧💧💧: if you do, put it into your Interzone."},{"type":"p","text":"As long as Malaleuco is in the Interzone, you can exhaust it to copy a Will on the stack that you control. You can choose a new target for the copy."},{"type":"p","text":"If Malaleuco is in hand and there is space in your Interzone, you can pay💧💧💧: Put it in your Interzone."},{"type":"p","text":"76"},{"type":"p","text":"Shymon, the Mastermind"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"35"},{"type":"p","text":"💧💧💧💧"},{"type":"p","text":"As long as Shymon is on the field, once per turn, it may get -2 power: the opponent does not draw in the next Replenishment Phase."},{"type":"p","text":"As long as it is on the field, you can exhaust Shymon and reduce its power by 2: Next turn, a target opponent cannot draw cards outside of the Recovery Phase until the end of that turn."},{"type":"p","text":"184"},{"type":"p","text":"Deviate"},{"type":"p","text":"Ephemeral Will"},{"type":"p","text":"/"},{"type":"p","text":"⚡⚡"},{"type":"p","text":"Destroy a manifestation that is about to enter an Empathic Vessel."},{"type":"p","text":"Lose 5 points."},{"type":"p","text":"You can play this Will only during the Resolution."},{"type":"p","text":"Destroy a target manifestation in the Confrontation Zone that lost the confrontation this turn."},{"type":"p","text":"175"},{"type":"p","text":"Katun, the Inconsistent"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"50"},{"type":"p","text":"⚡⚡⚡⚡⚡"},{"type":"p","text":"As long as Katun is in the Interzone, whenever a manifestation leaves the field, a Limbo, an Empathic Vessel, or a Stalemate Zone due to the effect of a card you control, gain 5 points."},{"type":"p","text":"If Katun was instead recovered from an Empathic Vessel, whenever you trigger its effects, gain 10 points."},{"type":"p","text":"As long as Katun is in the Interzone, whenever a manifestation leaves the field, a Limbo, an Empathic Vessel or the Stalemate Zone due to cards or effects, you gain 5 points."},{"type":"p","text":"If Katun has left an Empathic Vessel during the course of the game, instead whenever you trigger its effects you gain 10 points."},{"type":"p","text":"206"},{"type":"p","text":"Gorb, the Musclebound"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"25"},{"type":"p","text":"🔥🔥🔥🔥🔥🔥"},{"type":"p","text":"When Gorb enters the field, you cannot play manifestations as support until the end of the turn."},{"type":"p","text":"When Gorb enters the field, you cannot put manifestations in Support under your control until the end of the turn."},{"type":"p","text":"208"},{"type":"p","text":"Numbi, the Irritating"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"25"},{"type":"p","text":"🔥🔥🔥🔥"},{"type":"p","text":"As long as Numbi is in the Interzone, after Revelation you may force the opponent to play a manifestation from their hand as if it had Support. If the opponent cannot do so, they show you their hand."},{"type":"p","text":"As long as Numbi is in the Interzone, after the Revelation you may force a target opponent to Chain from their hand. If the opponent can do so, the First Manifestation you control gets +2 power until the end of the turn. If the opponent cannot do so, they reveal their hand."},{"type":"p","text":"211"},{"type":"p","text":"Quorum, the Untouchable"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"30"},{"type":"p","text":"🔥🔥"},{"type":"p","text":"When Quorum enters the field, you may discard any number of wills from your hand: Quorum gets +3 power for each will discarded this way."},{"type":"p","text":"When Quorum enters the field, you may discard any number of Wills from your hand. Quorum gets +3 power until the end of the turn for each Will discarded this way."},{"type":"p","text":"42"},{"type":"p","text":"Altruistic Inflorescence"},{"type":"p","text":"Persistent Will"},{"type":"p","text":"/"},{"type":"p","text":"🌿🌿🌿"},{"type":"p","text":"A manifestation on the field has Support in addition to its other effects."},{"type":"p","text":"When Altruistic Inflorescence enters the field, choose a target manifestation on the field. That manifestation has Support in addition to its other effects."},{"type":"p","text":"In the End Phase, you may exhaust this card and pay 🌿🌿🌿: Change the target of this card's effect"},{"type":"p","text":"35"},{"type":"p","text":"Gargullo, King of the Woods"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"50"},{"type":"p","text":"🌿"},{"type":"p","text":"As long as Gargullo is on the field, each manifestation in Support you control gets +1 power during the confrontation for each other manifestation you control in the confrontation."},{"type":"p","text":"As long as Gargullo is on the field, during the confrontation each non-token manifestation in Support you control gets +1 power for each other non-token manifestation you control in the Confrontation Zone."},{"type":"p","text":"37"},{"type":"p","text":"Plea for Generosity"},{"type":"p","text":"Ephemeral Will"},{"type":"p","text":"/"},{"type":"p","text":"🌿🌿"},{"type":"p","text":"Gain 5 points for each manifestation in a confrontation."},{"type":"p","text":"Gain 5 points for each non-token manifestation in the Confrontation Zone under the control of a target player."},{"type":"p","text":"21"},{"type":"p","text":"Spontaneous Incubator"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"25"},{"type":"p","text":"🌿🌿🌿🌿"},{"type":"p","text":"As long as Spontaneous Incubator is in the Interzone, at the beginning of the turn, you gain 5 points."},{"type":"p","text":"As long as Spontaneous Incubator is in the Interzone, at the beginning of the turn you gain 10 points."},{"type":"p","text":"33"},{"type":"p","text":"Tong, the Expansive"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"45"},{"type":"p","text":"🌿🌿🌿🌿"},{"type":"p","text":"🌿🌿🌿🌿🌿🌿"},{"type":"p","text":"As long as Tong is on the field, increase the spaces in your Interzone by 3."},{"type":"p","text":"/"},{"type":"p","text":"128"},{"type":"p","text":"Ergorath, Scribe of the Limbo"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"50"},{"type":"p","text":"🔮"},{"type":"p","text":"As long as Ergorath is on the field, you may play wills from your Limbo by paying 1 🔘 instead of their normal tribute cost."},{"type":"p","text":"If the wills played this way would enter a Limbo, a hand or a deck, instead exile them."},{"type":"p","text":"As long as Ergorath is on the field, you may play Wills from your Limbo by paying 1 🔘 instead of their normal tribute cost."},{"type":"p","text":"If the Wills played this way are about to enter a Limbo, a hand or a deck, exile them instead."},{"type":"p","text":"If at the end of the turn Ergorath is in the Interzone, its controller loses 10 points, then it is shuffled into its owner's deck."},{"type":"p","text":"138"},{"type":"p","text":"Flaying Jaw"},{"type":"p","text":"Persistent Will"},{"type":"p","text":"/"},{"type":"p","text":"🔮🔮"},{"type":"p","text":"When Flaying Jaw enters the field, choose a manifestation on the field."},{"type":"p","text":"That manifestation gets -2 power at the end of the turn."},{"type":"p","text":"In the End Phase, once per turn, you may pay 🔮: Change the target of this will."},{"type":"p","text":"When Flaying Jaw enters the field, choose a target manifestation on the field."},{"type":"p","text":"That manifestation gets -2 power."},{"type":"p","text":"In the End Phase, you may exhaust this card and pay 🔮: Change the target of this card's effect."},{"type":"p","text":"114"},{"type":"p","text":"Lament, Thought-Nullifier"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"25"},{"type":"p","text":"🔮🔮"},{"type":"p","text":"Support from hand."},{"type":"p","text":"Cannot be played as First Manifestation."},{"type":"p","text":"When Lament enters a confrontation, each player discards a card from the top of their deck for each manifestation you control in that confrontation."},{"type":"p","text":"Support from hand."},{"type":"p","text":"Cannot be played as First Manifestation."},{"type":"p","text":"When Lament enters the Confrontation Zone, a target player discards a card from the top of their deck for each non-token manifestation they control in the Confrontation Zone"},{"type":"p","text":"109"},{"type":"p","text":"Possessed Pyramid"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"20"},{"type":"p","text":"🔮"},{"type":"p","text":"Support from hand."},{"type":"p","text":"When Possessed Pyramid enters an opponent's Empathic Vessel, that player skips the next Replenishment Phase."},{"type":"p","text":"Support from hand."},{"type":"p","text":"When the Possessed Pyramid enters an opponent's Empathic Vessel, the next turn that player's hand is reduced by 1. During that turn, any excess card in their hand must be immediately discarded."},{"type":"p","text":"241"},{"type":"p","text":"Alchemical Press"},{"type":"p","text":"Persistent Will"},{"type":"p","text":"/"},{"type":"p","text":"💧💧🔮🔮"},{"type":"p","text":"You may use manifestations in your Limbo to pay tributes. If you do, exile them."},{"type":"p","text":"Whenever you play a will, you may draw a card. If you do, discard a card from your hand."},{"type":"p","text":"The Alchemical Press enters the field with 5 Formula counters on it."},{"type":"p","text":"As long as there are Formula counters on the Alchemical Press, you can use the manifestations in your Limbo to pay tributes. If you do, exile that manifestation and remove a Formula counter from the Alchemical Press."},{"type":"p","text":"Whenever you play a Will, you can discard a card. If you do, draw a card."},{"type":"p","text":"244"},{"type":"p","text":"Extortionist Womb"},{"type":"p","text":"Persistent Will"},{"type":"p","text":"/"},{"type":"p","text":"🔥🔥 🌿🌿"},{"type":"p","text":"After Revelation, the opponent may choose to show you their hand. If they do, you choose a manifestation from it, the opponent must play it as if it had Support. If the opponent does not show you their hand or cannot play manifestations, you may put a 🔘 token with 2 power into the confrontation as Support."},{"type":"p","text":"After the Revelation, a target opponent can show you their hand. If they do, choose a manifestation inside it, the opponent Chains that manifestation. If the opponent does not show you their hand or if they cannot Chain, put 2 tokens with 2 power 🔘 in Support."},{"type":"p","text":"250"},{"type":"p","text":"Qu Lom, Haphazard Martyr"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"25"},{"type":"p","text":"🌈🌈"},{"type":"p","text":"Whenever Qu Lom is used as a tribute, roll a D6: if the result of the roll is even, return Qu Lom to your hand from your Limbo."},{"type":"p","text":"When Qu Lom is used as tribute, at the end of that turn roll a D6. If the result of the roll is even, Qu Lom returns to its owner's hand from the Limbo. If the result of the roll is odd, it is exiled instead."},{"type":"p","text":"264"},{"type":"p","text":"Gummo"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"40"},{"type":"p","text":"🔘🔘🔘"},{"type":"p","text":"As long as Gummo is in the Interzone:"},{"type":"p","text":"· Once per turn, during the End Phase, you may choose a random manifestation in your Empathic Vessel: Gummo copies its base power and gets its effects in addition to its own until this effect is reactivated."},{"type":"p","text":"· Before Revelation, you may pay 🔘🔘🔘: Gummo enters the confrontation as First Manifestation."},{"type":"p","text":"As long as Gummo is in the Interzone, at the end of the turn you may choose a manifestation in your Empathic Vessel. If you do, Gummo copies its base power and gains its effects in addition to its own until this effect is reused."},{"type":"p","text":"Before the Revelation, you may pay 🔘🔘🔘: Gummo enters the Confrontation Zone as First Manifestation from the Interzone."},{"type":"p","text":"284"},{"type":"p","text":"Martyrize"},{"type":"p","text":"Ephemeral Will"},{"type":"p","text":"/"},{"type":"p","text":"🔘"},{"type":"p","text":"Show and discard a manifestation from your hand, draw a number of cards equal to its base power."},{"type":"p","text":"As an additional cost to play this Will, reveal and exile a manifestation from your hand. Draw a number of cards equal to the base power of the revealed manifestation, then exile this Will."},{"type":"p","text":"257"},{"type":"p","text":"Rocky Heartcrystal"},{"type":"p","text":"Manifesta-tion"},{"type":"p","text":"10"},{"type":"p","text":"15"},{"type":"p","text":"🔘🔘"},{"type":"p","text":"When Rocky Heartcrystal is used as tribute, it is considered to be of 🌈 temperament."},{"type":"p","text":"/"},{"type":"h2","text":"Authors’ Note"}]}},"provenance":{"fr":"Kartomantik - Livret de règles FR.docx","en":"index en.odt","it":"Official Italian illustrated booklet"}};
